    "وَأَدْخَلْنَٰهُ فِى رَحْمَتِنَآ  إِنَّهُۥ مِنَ الصَّٰلِحِينَ",
    "وَنُوحًا إِذْ نَادَىٰ مِن قَبْلُ فَاسْتَجَبْنَا لَهُۥ فَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ الْكَرْبِ الْعَظِيمِ",
    "وَنَصَرْنَٰهُ مِنَ الْقَوْمِ الَّذِينَ كَذَّبُوا بَِٔايَٰتِنَآ  إِنَّهُمْ كَانُوا قَوْمَ سَوْءٍ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ",
    "وَدَاوُۥدَ وَسُلَيْمَٰنَ إِذْ يَحْكُمَانِ فِى الْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ الْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَٰهِدِينَ",
    "فَفَهَّمْنَٰهَا سُلَيْمَٰنَ  وَكُلًّا ءَاتَيْنَا حُكْمًا وَعِلْمًا  وَسَخَّرْنَا مَعَ دَاوُۥدَ الْجِبَالَ يُسَبِّحْنَ وَالطَّيْرَ  وَكُنَّا فَٰعِلِينَ",
    "وَعَلَّمْنَٰهُ صَنْعَةَ لَبُوسٍ لَّكُمْ لِتُحْصِنَكُم مِّن بَأْسِكُمْ  فَهَلْ أَنتُمْ شَٰكِرُونَ",
    "وَلِسُلَيْمَٰنَ الرِّيحَ عَاصِفَةً تَجْرِى بِأَمْرِهِۦٓ إِلَى الْأَرْضِ الَّتِى بَٰرَكْنَا فِيهَا  وَكُنَّا بِكُلِّ شَىْءٍ عَٰلِمِينَ",
    "وَمِنَ الشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعْمَلُونَ عَمَلًا دُونَ ذَٰلِكَ  وَكُنَّا لَهُمْ حَٰفِظِينَ",
    "۞ وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّٰحِمِينَ",
    "فَاسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرٍّ  وَءَاتَيْنَٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَٰبِدِينَ",
    "وَإِسْمَٰعِيلَ وَإِدْرِيسَ وَذَا الْكِفْلِ  كُلٌّ مِّنَ الصَّٰبِرِينَ",
    "وَأَدْخَلْنَٰهُمْ فِى رَحْمَتِنَآ  إِنَّهُم مِّنَ الصَّٰلِحِينَ",
    "وَذَا النُّونِ إِذ ذَّهَبَ مُغَٰضِبًا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِى الظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ الظَّٰلِمِينَ",
    "فَاسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ الْغَمِّ  وَكَذَٰلِكَ نُجِى الْمُؤْمِنِينَ",
    "وَزَكَرِيَّآ إِذْ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرْنِى فَرْدًا وَأَنتَ خَيْرُ الْوَٰرِثِينَ",
    "فَاسْتَجَبْنَا لَهُۥ وَوَهَبْنَا لَهُۥ يَحْيَىٰ وَأَصْلَحْنَا لَهُۥ زَوْجَهُۥٓ  إِنَّهُمْ كَانُوا يُسَٰرِعُونَ فِى الْخَيْرَٰتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا  وَكَانُوا لَنَا خَٰشِعِينَ",
    "وَالَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِن رُّوحِنَا وَجَعَلْنَٰهَا وَابْنَهَآ ءَايَةً لِّلْعَٰلَمِينَ",
    "إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا رَبُّكُمْ فَاعْبُدُونِ",
    "وَتَقَطَّعُوٓا أَمْرَهُم بَيْنَهُمْ  كُلٌّ إِلَيْنَا رَٰجِعُونَ",
    "فَمَن يَعْمَلْ مِنَ الصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌ فَلَا كُفْرَانَ لِسَعْيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ",
    "وَحَرَٰمٌ عَلَىٰ قَرْيَةٍ أَهْلَكْنَٰهَآ أَنَّهُمْ لَا يَرْجِعُونَ",
    "حَتَّىٰٓ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍ يَنسِلُونَ",
    "وَاقْتَرَبَ الْوَعْدُ الْحَقُّ فَإِذَا هِىَ شَٰخِصَةٌ أَبْصَٰرُ الَّذِينَ كَفَرُوا يَٰوَيْلَنَا قَدْ كُنَّا فِى غَفْلَةٍ مِّنْ هَٰذَا بَلْ كُنَّا ظَٰلِمِينَ",
    "إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ اللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَٰرِدُونَ",
    "لَوْ كَانَ هَٰٓؤُلَآءِ ءَالِهَةً مَّا وَرَدُوهَا  وَكُلٌّ فِيهَا خَٰلِدُونَ",
    "لَهُمْ فِيهَا زَفِيرٌ وَهُمْ فِيهَا لَا يَسْمَعُونَ",
    "إِنَّ الَّذِينَ سَبَقَتْ لَهُم مِّنَّا الْحُسْنَىٰٓ أُولَٰٓئِكَ عَنْهَا مُبْعَدُونَ",
    "لَا يَسْمَعُونَ حَسِيسَهَا  وَهُمْ فِى مَا اشْتَهَتْ أَنفُسُهُمْ خَٰلِدُونَ",
    "لَا يَحْزُنُهُمُ الْفَزَعُ الْأَكْبَرُ وَتَتَلَقَّىٰهُمُ الْمَلَٰٓئِكَةُ هَٰذَا يَوْمُكُمُ الَّذِى كُنتُمْ تُوعَدُونَ",
    "يَوْمَ نَطْوِى السَّمَآءَ كَطَىِّ السِّجِلِّ لِلْكُتُبِ  كَمَا بَدَأْنَآ أَوَّلَ خَلْقٍ نُّعِيدُهُۥ  وَعْدًا عَلَيْنَآ  إِنَّا كُنَّا فَٰعِلِينَ",
    "وَلَقَدْ كَتَبْنَا فِى الزَّبُورِ مِن بَعْدِ الذِّكْرِ أَنَّ الْأَرْضَ يَرِثُهَا عِبَادِىَ الصَّٰلِحُونَ",
    "إِنَّ فِى هَٰذَا لَبَلَٰغًا لِّقَوْمٍ عَٰبِدِينَ",
    "وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةً لِّلْعَٰلَمِينَ",
    "قُلْ إِنَّمَا يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ  فَهَلْ أَنتُم مُّسْلِمُونَ",
    "فَإِن تَوَلَّوْا فَقُلْ ءَاذَنتُكُمْ عَلَىٰ سَوَآءٍ  وَإِنْ أَدْرِىٓ أَقَرِيبٌ أَم بَعِيدٌ مَّا تُوعَدُونَ",
    "إِنَّهُۥ يَعْلَمُ الْجَهْرَ مِنَ الْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ",
    "وَإِنْ أَدْرِى لَعَلَّهُۥ فِتْنَةٌ لَّكُمْ وَمَتَٰعٌ إِلَىٰ حِينٍ",
    "قَٰلَ رَبِّ احْكُم بِالْحَقِّ  وَرَبُّنَا الرَّحْمَٰنُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ",
  ],
  22: [
    "يَٰٓأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ  إِنَّ زَلْزَلَةَ السَّاعَةِ شَىْءٌ عَظِيمٌ",
    "يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّآ أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى النَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ اللَّهِ شَدِيدٌ",
    "وَمِنَ النَّاسِ مَن يُجَٰدِلُ فِى اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّبِعُ كُلَّ شَيْطَٰنٍ مَّرِيدٍ",
    "كُتِبَ عَلَيْهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهْدِيهِ إِلَىٰ عَذَابِ السَّعِيرِ",
    "يَٰٓأَيُّهَا النَّاسُ إِن كُنتُمْ فِى رَيْبٍ مِّنَ الْبَعْثِ فَإِنَّا خَلَقْنَٰكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ مِن مُّضْغَةٍ مُّخَلَّقَةٍ وَغَيْرِ مُخَلَّقَةٍ لِّنُبَيِّنَ لَكُمْ  وَنُقِرُّ فِى الْأَرْحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ نُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا أَشُدَّكُمْ  وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ الْعُمُرِ لِكَيْلَا يَعْلَمَ مِن بَعْدِ عِلْمٍ شَئًْا  وَتَرَى الْأَرْضَ هَامِدَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا الْمَآءَ اهْتَزَّتْ وَرَبَتْ وَأَنبَتَتْ مِن كُلِّ زَوْجٍ بَهِيجٍ",
    "ذَٰلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّهُۥ يُحْىِ الْمَوْتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ",
    "وَأَنَّ السَّاعَةَ ءَاتِيَةٌ لَّا رَيْبَ فِيهَا وَأَنَّ اللَّهَ يَبْعَثُ مَن فِى الْقُبُورِ",
    "وَمِنَ النَّاسِ مَن يُجَٰدِلُ فِى اللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَٰبٍ مُّنِيرٍ",
    "ثَانِىَ عِطْفِهِۦ لِيُضِلَّ عَن سَبِيلِ اللَّهِ  لَهُۥ فِى الدُّنْيَا خِزْىٌ  وَنُذِيقُهُۥ يَوْمَ الْقِيَٰمَةِ عَذَابَ الْحَرِيقِ",
    "ذَٰلِكَ بِمَا قَدَّمَتْ يَدَاكَ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّٰمٍ لِّلْعَبِيدِ",
    "وَمِنَ النَّاسِ مَن يَعْبُدُ اللَّهَ عَلَىٰ حَرْفٍ  فَإِنْ أَصَابَهُۥ خَيْرٌ اطْمَأَنَّ بِهِۦ  وَإِنْ أَصَابَتْهُ فِتْنَةٌ انقَلَبَ عَلَىٰ وَجْهِهِۦ خَسِرَ الدُّنْيَا وَالَْٔاخِرَةَ  ذَٰلِكَ هُوَ الْخُسْرَانُ الْمُبِينُ",
    "يَدْعُوا مِن دُونِ اللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥ  ذَٰلِكَ هُوَ الضَّلَٰلُ الْبَعِيدُ",
    "يَدْعُوا لَمَن ضَرُّهُۥٓ أَقْرَبُ مِن نَّفْعِهِۦ  لَبِئْسَ الْمَوْلَىٰ وَلَبِئْسَ الْعَشِيرُ",
    "إِنَّ اللَّهَ يُدْخِلُ الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَٰرُ  إِنَّ اللَّهَ يَفْعَلُ مَا يُرِيدُ",
    "مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ اللَّهُ فِى الدُّنْيَا وَالَْٔاخِرَةِ فَلْيَمْدُدْ بِسَبَبٍ إِلَى السَّمَآءِ ثُمَّ لْيَقْطَعْ فَلْيَنظُرْ هَلْ يُذْهِبَنَّ كَيْدُهُۥ مَا يَغِيظُ",
    "وَكَذَٰلِكَ أَنزَلْنَٰهُ ءَايَٰتٍ بَيِّنَٰتٍ وَأَنَّ اللَّهَ يَهْدِى مَن يُرِيدُ",
    "إِنَّ الَّذِينَ ءَامَنُوا وَالَّذِينَ هَادُوا وَالصَّٰبِِٔينَ وَالنَّصَٰرَىٰ وَالْمَجُوسَ وَالَّذِينَ أَشْرَكُوٓا إِنَّ اللَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ الْقِيَٰمَةِ  إِنَّ اللَّهَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ",
    "أَلَمْ تَرَ أَنَّ اللَّهَ يَسْجُدُ لَهُۥ مَن فِى السَّمَٰوَٰتِ وَمَن فِى الْأَرْضِ وَالشَّمْسُ وَالْقَمَرُ وَالنُّجُومُ وَالْجِبَالُ وَالشَّجَرُ وَالدَّوَآبُّ وَكَثِيرٌ مِّنَ النَّاسِ  وَكَثِيرٌ حَقَّ عَلَيْهِ الْعَذَابُ  وَمَن يُهِنِ اللَّهُ فَمَا لَهُۥ مِن مُّكْرِمٍ  إِنَّ اللَّهَ يَفْعَلُ مَا يَشَآءُ",
    "۞ هَٰذَانِ خَصْمَانِ اخْتَصَمُوا فِى رَبِّهِمْ  فَالَّذِينَ كَفَرُوا قُطِّعَتْ لَهُمْ ثِيَابٌ مِّن نَّارٍ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ الْحَمِيمُ",
    "يُصْهَرُ بِهِۦ مَا فِى بُطُونِهِمْ وَالْجُلُودُ",
    "وَلَهُم مَّقَٰمِعُ مِنْ حَدِيدٍ",
    "كُلَّمَآ أَرَادُوٓا أَن يَخْرُجُوا مِنْهَا مِنْ غَمٍّ أُعِيدُوا فِيهَا وَذُوقُوا عَذَابَ الْحَرِيقِ",
    "إِنَّ اللَّهَ يُدْخِلُ الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا  وَلِبَاسُهُمْ فِيهَا حَرِيرٌ",
    "وَهُدُوٓا إِلَى الطَّيِّبِ مِنَ الْقَوْلِ وَهُدُوٓا إِلَىٰ صِرَٰطِ الْحَمِيدِ",
    "إِنَّ الَّذِينَ كَفَرُوا وَيَصُدُّونَ عَن سَبِيلِ اللَّهِ وَالْمَسْجِدِ الْحَرَامِ الَّذِى جَعَلْنَٰهُ لِلنَّاسِ سَوَآءً الْعَٰكِفُ فِيهِ وَالْبَادِ  وَمَن يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُّذِقْهُ مِنْ عَذَابٍ أَلِيمٍ",
    "وَإِذْ بَوَّأْنَا لِإِبْرَٰهِيمَ مَكَانَ الْبَيْتِ أَن لَّا تُشْرِكْ بِى شَئًْا وَطَهِّرْ بَيْتِىَ لِلطَّآئِفِينَ وَالْقَآئِمِينَ وَالرُّكَّعِ السُّجُودِ",
    "وَأَذِّن فِى النَّاسِ بِالْحَجِّ يَأْتُوكَ رِجَالًا وَعَلَىٰ كُلِّ ضَامِرٍ يَأْتِينَ مِن كُلِّ فَجٍّ عَمِيقٍ",
    "لِّيَشْهَدُوا مَنَٰفِعَ لَهُمْ وَيَذْكُرُوا اسْمَ اللَّهِ فِىٓ أَيَّامٍ مَّعْلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّن بَهِيمَةِ الْأَنْعَٰمِ  فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَآئِسَ الْفَقِيرَ",
    "ثُمَّ لْيَقْضُوا تَفَثَهُمْ وَلْيُوفُوا نُذُورَهُمْ وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ",
    "ذَٰلِكَ وَمَن يُعَظِّمْ حُرُمَٰتِ اللَّهِ فَهُوَ خَيْرٌ لَّهُۥ عِندَ رَبِّهِۦ  وَأُحِلَّتْ لَكُمُ الْأَنْعَٰمُ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ  فَاجْتَنِبُوا الرِّجْسَ مِنَ الْأَوْثَٰنِ وَاجْتَنِبُوا قَوْلَ الزُّورِ",
    "حُنَفَآءَ لِلَّهِ غَيْرَ مُشْرِكِينَ بِهِۦ  وَمَن يُشْرِكْ بِاللَّهِ فَكَأَنَّمَا خَرَّ مِنَ السَّمَآءِ فَتَخْطَفُهُ الطَّيْرُ أَوْ تَهْوِى بِهِ الرِّيحُ فِى مَكَانٍ سَحِيقٍ",
    "ذَٰلِكَ وَمَن يُعَظِّمْ شَعَٰٓئِرَ اللَّهِ فَإِنَّهَا مِن تَقْوَى الْقُلُوبِ",
    "لَكُمْ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ مَحِلُّهَآ إِلَى الْبَيْتِ الْعَتِيقِ",
    "وَلِكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا لِّيَذْكُرُوا اسْمَ اللَّهِ عَلَىٰ مَا رَزَقَهُم مِّن بَهِيمَةِ الْأَنْعَٰمِ  فَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَلَهُۥٓ أَسْلِمُوا  وَبَشِّرِ الْمُخْبِتِينَ",
    "الَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ وَالصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمْ وَالْمُقِيمِى الصَّلَوٰةِ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ",
    "وَالْبُدْنَ جَعَلْنَٰهَا لَكُم مِّن شَعَٰٓئِرِ اللَّهِ لَكُمْ فِيهَا خَيْرٌ  فَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهَا صَوَآفَّ  فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا مِنْهَا وَأَطْعِمُوا الْقَانِعَ وَالْمُعْتَرَّ  كَذَٰلِكَ سَخَّرْنَٰهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ",
    "لَن يَنَالَ اللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ التَّقْوَىٰ مِنكُمْ  كَذَٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا اللَّهَ عَلَىٰ مَا هَدَىٰكُمْ  وَبَشِّرِ الْمُحْسِنِينَ",
    "۞ إِنَّ اللَّهَ يُدَٰفِعُ عَنِ الَّذِينَ ءَامَنُوٓا  إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٍ كَفُورٍ",
    "أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمْ ظُلِمُوا  وَإِنَّ اللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ",
    "الَّذِينَ أُخْرِجُوا مِن دِيَٰرِهِم بِغَيْرِ حَقٍّ إِلَّآ أَن يَقُولُوا رَبُّنَا اللَّهُ  وَلَوْلَا دَفْعُ اللَّهِ النَّاسَ بَعْضَهُم بِبَعْضٍ لَّهُدِّمَتْ صَوَٰمِعُ وَبِيَعٌ وَصَلَوَٰتٌ وَمَسَٰجِدُ يُذْكَرُ فِيهَا اسْمُ اللَّهِ كَثِيرًا  وَلَيَنصُرَنَّ اللَّهُ مَن يَنصُرُهُۥٓ  إِنَّ اللَّهَ لَقَوِىٌّ عَزِيزٌ",
    "الَّذِينَ إِن مَّكَّنَّٰهُمْ فِى الْأَرْضِ أَقَامُوا الصَّلَوٰةَ وَءَاتَوُا الزَّكَوٰةَ وَأَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنِ الْمُنكَرِ  وَلِلَّهِ عَٰقِبَةُ الْأُمُورِ",
    "وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَثَمُودُ",
    "وَقَوْمُ إِبْرَٰهِيمَ وَقَوْمُ لُوطٍ",
    "وَأَصْحَٰبُ مَدْيَنَ  وَكُذِّبَ مُوسَىٰ فَأَمْلَيْتُ لِلْكَٰفِرِينَ ثُمَّ أَخَذْتُهُمْ  فَكَيْفَ كَانَ نَكِيرِ",
    "فَكَأَيِّن مِّن قَرْيَةٍ أَهْلَكْنَٰهَا وَهِىَ ظَالِمَةٌ فَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئْرٍ مُّعَطَّلَةٍ وَقَصْرٍ مَّشِيدٍ",
    "أَفَلَمْ يَسِيرُوا فِى الْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَآ أَوْ ءَاذَانٌ يَسْمَعُونَ بِهَا  فَإِنَّهَا لَا تَعْمَى الْأَبْصَٰرُ وَلَٰكِن تَعْمَى الْقُلُوبُ الَّتِى فِى الصُّدُورِ",
    "وَيَسْتَعْجِلُونَكَ بِالْعَذَابِ وَلَن يُخْلِفَ اللَّهُ وَعْدَهُۥ  وَإِنَّ يَوْمًا عِندَ رَبِّكَ كَأَلْفِ سَنَةٍ مِّمَّا تَعُدُّونَ",
    "وَكَأَيِّن مِّن قَرْيَةٍ أَمْلَيْتُ لَهَا وَهِىَ ظَالِمَةٌ ثُمَّ أَخَذْتُهَا وَإِلَىَّ الْمَصِيرُ",
    "قُلْ يَٰٓأَيُّهَا النَّاسُ إِنَّمَآ أَنَا لَكُمْ نَذِيرٌ مُّبِينٌ",
    "فَالَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ",
    "وَالَّذِينَ سَعَوْا فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُولَٰٓئِكَ أَصْحَٰبُ الْجَحِيمِ",
    "وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ وَلَا نَبِىٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلْقَى الشَّيْطَٰنُ فِىٓ أُمْنِيَّتِهِۦ فَيَنسَخُ اللَّهُ مَا يُلْقِى الشَّيْطَٰنُ ثُمَّ يُحْكِمُ اللَّهُ ءَايَٰتِهِۦ  وَاللَّهُ عَلِيمٌ حَكِيمٌ",
    "لِّيَجْعَلَ مَا يُلْقِى الشَّيْطَٰنُ فِتْنَةً لِّلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَالْقَاسِيَةِ قُلُوبُهُمْ  وَإِنَّ الظَّٰلِمِينَ لَفِى شِقَاقٍ بَعِيدٍ",
    "وَلِيَعْلَمَ الَّذِينَ أُوتُوا الْعِلْمَ أَنَّهُ الْحَقُّ مِن رَّبِّكَ فَيُؤْمِنُوا بِهِۦ فَتُخْبِتَ لَهُۥ قُلُوبُهُمْ  وَإِنَّ اللَّهَ لَهَادِ الَّذِينَ ءَامَنُوٓا إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ",
    "وَلَا يَزَالُ الَّذِينَ كَفَرُوا فِى مِرْيَةٍ مِّنْهُ حَتَّىٰ تَأْتِيَهُمُ السَّاعَةُ بَغْتَةً أَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَقِيمٍ",
    "الْمُلْكُ يَوْمَئِذٍ لِّلَّهِ يَحْكُمُ بَيْنَهُمْ  فَالَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ فِى جَنَّٰتِ النَّعِيمِ",
    "وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بَِٔايَٰتِنَا فَأُولَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ",
    "وَالَّذِينَ هَاجَرُوا فِى سَبِيلِ اللَّهِ ثُمَّ قُتِلُوٓا أَوْ مَاتُوا لَيَرْزُقَنَّهُمُ اللَّهُ رِزْقًا حَسَنًا  وَإِنَّ اللَّهَ لَهُوَ خَيْرُ الرَّٰزِقِينَ",
    "لَيُدْخِلَنَّهُم مُّدْخَلًا يَرْضَوْنَهُۥ  وَإِنَّ اللَّهَ لَعَلِيمٌ حَلِيمٌ",
    "۞ ذَٰلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِىَ عَلَيْهِ لَيَنصُرَنَّهُ اللَّهُ  إِنَّ اللَّهَ لَعَفُوٌّ غَفُورٌ",
    "ذَٰلِكَ بِأَنَّ اللَّهَ يُولِجُ الَّيْلَ فِى النَّهَارِ وَيُولِجُ النَّهَارَ فِى الَّيْلِ وَأَنَّ اللَّهَ سَمِيعٌ بَصِيرٌ",
    "ذَٰلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِۦ هُوَ الْبَٰطِلُ وَأَنَّ اللَّهَ هُوَ الْعَلِىُّ الْكَبِيرُ",
    "أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَآءِ مَآءً فَتُصْبِحُ الْأَرْضُ مُخْضَرَّةً  إِنَّ اللَّهَ لَطِيفٌ خَبِيرٌ",
    "لَّهُۥ مَا فِى السَّمَٰوَٰتِ وَمَا فِى الْأَرْضِ  وَإِنَّ اللَّهَ لَهُوَ الْغَنِىُّ الْحَمِيدُ",
    "أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِى الْأَرْضِ وَالْفُلْكَ تَجْرِى فِى الْبَحْرِ بِأَمْرِهِۦ وَيُمْسِكُ السَّمَآءَ أَن تَقَعَ عَلَى الْأَرْضِ إِلَّا بِإِذْنِهِۦٓ  إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَّحِيمٌ",
    "وَهُوَ الَّذِىٓ أَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ  إِنَّ الْإِنسَٰنَ لَكَفُورٌ",
    "لِّكُلِّ أُمَّةٍ جَعَلْنَا مَنسَكًا هُمْ نَاسِكُوهُ  فَلَا يُنَٰزِعُنَّكَ فِى الْأَمْرِ  وَادْعُ إِلَىٰ رَبِّكَ  إِنَّكَ لَعَلَىٰ هُدًى مُّسْتَقِيمٍ",
    "وَإِن جَٰدَلُوكَ فَقُلِ اللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ",
    "اللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ الْقِيَٰمَةِ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ",
    "أَلَمْ تَعْلَمْ أَنَّ اللَّهَ يَعْلَمُ مَا فِى السَّمَآءِ وَالْأَرْضِ  إِنَّ ذَٰلِكَ فِى كِتَٰبٍ  إِنَّ ذَٰلِكَ عَلَى اللَّهِ يَسِيرٌ",
    "وَيَعْبُدُونَ مِن دُونِ اللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَمَا لَيْسَ لَهُم بِهِۦ عِلْمٌ  وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ",
    "وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ تَعْرِفُ فِى وُجُوهِ الَّذِينَ كَفَرُوا الْمُنكَرَ  يَكَادُونَ يَسْطُونَ بِالَّذِينَ يَتْلُونَ عَلَيْهِمْ ءَايَٰتِنَا  قُلْ أَفَأُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكُمُ  النَّارُ وَعَدَهَا اللَّهُ الَّذِينَ كَفَرُوا  وَبِئْسَ الْمَصِيرُ",
    "يَٰٓأَيُّهَا النَّاسُ ضُرِبَ مَثَلٌ فَاسْتَمِعُوا لَهُۥٓ  إِنَّ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَن يَخْلُقُوا ذُبَابًا وَلَوِ اجْتَمَعُوا لَهُۥ  وَإِن يَسْلُبْهُمُ الذُّبَابُ شَئًْا لَّا يَسْتَنقِذُوهُ مِنْهُ  ضَعُفَ الطَّالِبُ وَالْمَطْلُوبُ",
    "مَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِۦٓ  إِنَّ اللَّهَ لَقَوِىٌّ عَزِيزٌ",
    "اللَّهُ يَصْطَفِى مِنَ الْمَلَٰٓئِكَةِ رُسُلًا وَمِنَ النَّاسِ  إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ",
    "يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ  وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ",
    "يَٰٓأَيُّهَا الَّذِينَ ءَامَنُوا ارْكَعُوا وَاسْجُدُوا وَاعْبُدُوا رَبَّكُمْ وَافْعَلُوا الْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ",
    "وَجَٰهِدُوا فِى اللَّهِ حَقَّ جِهَادِهِۦ  هُوَ اجْتَبَىٰكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِى الدِّينِ مِنْ حَرَجٍ  مِّلَّةَ أَبِيكُمْ إِبْرَٰهِيمَ  هُوَ سَمَّىٰكُمُ الْمُسْلِمِينَ مِن قَبْلُ وَفِى هَٰذَا لِيَكُونَ الرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا شُهَدَآءَ عَلَى النَّاسِ  فَأَقِيمُوا الصَّلَوٰةَ وَءَاتُوا الزَّكَوٰةَ وَاعْتَصِمُوا بِاللَّهِ هُوَ مَوْلَىٰكُمْ  فَنِعْمَ الْمَوْلَىٰ وَنِعْمَ النَّصِيرُ",
  ],
  23: [
    "قَدْ أَفْلَحَ الْمُؤْمِنُونَ",
    "الَّذِينَ هُمْ فِى صَلَاتِهِمْ خَٰشِعُونَ",
    "وَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَ",
    "وَالَّذِينَ هُمْ لِلزَّكَوٰةِ فَٰعِلُونَ",
    "وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ",
    "إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ",
    "فَمَنِ ابْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُولَٰٓئِكَ هُمُ الْعَادُونَ",
    "وَالَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ",
    "وَالَّذِينَ هُمْ عَلَىٰ صَلَوَٰتِهِمْ يُحَافِظُونَ",
    "أُولَٰٓئِكَ هُمُ الْوَٰرِثُونَ",
    "الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَٰلِدُونَ",
    "وَلَقَدْ خَلَقْنَا الْإِنسَٰنَ مِن سُلَٰلَةٍ مِّن طِينٍ",
    "ثُمَّ جَعَلْنَٰهُ نُطْفَةً فِى قَرَارٍ مَّكِينٍ",
    "ثُمَّ خَلَقْنَا النُّطْفَةَ عَلَقَةً فَخَلَقْنَا الْعَلَقَةَ مُضْغَةً فَخَلَقْنَا الْمُضْغَةَ عِظَٰمًا فَكَسَوْنَا الْعِظَٰمَ لَحْمًا ثُمَّ أَنشَأْنَٰهُ خَلْقًا ءَاخَرَ  فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَٰلِقِينَ",
    "ثُمَّ إِنَّكُم بَعْدَ ذَٰلِكَ لَمَيِّتُونَ",
    "ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَٰمَةِ تُبْعَثُونَ",
    "وَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَآئِقَ وَمَا كُنَّا عَنِ الْخَلْقِ غَٰفِلِينَ",
    "وَأَنزَلْنَا مِنَ السَّمَآءِ مَآءً بِقَدَرٍ فَأَسْكَنَّٰهُ فِى الْأَرْضِ  وَإِنَّا عَلَىٰ ذَهَابٍ بِهِۦ لَقَٰدِرُونَ",
    "فَأَنشَأْنَا لَكُم بِهِۦ جَنَّٰتٍ مِّن نَّخِيلٍ وَأَعْنَٰبٍ لَّكُمْ فِيهَا فَوَٰكِهُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ",
    "وَشَجَرَةً تَخْرُجُ مِن طُورِ سَيْنَآءَ تَنبُتُ بِالدُّهْنِ وَصِبْغٍ لِّلَْٔاكِلِينَ",
    "وَإِنَّ لَكُمْ فِى الْأَنْعَٰمِ لَعِبْرَةً  نُّسْقِيكُم مِّمَّا فِى بُطُونِهَا وَلَكُمْ فِيهَا مَنَٰفِعُ كَثِيرَةٌ وَمِنْهَا تَأْكُلُونَ",
    "وَعَلَيْهَا وَعَلَى الْفُلْكِ تُحْمَلُونَ",
    "وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ  أَفَلَا تَتَّقُونَ",
    "فَقَالَ الْمَلَؤُا الَّذِينَ كَفَرُوا مِن قَوْمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يُرِيدُ أَن يَتَفَضَّلَ عَلَيْكُمْ وَلَوْ شَآءَ اللَّهُ لَأَنزَلَ مَلَٰٓئِكَةً مَّا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا الْأَوَّلِينَ",
    "إِنْ هُوَ إِلَّا رَجُلٌ بِهِۦ جِنَّةٌ فَتَرَبَّصُوا بِهِۦ حَتَّىٰ حِينٍ",
    "قَالَ رَبِّ انصُرْنِى بِمَا كَذَّبُونِ",
    "فَأَوْحَيْنَآ إِلَيْهِ أَنِ اصْنَعِ الْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا فَإِذَا جَآءَ أَمْرُنَا وَفَارَ التَّنُّورُ  فَاسْلُكْ فِيهَا مِن كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ الْقَوْلُ مِنْهُمْ  وَلَا تُخَٰطِبْنِى فِى الَّذِينَ ظَلَمُوٓا  إِنَّهُم مُّغْرَقُونَ",
    "فَإِذَا اسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى الْفُلْكِ فَقُلِ الْحَمْدُ لِلَّهِ الَّذِى نَجَّىٰنَا مِنَ الْقَوْمِ الظَّٰلِمِينَ",
    "وَقُل رَّبِّ أَنزِلْنِى مُنزَلًا مُّبَارَكًا وَأَنتَ خَيْرُ الْمُنزِلِينَ",
    "إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ وَإِن كُنَّا لَمُبْتَلِينَ",
    "ثُمَّ أَنشَأْنَا مِن بَعْدِهِمْ قَرْنًا ءَاخَرِينَ",
    "فَأَرْسَلْنَا فِيهِمْ رَسُولًا مِّنْهُمْ أَنِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ  أَفَلَا تَتَّقُونَ",
    "وَقَالَ الْمَلَأُ مِن قَوْمِهِ الَّذِينَ كَفَرُوا وَكَذَّبُوا بِلِقَآءِ الَْٔاخِرَةِ وَأَتْرَفْنَٰهُمْ فِى الْحَيَوٰةِ الدُّنْيَا مَا هَٰذَآ إِلَّا بَشَرٌ مِّثْلُكُمْ يَأْكُلُ مِمَّا تَأْكُلُونَ مِنْهُ وَيَشْرَبُ مِمَّا تَشْرَبُونَ",
    "وَلَئِنْ أَطَعْتُم بَشَرًا مِّثْلَكُمْ إِنَّكُمْ إِذًا لَّخَٰسِرُونَ",
    "أَيَعِدُكُمْ أَنَّكُمْ إِذَا مِتُّمْ وَكُنتُمْ تُرَابًا وَعِظَٰمًا أَنَّكُم مُّخْرَجُونَ",
    "۞ هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ",
    "إِنْ هِىَ إِلَّا حَيَاتُنَا الدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ",
    "إِنْ هُوَ إِلَّا رَجُلٌ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا وَمَا نَحْنُ لَهُۥ بِمُؤْمِنِينَ",
    "قَالَ رَبِّ انصُرْنِى بِمَا كَذَّبُونِ",
    "قَالَ عَمَّا قَلِيلٍ لَّيُصْبِحُنَّ نَٰدِمِينَ",
    "فَأَخَذَتْهُمُ الصَّيْحَةُ بِالْحَقِّ فَجَعَلْنَٰهُمْ غُثَآءً  فَبُعْدًا لِّلْقَوْمِ الظَّٰلِمِينَ",
    "ثُمَّ أَنشَأْنَا مِن بَعْدِهِمْ قُرُونًا ءَاخَرِينَ",
    "مَا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَْٔخِرُونَ",
    "ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرَا  كُلَّ مَا جَآءَ أُمَّةً رَّسُولُهَا كَذَّبُوهُ  فَأَتْبَعْنَا بَعْضَهُم بَعْضًا وَجَعَلْنَٰهُمْ أَحَادِيثَ  فَبُعْدًا لِّقَوْمٍ لَّا يُؤْمِنُونَ",
    "ثُمَّ أَرْسَلْنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بَِٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ",
    "إِلَىٰ فِرْعَوْنَ وَمَلَإِيهِۦ فَاسْتَكْبَرُوا وَكَانُوا قَوْمًا عَالِينَ",
    "فَقَالُوٓا أَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَٰبِدُونَ",
    "فَكَذَّبُوهُمَا فَكَانُوا مِنَ الْمُهْلَكِينَ",
    "وَلَقَدْ ءَاتَيْنَا مُوسَى الْكِتَٰبَ لَعَلَّهُمْ يَهْتَدُونَ",
    "وَجَعَلْنَا ابْنَ مَرْيَمَ وَأُمَّهُۥٓ ءَايَةً وَءَاوَيْنَٰهُمَآ إِلَىٰ رَبْوَةٍ ذَاتِ قَرَارٍ وَمَعِينٍ",
    "يَٰٓأَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَٰتِ وَاعْمَلُوا صَٰلِحًا  إِنِّى بِمَا تَعْمَلُونَ عَلِيمٌ",
    "وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةً وَٰحِدَةً وَأَنَا رَبُّكُمْ فَاتَّقُونِ",
    "فَتَقَطَّعُوٓا أَمْرَهُم بَيْنَهُمْ زُبُرًا  كُلُّ حِزْبٍ بِمَا لَدَيْهِمْ فَرِحُونَ",
    "فَذَرْهُمْ فِى غَمْرَتِهِمْ حَتَّىٰ حِينٍ",
    "أَيَحْسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٍ وَبَنِينَ",
    "نُسَارِعُ لَهُمْ فِى الْخَيْرَٰتِ  بَل لَّا يَشْعُرُونَ",
    "إِنَّ الَّذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِم مُّشْفِقُونَ",
    "وَالَّذِينَ هُم بَِٔايَٰتِ رَبِّهِمْ يُؤْمِنُونَ",
    "وَالَّذِينَ هُم بِرَبِّهِمْ لَا يُشْرِكُونَ",
    "وَالَّذِينَ يُؤْتُونَ مَآ ءَاتَوا وَّقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَىٰ رَبِّهِمْ رَٰجِعُونَ",
    "أُولَٰٓئِكَ يُسَٰرِعُونَ فِى الْخَيْرَٰتِ وَهُمْ لَهَا سَٰبِقُونَ",
    "وَلَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا  وَلَدَيْنَا كِتَٰبٌ يَنطِقُ بِالْحَقِّ  وَهُمْ لَا يُظْلَمُونَ",
    "بَلْ قُلُوبُهُمْ فِى غَمْرَةٍ مِّنْ هَٰذَا وَلَهُمْ أَعْمَٰلٌ مِّن دُونِ ذَٰلِكَ هُمْ لَهَا عَٰمِلُونَ",
    "حَتَّىٰٓ إِذَآ أَخَذْنَا مُتْرَفِيهِم بِالْعَذَابِ إِذَا هُمْ يَجَْٔرُونَ",
    "لَا تَجَْٔرُوا الْيَوْمَ  إِنَّكُم مِّنَّا لَا تُنصَرُونَ",
    "قَدْ كَانَتْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ تَنكِصُونَ",
    "مُسْتَكْبِرِينَ بِهِۦ سَٰمِرًا تَهْجُرُونَ",
    "أَفَلَمْ يَدَّبَّرُوا الْقَوْلَ أَمْ جَآءَهُم مَّا لَمْ يَأْتِ ءَابَآءَهُمُ الْأَوَّلِينَ",
    "أَمْ لَمْ يَعْرِفُوا رَسُولَهُمْ فَهُمْ لَهُۥ مُنكِرُونَ",
    "أَمْ يَقُولُونَ بِهِۦ جِنَّةٌ  بَلْ جَآءَهُم بِالْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَٰرِهُونَ",
    "وَلَوِ اتَّبَعَ الْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ السَّمَٰوَٰتُ وَالْأَرْضُ وَمَن فِيهِنَّ  بَلْ أَتَيْنَٰهُم بِذِكْرِهِمْ فَهُمْ عَن ذِكْرِهِم مُّعْرِضُونَ",
    "أَمْ تَسَْٔلُهُمْ خَرْجًا فَخَرَاجُ رَبِّكَ خَيْرٌ  وَهُوَ خَيْرُ الرَّٰزِقِينَ",
    "وَإِنَّكَ لَتَدْعُوهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ",
    "وَإِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالَْٔاخِرَةِ عَنِ الصِّرَٰطِ لَنَٰكِبُونَ",
    "۞ وَلَوْ رَحِمْنَٰهُمْ وَكَشَفْنَا مَا بِهِم مِّن ضُرٍّ لَّلَجُّوا فِى طُغْيَٰنِهِمْ يَعْمَهُونَ",
    "وَلَقَدْ أَخَذْنَٰهُم بِالْعَذَابِ فَمَا اسْتَكَانُوا لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ",
    "حَتَّىٰٓ إِذَا فَتَحْنَا عَلَيْهِم بَابًا ذَا عَذَابٍ شَدِيدٍ إِذَا هُمْ فِيهِ مُبْلِسُونَ",
    "وَهُوَ الَّذِىٓ أَنشَأَ لَكُمُ السَّمْعَ وَالْأَبْصَٰرَ وَالْأَفِْٔدَةَ  قَلِيلًا مَّا تَشْكُرُونَ",
    "وَهُوَ الَّذِى ذَرَأَكُمْ فِى الْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ",
    "وَهُوَ الَّذِى يُحْىِۦ وَيُمِيتُ وَلَهُ اخْتِلَٰفُ الَّيْلِ وَالنَّهَارِ  أَفَلَا تَعْقِلُونَ",
    "بَلْ قَالُوا مِثْلَ مَا قَالَ الْأَوَّلُونَ",
    "قَالُوٓا أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ",
    "لَقَدْ وُعِدْنَا نَحْنُ وَءَابَآؤُنَا هَٰذَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ الْأَوَّلِينَ",
    "قُل لِّمَنِ الْأَرْضُ وَمَن فِيهَآ إِن كُنتُمْ تَعْلَمُونَ",
    "سَيَقُولُونَ لِلَّهِ  قُلْ أَفَلَا تَذَكَّرُونَ",
    "قُلْ مَن رَّبُّ السَّمَٰوَٰتِ السَّبْعِ وَرَبُّ الْعَرْشِ الْعَظِيمِ",
    "سَيَقُولُونَ لِلَّهِ  قُلْ أَفَلَا تَتَّقُونَ",
    "قُلْ مَن بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ",
    "سَيَقُولُونَ لِلَّهِ  قُلْ فَأَنَّىٰ تُسْحَرُونَ",
    "بَلْ أَتَيْنَٰهُم بِالْحَقِّ وَإِنَّهُمْ لَكَٰذِبُونَ",
    "مَا اتَّخَذَ اللَّهُ مِن وَلَدٍ وَمَا كَانَ مَعَهُۥ مِنْ إِلَٰهٍ  إِذًا لَّذَهَبَ كُلُّ إِلَٰهٍ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْضٍ  سُبْحَٰنَ اللَّهِ عَمَّا يَصِفُونَ",
    "عَٰلِمِ الْغَيْبِ وَالشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ",
    "قُل رَّبِّ إِمَّا تُرِيَنِّى مَا يُوعَدُونَ",
    "رَبِّ فَلَا تَجْعَلْنِى فِى الْقَوْمِ الظَّٰلِمِينَ",
    "وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمْ لَقَٰدِرُونَ",
    "ادْفَعْ بِالَّتِى هِىَ أَحْسَنُ السَّيِّئَةَ  نَحْنُ أَعْلَمُ بِمَا يَصِفُونَ",
    "وَقُل رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَٰتِ الشَّيَٰطِينِ",
    "وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ",
    "حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ الْمَوْتُ قَالَ رَبِّ ارْجِعُونِ",
    "لَعَلِّىٓ أَعْمَلُ صَٰلِحًا فِيمَا تَرَكْتُ  كَلَّآ  إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا  وَمِن وَرَآئِهِم بَرْزَخٌ إِلَىٰ يَوْمِ يُبْعَثُونَ",
    "فَإِذَا نُفِخَ فِى الصُّورِ فَلَآ أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَآءَلُونَ",
    "فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُولَٰٓئِكَ هُمُ الْمُفْلِحُونَ",
    "وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُولَٰٓئِكَ الَّذِينَ خَسِرُوٓا أَنفُسَهُمْ فِى جَهَنَّمَ خَٰلِدُونَ",
    "تَلْفَحُ وُجُوهَهُمُ النَّارُ وَهُمْ فِيهَا كَٰلِحُونَ",
    "أَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُم بِهَا تُكَذِّبُونَ",
    "قَالُوا رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْمًا ضَآلِّينَ",
    "رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَٰلِمُونَ",
    "قَالَ اخْسَُٔوا فِيهَا وَلَا تُكَلِّمُونِ",
    "إِنَّهُۥ كَانَ فَرِيقٌ مِّنْ عِبَادِى يَقُولُونَ رَبَّنَآ ءَامَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الرَّٰحِمِينَ",
    "فَاتَّخَذْتُمُوهُمْ سِخْرِيًّا حَتَّىٰٓ أَنسَوْكُمْ ذِكْرِى وَكُنتُم مِّنْهُمْ تَضْحَكُونَ",
    "إِنِّى جَزَيْتُهُمُ الْيَوْمَ بِمَا صَبَرُوٓا أَنَّهُمْ هُمُ الْفَآئِزُونَ",
    "قَٰلَ كَمْ لَبِثْتُمْ فِى الْأَرْضِ عَدَدَ سِنِينَ",
    "قَالُوا لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ فَسَْٔلِ الْعَآدِّينَ",
    "قَٰلَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًا  لَّوْ أَنَّكُمْ كُنتُمْ تَعْلَمُونَ",
    "أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ",
    "فَتَعَٰلَى اللَّهُ الْمَلِكُ الْحَقُّ  لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ الْعَرْشِ الْكَرِيمِ",
    "وَمَن يَدْعُ مَعَ اللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرْهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓ  إِنَّهُۥ لَا يُفْلِحُ الْكَٰفِرُونَ",
    "وَقُل رَّبِّ اغْفِرْ وَارْحَمْ وَأَنتَ خَيْرُ الرَّٰحِمِينَ",
  ],
  24: [
    "سُورَةٌ أَنزَلْنَٰهَا وَفَرَضْنَٰهَا وَأَنزَلْنَا فِيهَآ ءَايَٰتٍ بَيِّنَٰتٍ لَّعَلَّكُمْ تَذَكَّرُونَ",
    "الزَّانِيَةُ وَالزَّانِى فَاجْلِدُوا كُلَّ وَٰحِدٍ مِّنْهُمَا مِائَةَ جَلْدَةٍ  وَلَا تَأْخُذْكُم بِهِمَا رَأْفَةٌ فِى دِينِ اللَّهِ إِن كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الَْٔاخِرِ  وَلْيَشْهَدْ عَذَابَهُمَا طَآئِفَةٌ مِّنَ الْمُؤْمِنِينَ",
    "الزَّانِى لَا يَنكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةً وَالزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوْ مُشْرِكٌ  وَحُرِّمَ ذَٰلِكَ عَلَى الْمُؤْمِنِينَ",
    "وَالَّذِينَ يَرْمُونَ الْمُحْصَنَٰتِ ثُمَّ لَمْ يَأْتُوا بِأَرْبَعَةِ شُهَدَآءَ فَاجْلِدُوهُمْ ثَمَٰنِينَ جَلْدَةً وَلَا تَقْبَلُوا لَهُمْ شَهَٰدَةً أَبَدًا  وَأُولَٰٓئِكَ هُمُ الْفَٰسِقُونَ",
    "إِلَّا الَّذِينَ تَابُوا مِن بَعْدِ ذَٰلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ",
    "وَالَّذِينَ يَرْمُونَ أَزْوَٰجَهُمْ وَلَمْ يَكُن لَّهُمْ شُهَدَآءُ إِلَّآ أَنفُسُهُمْ فَشَهَٰدَةُ أَحَدِهِمْ أَرْبَعُ شَهَٰدَٰتٍ بِاللَّهِ  إِنَّهُۥ لَمِنَ الصَّٰدِقِينَ",
    "وَالْخَٰمِسَةُ أَنَّ لَعْنَتَ اللَّهِ عَلَيْهِ إِن كَانَ مِنَ الْكَٰذِبِينَ",
    "وَيَدْرَؤُا عَنْهَا الْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَٰدَٰتٍ بِاللَّهِ  إِنَّهُۥ لَمِنَ الْكَٰذِبِينَ",
    "وَالْخَٰمِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَآ إِن كَانَ مِنَ الصَّٰدِقِينَ",
    "وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ اللَّهَ تَوَّابٌ حَكِيمٌ",
    "إِنَّ الَّذِينَ جَآءُو بِالْإِفْكِ عُصْبَةٌ مِّنكُمْ  لَا تَحْسَبُوهُ شَرًّا لَّكُم  بَلْ هُوَ خَيْرٌ لَّكُمْ  لِكُلِّ امْرِئٍ مِّنْهُم مَّا اكْتَسَبَ مِنَ الْإِثْمِ  وَالَّذِى تَوَلَّىٰ كِبْرَهُۥ مِنْهُمْ لَهُۥ عَذَابٌ عَظِيمٌ",
    "لَّوْلَآ إِذْ سَمِعْتُمُوهُ ظَنَّ الْمُؤْمِنُونَ وَالْمُؤْمِنَٰتُ بِأَنفُسِهِمْ خَيْرًا وَقَالُوا هَٰذَآ إِفْكٌ مُّبِينٌ",
    "لَّوْلَا جَآءُو عَلَيْهِ بِأَرْبَعَةِ شُهَدَآءَ  فَإِذْ لَمْ يَأْتُوا بِالشُّهَدَآءِ فَأُولَٰٓئِكَ عِندَ اللَّهِ هُمُ الْكَٰذِبُونَ",
    "وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ فِى الدُّنْيَا وَالَْٔاخِرَةِ لَمَسَّكُمْ فِى مَآ أَفَضْتُمْ فِيهِ عَذَابٌ عَظِيمٌ",
    "إِذْ تَلَقَّوْنَهُۥ بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِكُم مَّا لَيْسَ لَكُم بِهِۦ عِلْمٌ وَتَحْسَبُونَهُۥ هَيِّنًا وَهُوَ عِندَ اللَّهِ عَظِيمٌ",
    "وَلَوْلَآ إِذْ سَمِعْتُمُوهُ قُلْتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبْحَٰنَكَ هَٰذَا بُهْتَٰنٌ عَظِيمٌ",
    "يَعِظُكُمُ اللَّهُ أَن تَعُودُوا لِمِثْلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤْمِنِينَ",
    "وَيُبَيِّنُ اللَّهُ لَكُمُ الَْٔايَٰتِ  وَاللَّهُ عَلِيمٌ حَكِيمٌ",
    "إِنَّ الَّذِينَ يُحِبُّونَ أَن تَشِيعَ الْفَٰحِشَةُ فِى الَّذِينَ ءَامَنُوا لَهُمْ عَذَابٌ أَلِيمٌ فِى الدُّنْيَا وَالَْٔاخِرَةِ  وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ",
    "وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ اللَّهَ رَءُوفٌ رَّحِيمٌ",
    "۞ يَٰٓأَيُّهَا الَّذِينَ ءَامَنُوا لَا تَتَّبِعُوا خُطُوَٰتِ الشَّيْطَٰنِ  وَمَن يَتَّبِعْ خُطُوَٰتِ الشَّيْطَٰنِ فَإِنَّهُۥ يَأْمُرُ بِالْفَحْشَآءِ وَالْمُنكَرِ  وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًا وَلَٰكِنَّ اللَّهَ يُزَكِّى مَن يَشَآءُ  وَاللَّهُ سَمِيعٌ عَلِيمٌ",
    "وَلَا يَأْتَلِ أُولُوا الْفَضْلِ مِنكُمْ وَالسَّعَةِ أَن يُؤْتُوٓا أُولِى الْقُرْبَىٰ وَالْمَسَٰكِينَ وَالْمُهَٰجِرِينَ فِى سَبِيلِ اللَّهِ  وَلْيَعْفُوا وَلْيَصْفَحُوٓا  أَلَا تُحِبُّونَ أَن يَغْفِرَ اللَّهُ لَكُمْ  وَاللَّهُ غَفُورٌ رَّحِيمٌ",
    "إِنَّ الَّذِينَ يَرْمُونَ الْمُحْصَنَٰتِ الْغَٰفِلَٰتِ الْمُؤْمِنَٰتِ لُعِنُوا فِى الدُّنْيَا وَالَْٔاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌ",
    "يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُم بِمَا كَانُوا يَعْمَلُونَ",
    "يَوْمَئِذٍ يُوَفِّيهِمُ اللَّهُ دِينَهُمُ الْحَقَّ وَيَعْلَمُونَ أَنَّ اللَّهَ هُوَ الْحَقُّ الْمُبِينُ",
    "الْخَبِيثَٰتُ لِلْخَبِيثِينَ وَالْخَبِيثُونَ لِلْخَبِيثَٰتِ  وَالطَّيِّبَٰتُ لِلطَّيِّبِينَ وَالطَّيِّبُونَ لِلطَّيِّبَٰتِ  أُولَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ  لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ",
    "يَٰٓأَيُّهَا الَّذِينَ ءَامَنُوا لَا تَدْخُلُوا بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُوا وَتُسَلِّمُوا عَلَىٰٓ أَهْلِهَا  ذَٰلِكُمْ خَيْرٌ لَّكُمْ لَعَلَّكُمْ تَذَكَّرُونَ",
    "فَإِن لَّمْ تَجِدُوا فِيهَآ أَحَدًا فَلَا تَدْخُلُوهَا حَتَّىٰ يُؤْذَنَ لَكُمْ  وَإِن قِيلَ لَكُمُ ارْجِعُوا فَارْجِعُوا  هُوَ أَزْكَىٰ لَكُمْ  وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ",
    "لَّيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَدْخُلُوا بُيُوتًا غَيْرَ مَسْكُونَةٍ فِيهَا مَتَٰعٌ لَّكُمْ  وَاللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ",
    "قُل لِّلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَٰرِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ  ذَٰلِكَ أَزْكَىٰ لَهُمْ  إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ",
    "وَقُل لِّلْمُؤْمِنَٰتِ يَغْضُضْنَ مِنْ أَبْصَٰرِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا  وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ  وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ ءَابَآئِهِنَّ أَوْ ءَابَآءِ بُعُولَتِهِنَّ أَوْ أَبْنَآئِهِنَّ أَوْ أَبْنَآءِ بُعُولَتِهِنَّ أَوْ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ أَخَوَٰتِهِنَّ أَوْ نِسَآئِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُنَّ أَوِ التَّٰبِعِينَ غَيْرِ أُولِى الْإِرْبَةِ مِنَ الرِّجَالِ أَوِ الطِّفْلِ الَّذِينَ لَمْ يَظْهَرُوا عَلَىٰ عَوْرَٰتِ النِّسَآءِ  وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ  وَتُوبُوٓا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ",
    "وَأَنكِحُوا الْأَيَٰمَىٰ مِنكُمْ وَالصَّٰلِحِينَ مِنْ عِبَادِكُمْ وَإِمَآئِكُمْ  إِن يَكُونُوا فُقَرَآءَ يُغْنِهِمُ اللَّهُ مِن فَضْلِهِۦ  وَاللَّهُ وَٰسِعٌ عَلِيمٌ",
    "وَلْيَسْتَعْفِفِ الَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغْنِيَهُمُ اللَّهُ مِن فَضْلِهِۦ  وَالَّذِينَ يَبْتَغُونَ الْكِتَٰبَ مِمَّا مَلَكَتْ أَيْمَٰنُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا  وَءَاتُوهُم مِّن مَّالِ اللَّهِ الَّذِىٓ ءَاتَىٰكُمْ  وَلَا تُكْرِهُوا فَتَيَٰتِكُمْ عَلَى الْبِغَآءِ إِنْ أَرَدْنَ تَحَصُّنًا لِّتَبْتَغُوا عَرَضَ الْحَيَوٰةِ الدُّنْيَا  وَمَن يُكْرِههُّنَّ فَإِنَّ اللَّهَ مِن بَعْدِ إِكْرَٰهِهِنَّ غَفُورٌ رَّحِيمٌ",
    "وَلَقَدْ أَنزَلْنَآ إِلَيْكُمْ ءَايَٰتٍ مُّبَيِّنَٰتٍ وَمَثَلًا مِّنَ الَّذِينَ خَلَوْا مِن قَبْلِكُمْ وَمَوْعِظَةً لِّلْمُتَّقِينَ",
    "۞ اللَّهُ نُورُ السَّمَٰوَٰتِ وَالْأَرْضِ  مَثَلُ نُورِهِۦ كَمِشْكَوٰةٍ فِيهَا مِصْبَاحٌ  الْمِصْبَاحُ فِى زُجَاجَةٍ  الزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّىٌّ يُوقَدُ مِن شَجَرَةٍ مُّبَٰرَكَةٍ زَيْتُونَةٍ لَّا شَرْقِيَّةٍ وَلَا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِىٓءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ  نُّورٌ عَلَىٰ نُورٍ  يَهْدِى اللَّهُ لِنُورِهِۦ مَن يَشَآءُ  وَيَضْرِبُ اللَّهُ الْأَمْثَٰلَ لِلنَّاسِ  وَاللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ",
    "فِى بُيُوتٍ أَذِنَ اللَّهُ أَن تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِالْغُدُوِّ وَالَْٔاصَالِ",
    "رِجَالٌ لَّا تُلْهِيهِمْ تِجَٰرَةٌ وَلَا بَيْعٌ عَن ذِكْرِ اللَّهِ وَإِقَامِ الصَّلَوٰةِ وَإِيتَآءِ الزَّكَوٰةِ  يَخَافُونَ يَوْمًا تَتَقَلَّبُ فِيهِ الْقُلُوبُ وَالْأَبْصَٰرُ",
    "لِيَجْزِيَهُمُ اللَّهُ أَحْسَنَ مَا عَمِلُوا وَيَزِيدَهُم مِّن فَضْلِهِۦ  وَاللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ",
    "وَالَّذِينَ كَفَرُوٓا أَعْمَٰلُهُمْ كَسَرَابٍ بِقِيعَةٍ يَحْسَبُهُ الظَّمَْٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمْ يَجِدْهُ شَئًْا وَوَجَدَ اللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥ  وَاللَّهُ سَرِيعُ الْحِسَابِ",
    "أَوْ كَظُلُمَٰتٍ فِى بَحْرٍ لُّجِّىٍّ يَغْشَىٰهُ مَوْجٌ مِّن فَوْقِهِۦ مَوْجٌ مِّن فَوْقِهِۦ سَحَابٌ  ظُلُمَٰتٌ بَعْضُهَا فَوْقَ بَعْضٍ إِذَآ أَخْرَجَ يَدَهُۥ لَمْ يَكَدْ يَرَىٰهَا  وَمَن لَّمْ يَجْعَلِ اللَّهُ لَهُۥ نُورًا فَمَا لَهُۥ مِن نُّورٍ",
    "أَلَمْ تَرَ أَنَّ اللَّهَ يُسَبِّحُ لَهُۥ مَن فِى السَّمَٰوَٰتِ وَالْأَرْضِ وَالطَّيْرُ صَٰٓفَّٰتٍ  كُلٌّ قَدْ عَلِمَ صَلَاتَهُۥ وَتَسْبِيحَهُۥ  وَاللَّهُ عَلِيمٌ بِمَا يَفْعَلُونَ",
    "وَلِلَّهِ مُلْكُ السَّمَٰوَٰتِ وَالْأَرْضِ  وَإِلَى اللَّهِ الْمَصِيرُ",
    "أَلَمْ تَرَ أَنَّ اللَّهَ يُزْجِى سَحَابًا ثُمَّ يُؤَلِّفُ بَيْنَهُۥ ثُمَّ يَجْعَلُهُۥ رُكَامًا فَتَرَى الْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ السَّمَآءِ مِن جِبَالٍ فِيهَا مِن بَرَدٍ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصْرِفُهُۥ عَن مَّن يَشَآءُ  يَكَادُ سَنَا بَرْقِهِۦ يَذْهَبُ بِالْأَبْصَٰرِ",
    "يُقَلِّبُ اللَّهُ الَّيْلَ وَالنَّهَارَ  إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّأُولِى الْأَبْصَٰرِ",
    "وَاللَّهُ خَلَقَ كُلَّ دَآبَّةٍ مِّن مَّآءٍ  فَمِنْهُم مَّن يَمْشِى عَلَىٰ بَطْنِهِۦ وَمِنْهُم مَّن يَمْشِى عَلَىٰ رِجْلَيْنِ وَمِنْهُم مَّن يَمْشِى عَلَىٰٓ أَرْبَعٍ  يَخْلُقُ اللَّهُ مَا يَشَآءُ  إِنَّ اللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ",
    "لَّقَدْ أَنزَلْنَآ ءَايَٰتٍ مُّبَيِّنَٰتٍ  وَاللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ",
    "وَيَقُولُونَ ءَامَنَّا بِاللَّهِ وَبِالرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٌ مِّنْهُم مِّن بَعْدِ ذَٰلِكَ  وَمَآ أُولَٰٓئِكَ بِالْمُؤْمِنِينَ",
    "وَإِذَا دُعُوٓا إِلَى اللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌ مِّنْهُم مُّعْرِضُونَ",
    "وَإِن يَكُن لَّهُمُ الْحَقُّ يَأْتُوٓا إِلَيْهِ مُذْعِنِينَ",
    "أَفِى قُلُوبِهِم مَّرَضٌ أَمِ ارْتَابُوٓا أَمْ يَخَافُونَ أَن يَحِيفَ اللَّهُ عَلَيْهِمْ وَرَسُولُهُۥ  بَلْ أُولَٰٓئِكَ هُمُ الظَّٰلِمُونَ",
    "إِنَّمَا كَانَ قَوْلَ الْمُؤْمِنِينَ إِذَا دُعُوٓا إِلَى اللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا سَمِعْنَا وَأَطَعْنَا  وَأُولَٰٓئِكَ هُمُ الْمُفْلِحُونَ",
    "وَمَن يُطِعِ اللَّهَ وَرَسُولَهُۥ وَيَخْشَ اللَّهَ وَيَتَّقْهِ فَأُولَٰٓئِكَ هُمُ الْفَآئِزُونَ",
    "۞ وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِنْ أَمَرْتَهُمْ لَيَخْرُجُنَّ  قُل لَّا تُقْسِمُوا  طَاعَةٌ مَّعْرُوفَةٌ  إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ",
    "قُلْ أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ  فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ  وَإِن تُطِيعُوهُ تَهْتَدُوا  وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلَٰغُ الْمُبِينُ",
    "وَعَدَ اللَّهُ الَّذِينَ ءَامَنُوا مِنكُمْ وَعَمِلُوا الصَّٰلِحَٰتِ لَيَسْتَخْلِفَنَّهُمْ فِى الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِى ارْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُم مِّن بَعْدِ خَوْفِهِمْ أَمْنًا  يَعْبُدُونَنِى لَا يُشْرِكُونَ بِى شَئًْا  وَمَن كَفَرَ بَعْدَ ذَٰلِكَ فَأُولَٰٓئِكَ هُمُ الْفَٰسِقُونَ",
    "وَأَقِيمُوا الصَّلَوٰةَ وَءَاتُوا الزَّكَوٰةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ",
    "لَا تَحْسَبَنَّ الَّذِينَ كَفَرُوا مُعْجِزِينَ فِى الْأَرْضِ  وَمَأْوَىٰهُمُ النَّارُ  وَلَبِئْسَ الْمَصِيرُ",
    "يَٰٓأَيُّهَا الَّذِينَ ءَامَنُوا لِيَسْتَْٔذِنكُمُ الَّذِينَ مَلَكَتْ أَيْمَٰنُكُمْ وَالَّذِينَ لَمْ يَبْلُغُوا الْحُلُمَ مِنكُمْ ثَلَٰثَ مَرَّٰتٍ  مِّن قَبْلِ صَلَوٰةِ الْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ الظَّهِيرَةِ وَمِن بَعْدِ صَلَوٰةِ الْعِشَآءِ  ثَلَٰثُ عَوْرَٰتٍ لَّكُمْ  لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌ بَعْدَهُنَّ  طَوَّٰفُونَ عَلَيْكُم بَعْضُكُمْ عَلَىٰ بَعْضٍ  كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الَْٔايَٰتِ  وَاللَّهُ عَلِيمٌ حَكِيمٌ",
    "وَإِذَا بَلَغَ الْأَطْفَٰلُ مِنكُمُ الْحُلُمَ فَلْيَسْتَْٔذِنُوا كَمَا اسْتَْٔذَنَ الَّذِينَ مِن قَبْلِهِمْ  كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمْ ءَايَٰتِهِۦ  وَاللَّهُ عَلِيمٌ حَكِيمٌ",
    "وَالْقَوَٰعِدُ مِنَ النِّسَآءِ الَّٰتِى لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَٰتٍ بِزِينَةٍ  وَأَن يَسْتَعْفِفْنَ خَيْرٌ لَّهُنَّ  وَاللَّهُ سَمِيعٌ عَلِيمٌ",
    "لَّيْسَ عَلَى الْأَعْمَىٰ حَرَجٌ وَلَا عَلَى الْأَعْرَجِ حَرَجٌ وَلَا عَلَى الْمَرِيضِ حَرَجٌ وَلَا عَلَىٰٓ أَنفُسِكُمْ أَن تَأْكُلُوا مِن بُيُوتِكُمْ أَوْ بُيُوتِ ءَابَآئِكُمْ أَوْ بُيُوتِ أُمَّهَٰتِكُمْ أَوْ بُيُوتِ إِخْوَٰنِكُمْ أَوْ بُيُوتِ أَخَوَٰتِكُمْ أَوْ بُيُوتِ أَعْمَٰمِكُمْ أَوْ بُيُوتِ عَمَّٰتِكُمْ أَوْ بُيُوتِ أَخْوَٰلِكُمْ أَوْ بُيُوتِ خَٰلَٰتِكُمْ أَوْ مَا مَلَكْتُم مَّفَاتِحَهُۥٓ أَوْ صَدِيقِكُمْ  لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا جَمِيعًا أَوْ أَشْتَاتًا  فَإِذَا دَخَلْتُم بُيُوتًا فَسَلِّمُوا عَلَىٰٓ أَنفُسِكُمْ تَحِيَّةً مِّنْ عِندِ اللَّهِ مُبَٰرَكَةً طَيِّبَةً  كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الَْٔايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ",
    "إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ ءَامَنُوا بِاللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُوا مَعَهُۥ عَلَىٰٓ أَمْرٍ جَامِعٍ لَّمْ يَذْهَبُوا حَتَّىٰ يَسْتَْٔذِنُوهُ  إِنَّ الَّذِينَ يَسْتَْٔذِنُونَكَ أُولَٰٓئِكَ الَّذِينَ يُؤْمِنُونَ بِاللَّهِ وَرَسُولِهِۦ  فَإِذَا اسْتَْٔذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَن لِّمَن شِئْتَ مِنْهُمْ وَاسْتَغْفِرْ لَهُمُ اللَّهَ  إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ",
    "لَّا تَجْعَلُوا دُعَآءَ الرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُم بَعْضًا  قَدْ يَعْلَمُ اللَّهُ الَّذِينَ يَتَسَلَّلُونَ مِنكُمْ لِوَاذًا  فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِۦٓ أَن تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ",
    "أَلَآ إِنَّ لِلَّهِ مَا فِى السَّمَٰوَٰتِ وَالْأَرْضِ  قَدْ يَعْلَمُ مَآ أَنتُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُم بِمَا عَمِلُوا  وَاللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ",
  ],
  25: [
    "تَبَارَكَ الَّذِى نَزَّلَ الْفُرْقَانَ عَلَىٰ عَبْدِهِۦ لِيَكُونَ لِلْعَٰلَمِينَ نَذِيرًا",
    "الَّذِى لَهُۥ مُلْكُ السَّمَٰوَٰتِ وَالْأَرْضِ وَلَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُۥ شَرِيكٌ فِى الْمُلْكِ وَخَلَقَ كُلَّ شَىْءٍ فَقَدَّرَهُۥ تَقْدِيرًا",
    "وَاتَّخَذُوا مِن دُونِهِۦٓ ءَالِهَةً لَّا يَخْلُقُونَ شَئًْا وَهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِأَنفُسِهِمْ ضَرًّا وَلَا نَفْعًا وَلَا يَمْلِكُونَ مَوْتًا وَلَا حَيَوٰةً وَلَا نُشُورًا",
    "وَقَالَ الَّذِينَ كَفَرُوٓا إِنْ هَٰذَآ إِلَّآ إِفْكٌ افْتَرَىٰهُ وَأَعَانَهُۥ عَلَيْهِ قَوْمٌ ءَاخَرُونَ  فَقَدْ جَآءُو ظُلْمًا وَزُورًا",
    "وَقَالُوٓا أَسَٰطِيرُ الْأَوَّلِينَ اكْتَتَبَهَا فَهِىَ تُمْلَىٰ عَلَيْهِ بُكْرَةً وَأَصِيلًا",
    "قُلْ أَنزَلَهُ الَّذِى يَعْلَمُ السِّرَّ فِى السَّمَٰوَٰتِ وَالْأَرْضِ  إِنَّهُۥ كَانَ غَفُورًا رَّحِيمًا",
    "وَقَالُوا مَالِ هَٰذَا الرَّسُولِ يَأْكُلُ الطَّعَامَ وَيَمْشِى فِى الْأَسْوَاقِ  لَوْلَآ أُنزِلَ إِلَيْهِ مَلَكٌ فَيَكُونَ مَعَهُۥ نَذِيرًا",
    "أَوْ يُلْقَىٰٓ إِلَيْهِ كَنزٌ أَوْ تَكُونُ لَهُۥ جَنَّةٌ يَأْكُلُ مِنْهَا  وَقَالَ الظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًا مَّسْحُورًا",
    "انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَٰلَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا",
    "تَبَارَكَ الَّذِىٓ إِن شَآءَ جَعَلَ لَكَ خَيْرًا مِّن ذَٰلِكَ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا الْأَنْهَٰرُ وَيَجْعَل لَّكَ قُصُورًا",
    "بَلْ كَذَّبُوا بِالسَّاعَةِ  وَأَعْتَدْنَا لِمَن كَذَّبَ بِالسَّاعَةِ سَعِيرًا",
    "إِذَا رَأَتْهُم مِّن مَّكَانٍ بَعِيدٍ سَمِعُوا لَهَا تَغَيُّظًا وَزَفِيرًا",
    "وَإِذَآ أُلْقُوا مِنْهَا مَكَانًا ضَيِّقًا مُّقَرَّنِينَ دَعَوْا هُنَالِكَ ثُبُورًا",
    "لَّا تَدْعُوا الْيَوْمَ ثُبُورًا وَٰحِدًا وَادْعُوا ثُبُورًا كَثِيرًا",
    "قُلْ أَذَٰلِكَ خَيْرٌ أَمْ جَنَّةُ الْخُلْدِ الَّتِى وُعِدَ الْمُتَّقُونَ  كَانَتْ لَهُمْ جَزَآءً وَمَصِيرًا",
    "لَّهُمْ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَ  كَانَ عَلَىٰ رَبِّكَ وَعْدًا مَّسُْٔولًا",
    "وَيَوْمَ يَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِن دُونِ اللَّهِ فَيَقُولُ ءَأَنتُمْ أَضْلَلْتُمْ عِبَادِى هَٰٓؤُلَآءِ أَمْ هُمْ ضَلُّوا السَّبِيلَ",
    "قَالُوا سُبْحَٰنَكَ مَا كَانَ يَنبَغِى لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنْ أَوْلِيَآءَ وَلَٰكِن مَّتَّعْتَهُمْ وَءَابَآءَهُمْ حَتَّىٰ نَسُوا الذِّكْرَ وَكَانُوا قَوْمًا بُورًا",
    "فَقَدْ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسْتَطِيعُونَ صَرْفًا وَلَا نَصْرًا  وَمَن يَظْلِم مِّنكُمْ نُذِقْهُ عَذَابًا كَبِيرًا",
    "وَمَآ أَرْسَلْنَا قَبْلَكَ مِنَ الْمُرْسَلِينَ إِلَّآ إِنَّهُمْ لَيَأْكُلُونَ الطَّعَامَ وَيَمْشُونَ فِى الْأَسْوَاقِ  وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً أَتَصْبِرُونَ  وَكَانَ رَبُّكَ بَصِيرًا",
    "۞ وَقَالَ الَّذِينَ لَا يَرْجُونَ لِقَآءَنَا لَوْلَآ أُنزِلَ عَلَيْنَا الْمَلَٰٓئِكَةُ أَوْ نَرَىٰ رَبَّنَا  لَقَدِ اسْتَكْبَرُوا فِىٓ أَنفُسِهِمْ وَعَتَوْ عُتُوًّا كَبِيرًا",
    "يَوْمَ يَرَوْنَ الْمَلَٰٓئِكَةَ لَا بُشْرَىٰ يَوْمَئِذٍ لِّلْمُجْرِمِينَ وَيَقُولُونَ حِجْرًا مَّحْجُورًا",
    "وَقَدِمْنَآ إِلَىٰ مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَٰهُ هَبَآءً مَّنثُورًا",
    "أَصْحَٰبُ الْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُّسْتَقَرًّا وَأَحْسَنُ مَقِيلًا",
    "وَيَوْمَ تَشَقَّقُ السَّمَآءُ بِالْغَمَٰمِ وَنُزِّلَ الْمَلَٰٓئِكَةُ تَنزِيلًا",
    "الْمُلْكُ يَوْمَئِذٍ الْحَقُّ لِلرَّحْمَٰنِ  وَكَانَ يَوْمًا عَلَى الْكَٰفِرِينَ عَسِيرًا",
    "وَيَوْمَ يَعَضُّ الظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَٰلَيْتَنِى اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلًا",
    "يَٰوَيْلَتَىٰ لَيْتَنِى لَمْ أَتَّخِذْ فُلَانًا خَلِيلًا",
    "لَّقَدْ أَضَلَّنِى عَنِ الذِّكْرِ بَعْدَ إِذْ جَآءَنِى  وَكَانَ الشَّيْطَٰنُ لِلْإِنسَٰنِ خَذُولًا",
    "وَقَالَ الرَّسُولُ يَٰرَبِّ إِنَّ قَوْمِى اتَّخَذُوا هَٰذَا الْقُرْءَانَ مَهْجُورًا",
    "وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا مِّنَ الْمُجْرِمِينَ  وَكَفَىٰ بِرَبِّكَ هَادِيًا وَنَصِيرًا",
    "وَقَالَ الَّذِينَ كَفَرُوا لَوْلَا نُزِّلَ عَلَيْهِ الْقُرْءَانُ جُمْلَةً وَٰحِدَةً  كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَ  وَرَتَّلْنَٰهُ تَرْتِيلًا",
    "وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَٰكَ بِالْحَقِّ وَأَحْسَنَ تَفْسِيرًا",
    "الَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَنَّمَ أُولَٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ سَبِيلًا",
    "وَلَقَدْ ءَاتَيْنَا مُوسَى الْكِتَٰبَ وَجَعَلْنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيرًا",
    "فَقُلْنَا اذْهَبَآ إِلَى الْقَوْمِ الَّذِينَ كَذَّبُوا بَِٔايَٰتِنَا فَدَمَّرْنَٰهُمْ تَدْمِيرًا",
    "وَقَوْمَ نُوحٍ لَّمَّا كَذَّبُوا الرُّسُلَ أَغْرَقْنَٰهُمْ وَجَعَلْنَٰهُمْ لِلنَّاسِ ءَايَةً  وَأَعْتَدْنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمًا",
    "وَعَادًا وَثَمُودَا وَأَصْحَٰبَ الرَّسِّ وَقُرُونًا بَيْنَ ذَٰلِكَ كَثِيرًا",
    "وَكُلًّا ضَرَبْنَا لَهُ الْأَمْثَٰلَ  وَكُلًّا تَبَّرْنَا تَتْبِيرًا",
    "وَلَقَدْ أَتَوْا عَلَى الْقَرْيَةِ الَّتِىٓ أُمْطِرَتْ مَطَرَ السَّوْءِ  أَفَلَمْ يَكُونُوا يَرَوْنَهَا  بَلْ كَانُوا لَا يَرْجُونَ نُشُورًا",
    "وَإِذَا رَأَوْكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا الَّذِى بَعَثَ اللَّهُ رَسُولًا",
    "إِن كَادَ لَيُضِلُّنَا عَنْ ءَالِهَتِنَا لَوْلَآ أَن صَبَرْنَا عَلَيْهَا  وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ الْعَذَابَ مَنْ أَضَلُّ سَبِيلًا",
    "أَرَءَيْتَ مَنِ اتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا",
    "أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ  إِنْ هُمْ إِلَّا كَالْأَنْعَٰمِ  بَلْ هُمْ أَضَلُّ سَبِيلًا",
    "أَلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ الظِّلَّ وَلَوْ شَآءَ لَجَعَلَهُۥ سَاكِنًا ثُمَّ جَعَلْنَا الشَّمْسَ عَلَيْهِ دَلِيلًا",
    "ثُمَّ قَبَضْنَٰهُ إِلَيْنَا قَبْضًا يَسِيرًا",
    "وَهُوَ الَّذِى جَعَلَ لَكُمُ الَّيْلَ لِبَاسًا وَالنَّوْمَ سُبَاتًا وَجَعَلَ النَّهَارَ نُشُورًا",
    "وَهُوَ الَّذِىٓ أَرْسَلَ الرِّيَٰحَ بُشْرًا بَيْنَ يَدَىْ رَحْمَتِهِۦ  وَأَنزَلْنَا مِنَ السَّمَآءِ مَآءً طَهُورًا",
    "لِّنُحِْىَ بِهِۦ بَلْدَةً مَّيْتًا وَنُسْقِيَهُۥ مِمَّا خَلَقْنَآ أَنْعَٰمًا وَأَنَاسِىَّ كَثِيرًا",
    "وَلَقَدْ صَرَّفْنَٰهُ بَيْنَهُمْ لِيَذَّكَّرُوا فَأَبَىٰٓ أَكْثَرُ النَّاسِ إِلَّا كُفُورًا",
    "وَلَوْ شِئْنَا لَبَعَثْنَا فِى كُلِّ قَرْيَةٍ نَّذِيرًا",
    "فَلَا تُطِعِ الْكَٰفِرِينَ وَجَٰهِدْهُم بِهِۦ جِهَادًا كَبِيرًا",
    "۞ وَهُوَ الَّذِى مَرَجَ الْبَحْرَيْنِ هَٰذَا عَذْبٌ فُرَاتٌ وَهَٰذَا مِلْحٌ أُجَاجٌ وَجَعَلَ بَيْنَهُمَا بَرْزَخًا وَحِجْرًا مَّحْجُورًا",
    "وَهُوَ الَّذِى خَلَقَ مِنَ الْمَآءِ بَشَرًا فَجَعَلَهُۥ نَسَبًا وَصِهْرًا  وَكَانَ رَبُّكَ قَدِيرًا",
    "وَيَعْبُدُونَ مِن دُونِ اللَّهِ مَا لَا يَنفَعُهُمْ وَلَا يَضُرُّهُمْ  وَكَانَ الْكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرًا",
    "وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًا وَنَذِيرًا",
    "قُلْ مَآ أَسَْٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلًا",
    "وَتَوَكَّلْ عَلَى الْحَىِّ الَّذِى لَا يَمُوتُ وَسَبِّحْ بِحَمْدِهِۦ  وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا",
    "الَّذِى خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ  الرَّحْمَٰنُ فَسَْٔلْ بِهِۦ خَبِيرًا",
    "وَإِذَا قِيلَ لَهُمُ اسْجُدُوا لِلرَّحْمَٰنِ قَالُوا وَمَا الرَّحْمَٰنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًا",
    "تَبَارَكَ الَّذِى جَعَلَ فِى السَّمَآءِ بُرُوجًا وَجَعَلَ فِيهَا سِرَٰجًا وَقَمَرًا مُّنِيرًا",
    "وَهُوَ الَّذِى جَعَلَ الَّيْلَ وَالنَّهَارَ خِلْفَةً لِّمَنْ أَرَادَ أَن يَذَّكَّرَ أَوْ أَرَادَ شُكُورًا",
    "وَعِبَادُ الرَّحْمَٰنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ الْجَٰهِلُونَ قَالُوا سَلَٰمًا",
    "وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَٰمًا",
    "وَالَّذِينَ يَقُولُونَ رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ  إِنَّ عَذَابَهَا كَانَ غَرَامًا",
    "إِنَّهَا سَآءَتْ مُسْتَقَرًّا وَمُقَامًا",
    "وَالَّذِينَ إِذَآ أَنفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذَٰلِكَ قَوَامًا",
    "وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِى حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ  وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًا",
    "يُضَٰعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَٰمَةِ وَيَخْلُدْ فِيهِۦ مُهَانًا",
    "إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًا صَٰلِحًا فَأُولَٰٓئِكَ يُبَدِّلُ اللَّهُ سَئَِّاتِهِمْ حَسَنَٰتٍ  وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا",
    "وَمَن تَابَ وَعَمِلَ صَٰلِحًا فَإِنَّهُۥ يَتُوبُ إِلَى اللَّهِ مَتَابًا",
    "وَالَّذِينَ لَا يَشْهَدُونَ الزُّورَ وَإِذَا مَرُّوا بِاللَّغْوِ مَرُّوا كِرَامًا",
    "وَالَّذِينَ إِذَا ذُكِّرُوا بَِٔايَٰتِ رَبِّهِمْ لَمْ يَخِرُّوا عَلَيْهَا صُمًّا وَعُمْيَانًا",
    "وَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا",
    "أُولَٰٓئِكَ يُجْزَوْنَ الْغُرْفَةَ بِمَا صَبَرُوا وَيُلَقَّوْنَ فِيهَا تَحِيَّةً وَسَلَٰمًا",
    "خَٰلِدِينَ فِيهَا  حَسُنَتْ مُسْتَقَرًّا وَمُقَامًا",
    "قُلْ مَا يَعْبَؤُا بِكُمْ رَبِّى لَوْلَا دُعَآؤُكُمْ  فَقَدْ كَذَّبْتُمْ فَسَوْفَ يَكُونُ لِزَامًا",
  ],
  26: [
    "طسٓمٓ",
    "تِلْكَ ءَايَٰتُ الْكِتَٰبِ الْمُبِينِ",
    "لَعَلَّكَ بَٰخِعٌ نَّفْسَكَ أَلَّا يَكُونُوا مُؤْمِنِينَ",
    "إِن نَّشَأْ نُنَزِّلْ عَلَيْهِم مِّنَ السَّمَآءِ ءَايَةً فَظَلَّتْ أَعْنَٰقُهُمْ لَهَا خَٰضِعِينَ",
    "وَمَا يَأْتِيهِم مِّن ذِكْرٍ مِّنَ الرَّحْمَٰنِ مُحْدَثٍ إِلَّا كَانُوا عَنْهُ مُعْرِضِينَ",
    "فَقَدْ كَذَّبُوا فَسَيَأْتِيهِمْ أَنبَٰٓؤُا مَا كَانُوا بِهِۦ يَسْتَهْزِءُونَ",
    "أَوَلَمْ يَرَوْا إِلَى الْأَرْضِ كَمْ أَنبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ",
    "إِنَّ فِى ذَٰلِكَ لََٔايَةً  وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ",
    "وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ",
    "وَإِذْ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ائْتِ الْقَوْمَ الظَّٰلِمِينَ",
    "قَوْمَ فِرْعَوْنَ  أَلَا يَتَّقُونَ",
    "قَالَ رَبِّ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ",
    "وَيَضِيقُ صَدْرِى وَلَا يَنطَلِقُ لِسَانِى فَأَرْسِلْ إِلَىٰ هَٰرُونَ",
    "وَلَهُمْ عَلَىَّ ذَنبٌ فَأَخَافُ أَن يَقْتُلُونِ",
    "قَالَ كَلَّا  فَاذْهَبَا بَِٔايَٰتِنَآ  إِنَّا مَعَكُم مُّسْتَمِعُونَ",
    "فَأْتِيَا فِرْعَوْنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ الْعَٰلَمِينَ",
    "أَنْ أَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ",
    "قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِيدًا وَلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِنِينَ",
    "وَفَعَلْتَ فَعْلَتَكَ الَّتِى فَعَلْتَ وَأَنتَ مِنَ الْكَٰفِرِينَ",
    "قَالَ فَعَلْتُهَآ إِذًا وَأَنَا مِنَ الضَّآلِّينَ",
    "فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِى رَبِّى حُكْمًا وَجَعَلَنِى مِنَ الْمُرْسَلِينَ",
    "وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَىَّ أَنْ عَبَّدتَّ بَنِىٓ إِسْرَٰٓءِيلَ",
    "قَالَ فِرْعَوْنُ وَمَا رَبُّ الْعَٰلَمِينَ",
    "قَالَ رَبُّ السَّمَٰوَٰتِ وَالْأَرْضِ وَمَا بَيْنَهُمَآ  إِن كُنتُم مُّوقِنِينَ",
    "قَالَ لِمَنْ حَوْلَهُۥٓ أَلَا تَسْتَمِعُونَ",
    "قَالَ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ الْأَوَّلِينَ",
    "قَالَ إِنَّ رَسُولَكُمُ الَّذِىٓ أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌ",
    "قَالَ رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ وَمَا بَيْنَهُمَآ  إِن كُنتُمْ تَعْقِلُونَ",
    "قَالَ لَئِنِ اتَّخَذْتَ إِلَٰهًا غَيْرِى لَأَجْعَلَنَّكَ مِنَ الْمَسْجُونِينَ",
    "قَالَ أَوَلَوْ جِئْتُكَ بِشَىْءٍ مُّبِينٍ",
    "قَالَ فَأْتِ بِهِۦٓ إِن كُنتَ مِنَ الصَّٰدِقِينَ",
    "فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ",
    "وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ",
    "قَالَ لِلْمَلَإِ حَوْلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌ",
    "يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُم بِسِحْرِهِۦ فَمَاذَا تَأْمُرُونَ",
    "قَالُوٓا أَرْجِهْ وَأَخَاهُ وَابْعَثْ فِى الْمَدَآئِنِ حَٰشِرِينَ",
    "يَأْتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٍ",
    "فَجُمِعَ السَّحَرَةُ لِمِيقَٰتِ يَوْمٍ مَّعْلُومٍ",
    "وَقِيلَ لِلنَّاسِ هَلْ أَنتُم مُّجْتَمِعُونَ",
    "لَعَلَّنَا نَتَّبِعُ السَّحَرَةَ إِن كَانُوا هُمُ الْغَٰلِبِينَ",
    "فَلَمَّا جَآءَ السَّحَرَةُ قَالُوا لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ الْغَٰلِبِينَ",
    "قَالَ نَعَمْ وَإِنَّكُمْ إِذًا لَّمِنَ الْمُقَرَّبِينَ",
    "قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا مَآ أَنتُم مُّلْقُونَ",
    "فَأَلْقَوْا حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُوا بِعِزَّةِ فِرْعَوْنَ إِنَّا لَنَحْنُ الْغَٰلِبُونَ",
    "فَأَلْقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ",
    "فَأُلْقِىَ السَّحَرَةُ سَٰجِدِينَ",
    "قَالُوٓا ءَامَنَّا بِرَبِّ الْعَٰلَمِينَ",
    "رَبِّ مُوسَىٰ وَهَٰرُونَ",
    "قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ  إِنَّهُۥ لَكَبِيرُكُمُ الَّذِى عَلَّمَكُمُ السِّحْرَ فَلَسَوْفَ تَعْلَمُونَ  لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ",
    "قَالُوا لَا ضَيْرَ  إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ",
    "إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ الْمُؤْمِنِينَ",
    "۞ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِىٓ إِنَّكُم مُّتَّبَعُونَ",
    "فَأَرْسَلَ فِرْعَوْنُ فِى الْمَدَآئِنِ حَٰشِرِينَ",
    "إِنَّ هَٰٓؤُلَآءِ لَشِرْذِمَةٌ قَلِيلُونَ",
    "وَإِنَّهُمْ لَنَا لَغَآئِظُونَ",
    "وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ",
    "فَأَخْرَجْنَٰهُم مِّن جَنَّٰتٍ وَعُيُونٍ",
    "وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ",
    "كَذَٰلِكَ وَأَوْرَثْنَٰهَا بَنِىٓ إِسْرَٰٓءِيلَ",
    "فَأَتْبَعُوهُم مُّشْرِقِينَ",
    "فَلَمَّا تَرَٰٓءَا الْجَمْعَانِ قَالَ أَصْحَٰبُ مُوسَىٰٓ إِنَّا لَمُدْرَكُونَ",
    "قَالَ كَلَّآ  إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ",
    "فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ اضْرِب بِّعَصَاكَ الْبَحْرَ  فَانفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَالطَّوْدِ الْعَظِيمِ",
    "وَأَزْلَفْنَا ثَمَّ الَْٔاخَرِينَ",
    "وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ",
    "ثُمَّ أَغْرَقْنَا الَْٔاخَرِينَ",
    "إِنَّ فِى ذَٰلِكَ لََٔايَةً  وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ",
    "وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ",
    "وَاتْلُ عَلَيْهِمْ نَبَأَ إِبْرَٰهِيمَ",
    "إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا تَعْبُدُونَ",
    "قَالُوا نَعْبُدُ أَصْنَامًا فَنَظَلُّ لَهَا عَٰكِفِينَ",
    "قَالَ هَلْ يَسْمَعُونَكُمْ إِذْ تَدْعُونَ",
    "أَوْ يَنفَعُونَكُمْ أَوْ يَضُرُّونَ",
    "قَالُوا بَلْ وَجَدْنَآ ءَابَآءَنَا كَذَٰلِكَ يَفْعَلُونَ",
    "قَالَ أَفَرَءَيْتُم مَّا كُنتُمْ تَعْبُدُونَ",
    "أَنتُمْ وَءَابَآؤُكُمُ الْأَقْدَمُونَ",
    "فَإِنَّهُمْ عَدُوٌّ لِّىٓ إِلَّا رَبَّ الْعَٰلَمِينَ",
    "الَّذِى خَلَقَنِى فَهُوَ يَهْدِينِ",
    "وَالَّذِى هُوَ يُطْعِمُنِى وَيَسْقِينِ",
    "وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ",
    "وَالَّذِى يُمِيتُنِى ثُمَّ يُحْيِينِ",
    "وَالَّذِىٓ أَطْمَعُ أَن يَغْفِرَ لِى خَطِيَٓٔتِى يَوْمَ الدِّينِ",
    "رَبِّ هَبْ لِى حُكْمًا وَأَلْحِقْنِى بِالصَّٰلِحِينَ",
    "وَاجْعَل لِّى لِسَانَ صِدْقٍ فِى الَْٔاخِرِينَ",
    "وَاجْعَلْنِى مِن وَرَثَةِ جَنَّةِ النَّعِيمِ",
    "وَاغْفِرْ لِأَبِىٓ إِنَّهُۥ كَانَ مِنَ الضَّآلِّينَ",
    "وَلَا تُخْزِنِى يَوْمَ يُبْعَثُونَ",
    "يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ",
    "إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ",
    "وَأُزْلِفَتِ الْجَنَّةُ لِلْمُتَّقِينَ",
    "وَبُرِّزَتِ الْجَحِيمُ لِلْغَاوِينَ",
    "وَقِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تَعْبُدُونَ",
    "مِن دُونِ اللَّهِ هَلْ يَنصُرُونَكُمْ أَوْ يَنتَصِرُونَ",
    "فَكُبْكِبُوا فِيهَا هُمْ وَالْغَاوُۥنَ",
    "وَجُنُودُ إِبْلِيسَ أَجْمَعُونَ",
    "قَالُوا وَهُمْ فِيهَا يَخْتَصِمُونَ",
    "تَاللَّهِ إِن كُنَّا لَفِى ضَلَٰلٍ مُّبِينٍ",
    "إِذْ نُسَوِّيكُم بِرَبِّ الْعَٰلَمِينَ",
    "وَمَآ أَضَلَّنَآ إِلَّا الْمُجْرِمُونَ",
    "فَمَا لَنَا مِن شَٰفِعِينَ",
    "وَلَا صَدِيقٍ حَمِيمٍ",
    "فَلَوْ أَنَّ لَنَا كَرَّةً فَنَكُونَ مِنَ الْمُؤْمِنِينَ",
    "إِنَّ فِى ذَٰلِكَ لََٔايَةً  وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ",
    "وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ",
    "كَذَّبَتْ قَوْمُ نُوحٍ الْمُرْسَلِينَ",
    "إِذْ قَالَ لَهُمْ أَخُوهُمْ نُوحٌ أَلَا تَتَّقُونَ",
    "إِنِّى لَكُمْ رَسُولٌ أَمِينٌ",
    "فَاتَّقُوا اللَّهَ وَأَطِيعُونِ",
    "وَمَآ أَسَْٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ  إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ الْعَٰلَمِينَ",
    "فَاتَّقُوا اللَّهَ وَأَطِيعُونِ",
    "۞ قَالُوٓا أَنُؤْمِنُ لَكَ وَاتَّبَعَكَ الْأَرْذَلُونَ",
    "قَالَ وَمَا عِلْمِى بِمَا كَانُوا يَعْمَلُونَ",
    "إِنْ حِسَابُهُمْ إِلَّا عَلَىٰ رَبِّى  لَوْ تَشْعُرُونَ",
    "وَمَآ أَنَا بِطَارِدِ الْمُؤْمِنِينَ",
    "إِنْ أَنَا إِلَّا نَذِيرٌ مُّبِينٌ",
    "قَالُوا لَئِن لَّمْ تَنتَهِ يَٰنُوحُ لَتَكُونَنَّ مِنَ الْمَرْجُومِينَ",
    "قَالَ رَبِّ إِنَّ قَوْمِى كَذَّبُونِ",
    "فَافْتَحْ بَيْنِى وَبَيْنَهُمْ فَتْحًا وَنَجِّنِى وَمَن مَّعِىَ مِنَ الْمُؤْمِنِينَ",
    "فَأَنجَيْنَٰهُ وَمَن مَّعَهُۥ فِى الْفُلْكِ الْمَشْحُونِ",
    "ثُمَّ أَغْرَقْنَا بَعْدُ الْبَاقِينَ",
    "إِنَّ فِى ذَٰلِكَ لََٔايَةً  وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ",
    "وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ",
    "كَذَّبَتْ عَادٌ الْمُرْسَلِينَ",
    "إِذْ قَالَ لَهُمْ أَخُوهُمْ هُودٌ أَلَا تَتَّقُونَ",
    "إِنِّى لَكُمْ رَسُولٌ أَمِينٌ",
    "فَاتَّقُوا اللَّهَ وَأَطِيعُونِ",
    "وَمَآ أَسَْٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ  إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ الْعَٰلَمِينَ",
    "أَتَبْنُونَ بِكُلِّ رِيعٍ ءَايَةً تَعْبَثُونَ",
    "وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمْ تَخْلُدُونَ",
    "وَإِذَا بَطَشْتُم بَطَشْتُمْ جَبَّارِينَ",
    "فَاتَّقُوا اللَّهَ وَأَطِيعُونِ",
    "وَاتَّقُوا الَّذِىٓ أَمَدَّكُم بِمَا تَعْلَمُونَ",
    "أَمَدَّكُم بِأَنْعَٰمٍ وَبَنِينَ",
    "وَجَنَّٰتٍ وَعُيُونٍ",
    "إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ",
    "قَالُوا سَوَآءٌ عَلَيْنَآ أَوَعَظْتَ أَمْ لَمْ تَكُن مِّنَ الْوَٰعِظِينَ",
    "إِنْ هَٰذَآ إِلَّا خُلُقُ الْأَوَّلِينَ",
    "وَمَا نَحْنُ بِمُعَذَّبِينَ",
    "فَكَذَّبُوهُ فَأَهْلَكْنَٰهُمْ  إِنَّ فِى ذَٰلِكَ لََٔايَةً  وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ",
    "وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ",
    "كَذَّبَتْ ثَمُودُ الْمُرْسَلِينَ",
    "إِذْ قَالَ لَهُمْ أَخُوهُمْ صَٰلِحٌ أَلَا تَتَّقُونَ",
    "إِنِّى لَكُمْ رَسُولٌ أَمِينٌ",
    "فَاتَّقُوا اللَّهَ وَأَطِيعُونِ",
    "وَمَآ أَسَْٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ  إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ الْعَٰلَمِينَ",
    "أَتُتْرَكُونَ فِى مَا هَٰهُنَآ ءَامِنِينَ",
    "فِى جَنَّٰتٍ وَعُيُونٍ",
    "وَزُرُوعٍ وَنَخْلٍ طَلْعُهَا هَضِيمٌ",
    "وَتَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتًا فَٰرِهِينَ",
    "فَاتَّقُوا اللَّهَ وَأَطِيعُونِ",
    "وَلَا تُطِيعُوٓا أَمْرَ الْمُسْرِفِينَ",
    "الَّذِينَ يُفْسِدُونَ فِى الْأَرْضِ وَلَا يُصْلِحُونَ",
    "قَالُوٓا إِنَّمَآ أَنتَ مِنَ الْمُسَحَّرِينَ",
    "مَآ أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا فَأْتِ بَِٔايَةٍ إِن كُنتَ مِنَ الصَّٰدِقِينَ",
    "قَالَ هَٰذِهِۦ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ",
    "وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابُ يَوْمٍ عَظِيمٍ",
    "فَعَقَرُوهَا فَأَصْبَحُوا نَٰدِمِينَ",
    "فَأَخَذَهُمُ الْعَذَابُ  إِنَّ فِى ذَٰلِكَ لََٔايَةً  وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ",
    "وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ",
    "كَذَّبَتْ قَوْمُ لُوطٍ الْمُرْسَلِينَ",
    "إِذْ قَالَ لَهُمْ أَخُوهُمْ لُوطٌ أَلَا تَتَّقُونَ",
    "إِنِّى لَكُمْ رَسُولٌ أَمِينٌ",
    "فَاتَّقُوا اللَّهَ وَأَطِيعُونِ",
    "وَمَآ أَسَْٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ  إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ الْعَٰلَمِينَ",
    "أَتَأْتُونَ الذُّكْرَانَ مِنَ الْعَٰلَمِينَ",
    "وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُم مِّنْ أَزْوَٰجِكُم  بَلْ أَنتُمْ قَوْمٌ عَادُونَ",
    "قَالُوا لَئِن لَّمْ تَنتَهِ يَٰلُوطُ لَتَكُونَنَّ مِنَ الْمُخْرَجِينَ",
    "قَالَ إِنِّى لِعَمَلِكُم مِّنَ الْقَالِينَ",
    "رَبِّ نَجِّنِى وَأَهْلِى مِمَّا يَعْمَلُونَ",
    "فَنَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ",
    "إِلَّا عَجُوزًا فِى الْغَٰبِرِينَ",
    "ثُمَّ دَمَّرْنَا الَْٔاخَرِينَ",
    "وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا  فَسَآءَ مَطَرُ الْمُنذَرِينَ",
    "إِنَّ فِى ذَٰلِكَ لََٔايَةً  وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ",
    "وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ",
    "كَذَّبَ أَصْحَٰبُ لَْٔيْكَةِ الْمُرْسَلِينَ",
    "إِذْ قَالَ لَهُمْ شُعَيْبٌ أَلَا تَتَّقُونَ",
    "إِنِّى لَكُمْ رَسُولٌ أَمِينٌ",
    "فَاتَّقُوا اللَّهَ وَأَطِيعُونِ",
    "وَمَآ أَسَْٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ  إِنْ أَجْرِىَ إِلَّا عَلَىٰ رَبِّ الْعَٰلَمِينَ",
    "۞ أَوْفُوا الْكَيْلَ وَلَا تَكُونُوا مِنَ الْمُخْسِرِينَ",
    "وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ",
    "وَلَا تَبْخَسُوا النَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا فِى الْأَرْضِ مُفْسِدِينَ",
    "وَاتَّقُوا الَّذِى خَلَقَكُمْ وَالْجِبِلَّةَ الْأَوَّلِينَ",
    "قَالُوٓا إِنَّمَآ أَنتَ مِنَ الْمُسَحَّرِينَ",
    "وَمَآ أَنتَ إِلَّا بَشَرٌ مِّثْلُنَا وَإِن نَّظُنُّكَ لَمِنَ الْكَٰذِبِينَ",
    "فَأَسْقِطْ عَلَيْنَا كِسَفًا مِّنَ السَّمَآءِ إِن كُنتَ مِنَ الصَّٰدِقِينَ",
    "قَالَ رَبِّىٓ أَعْلَمُ بِمَا تَعْمَلُونَ",
    "فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ الظُّلَّةِ  إِنَّهُۥ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ",
    "إِنَّ فِى ذَٰلِكَ لََٔايَةً  وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ",
    "وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ",
    "وَإِنَّهُۥ لَتَنزِيلُ رَبِّ الْعَٰلَمِينَ",
    "نَزَلَ بِهِ الرُّوحُ الْأَمِينُ",
    "عَلَىٰ قَلْبِكَ لِتَكُونَ مِنَ الْمُنذِرِينَ",
    "بِلِسَانٍ عَرَبِىٍّ مُّبِينٍ",
    "وَإِنَّهُۥ لَفِى زُبُرِ الْأَوَّلِينَ",
    "أَوَلَمْ يَكُن لَّهُمْ ءَايَةً أَن يَعْلَمَهُۥ عُلَمَٰٓؤُا بَنِىٓ إِسْرَٰٓءِيلَ",
    "وَلَوْ نَزَّلْنَٰهُ عَلَىٰ بَعْضِ الْأَعْجَمِينَ",
    "فَقَرَأَهُۥ عَلَيْهِم مَّا كَانُوا بِهِۦ مُؤْمِنِينَ",
    "كَذَٰلِكَ سَلَكْنَٰهُ فِى قُلُوبِ الْمُجْرِمِينَ",
    "لَا يُؤْمِنُونَ بِهِۦ حَتَّىٰ يَرَوُا الْعَذَابَ الْأَلِيمَ",
    "فَيَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ",
    "فَيَقُولُوا هَلْ نَحْنُ مُنظَرُونَ",
    "أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ",
    "أَفَرَءَيْتَ إِن مَّتَّعْنَٰهُمْ سِنِينَ",
    "ثُمَّ جَآءَهُم مَّا كَانُوا يُوعَدُونَ",
    "مَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا يُمَتَّعُونَ",
    "وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا لَهَا مُنذِرُونَ",
    "ذِكْرَىٰ وَمَا كُنَّا ظَٰلِمِينَ",
    "وَمَا تَنَزَّلَتْ بِهِ الشَّيَٰطِينُ",
    "وَمَا يَنبَغِى لَهُمْ وَمَا يَسْتَطِيعُونَ",
    "إِنَّهُمْ عَنِ السَّمْعِ لَمَعْزُولُونَ",
    "فَلَا تَدْعُ مَعَ اللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ مِنَ الْمُعَذَّبِينَ",
    "وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ",
    "وَاخْفِضْ جَنَاحَكَ لِمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ",
    "فَإِنْ عَصَوْكَ فَقُلْ إِنِّى بَرِىٓءٌ مِّمَّا تَعْمَلُونَ",
    "وَتَوَكَّلْ عَلَى الْعَزِيزِ الرَّحِيمِ",
    "الَّذِى يَرَىٰكَ حِينَ تَقُومُ",
    "وَتَقَلُّبَكَ فِى السَّٰجِدِينَ",
    "إِنَّهُۥ هُوَ السَّمِيعُ الْعَلِيمُ",
    "هَلْ أُنَبِّئُكُمْ عَلَىٰ مَن تَنَزَّلُ الشَّيَٰطِينُ",
    "تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٍ",
    "يُلْقُونَ السَّمْعَ وَأَكْثَرُهُمْ كَٰذِبُونَ",
    "وَالشُّعَرَآءُ يَتَّبِعُهُمُ الْغَاوُۥنَ",
    "أَلَمْ تَرَ أَنَّهُمْ فِى كُلِّ وَادٍ يَهِيمُونَ",
    "وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ",
    "إِلَّا الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ وَذَكَرُوا اللَّهَ كَثِيرًا وَانتَصَرُوا مِن بَعْدِ مَا ظُلِمُوا  وَسَيَعْلَمُ الَّذِينَ ظَلَمُوٓا أَىَّ مُنقَلَبٍ يَنقَلِبُونَ",
  ],
  27: [
    "طسٓ  تِلْكَ ءَايَٰتُ الْقُرْءَانِ وَكِتَابٍ مُّبِينٍ",
    "هُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ",
    "الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَيُؤْتُونَ الزَّكَوٰةَ وَهُم بِالَْٔاخِرَةِ هُمْ يُوقِنُونَ",
    "إِنَّ الَّذِينَ لَا يُؤْمِنُونَ بِالَْٔاخِرَةِ زَيَّنَّا لَهُمْ أَعْمَٰلَهُمْ فَهُمْ يَعْمَهُونَ",
    "أُولَٰٓئِكَ الَّذِينَ لَهُمْ سُوٓءُ الْعَذَابِ وَهُمْ فِى الَْٔاخِرَةِ هُمُ الْأَخْسَرُونَ",
    "وَإِنَّكَ لَتُلَقَّى الْقُرْءَانَ مِن لَّدُنْ حَكِيمٍ عَلِيمٍ",
    "إِذْ قَالَ مُوسَىٰ لِأَهْلِهِۦٓ إِنِّىٓ ءَانَسْتُ نَارًا سََٔاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ ءَاتِيكُم بِشِهَابٍ قَبَسٍ لَّعَلَّكُمْ تَصْطَلُونَ",
    "فَلَمَّا جَآءَهَا نُودِىَ أَن بُورِكَ مَن فِى النَّارِ وَمَنْ حَوْلَهَا وَسُبْحَٰنَ اللَّهِ رَبِّ الْعَٰلَمِينَ",
    "يَٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا اللَّهُ الْعَزِيزُ الْحَكِيمُ",
    "وَأَلْقِ عَصَاكَ  فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ  يَٰمُوسَىٰ لَا تَخَفْ إِنِّى لَا يَخَافُ لَدَىَّ الْمُرْسَلُونَ",
    "إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسْنًا بَعْدَ سُوٓءٍ فَإِنِّى غَفُورٌ رَّحِيمٌ",
    "وَأَدْخِلْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ  فِى تِسْعِ ءَايَٰتٍ إِلَىٰ فِرْعَوْنَ وَقَوْمِهِۦٓ  إِنَّهُمْ كَانُوا قَوْمًا فَٰسِقِينَ",
    "فَلَمَّا جَآءَتْهُمْ ءَايَٰتُنَا مُبْصِرَةً قَالُوا هَٰذَا سِحْرٌ مُّبِينٌ",
    "وَجَحَدُوا بِهَا وَاسْتَيْقَنَتْهَآ أَنفُسُهُمْ ظُلْمًا وَعُلُوًّا  فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ الْمُفْسِدِينَ",
    "وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ وَسُلَيْمَٰنَ عِلْمًا  وَقَالَا الْحَمْدُ لِلَّهِ الَّذِى فَضَّلَنَا عَلَىٰ كَثِيرٍ مِّنْ عِبَادِهِ الْمُؤْمِنِينَ",
    "وَوَرِثَ سُلَيْمَٰنُ دَاوُۥدَ  وَقَالَ يَٰٓأَيُّهَا النَّاسُ عُلِّمْنَا مَنطِقَ الطَّيْرِ وَأُوتِينَا مِن كُلِّ شَىْءٍ  إِنَّ هَٰذَا لَهُوَ الْفَضْلُ الْمُبِينُ",
    "وَحُشِرَ لِسُلَيْمَٰنَ جُنُودُهُۥ مِنَ الْجِنِّ وَالْإِنسِ وَالطَّيْرِ فَهُمْ يُوزَعُونَ",
    "حَتَّىٰٓ إِذَآ أَتَوْا عَلَىٰ وَادِ النَّمْلِ قَالَتْ نَمْلَةٌ يَٰٓأَيُّهَا النَّمْلُ ادْخُلُوا مَسَٰكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَٰنُ وَجُنُودُهُۥ وَهُمْ لَا يَشْعُرُونَ",
    "فَتَبَسَّمَ ضَاحِكًا مِّن قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَٰلِحًا تَرْضَىٰهُ وَأَدْخِلْنِى بِرَحْمَتِكَ فِى عِبَادِكَ الصَّٰلِحِينَ",
    "وَتَفَقَّدَ الطَّيْرَ فَقَالَ مَا لِىَ لَآ أَرَى الْهُدْهُدَ أَمْ كَانَ مِنَ الْغَآئِبِينَ",
    "لَأُعَذِّبَنَّهُۥ عَذَابًا شَدِيدًا أَوْ لَأَاذْبَحَنَّهُۥٓ أَوْ لَيَأْتِيَنِّى بِسُلْطَٰنٍ مُّبِينٍ",
    "فَمَكَثَ غَيْرَ بَعِيدٍ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِۦ وَجِئْتُكَ مِن سَبَإٍ بِنَبَإٍ يَقِينٍ",
    "إِنِّى وَجَدتُّ امْرَأَةً تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَىْءٍ وَلَهَا عَرْشٌ عَظِيمٌ",
    "وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ اللَّهِ وَزَيَّنَ لَهُمُ الشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ السَّبِيلِ فَهُمْ لَا يَهْتَدُونَ",
    "أَلَّا يَسْجُدُوا لِلَّهِ الَّذِى يُخْرِجُ الْخَبْءَ فِى السَّمَٰوَٰتِ وَالْأَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ",
    "اللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ الْعَرْشِ الْعَظِيمِ",
    "۞ قَالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ الْكَٰذِبِينَ",
    "اذْهَب بِّكِتَٰبِى هَٰذَا فَأَلْقِهْ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَانظُرْ مَاذَا يَرْجِعُونَ",
    "قَالَتْ يَٰٓأَيُّهَا الْمَلَؤُا إِنِّىٓ أُلْقِىَ إِلَىَّ كِتَٰبٌ كَرِيمٌ",
    "إِنَّهُۥ مِن سُلَيْمَٰنَ وَإِنَّهُۥ بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ",
    "أَلَّا تَعْلُوا عَلَىَّ وَأْتُونِى مُسْلِمِينَ",
    "قَالَتْ يَٰٓأَيُّهَا الْمَلَؤُا أَفْتُونِى فِىٓ أَمْرِى مَا كُنتُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَدُونِ",
    "قَالُوا نَحْنُ أُولُوا قُوَّةٍ وَأُولُوا بَأْسٍ شَدِيدٍ وَالْأَمْرُ إِلَيْكِ فَانظُرِى مَاذَا تَأْمُرِينَ",
    "قَالَتْ إِنَّ الْمُلُوكَ إِذَا دَخَلُوا قَرْيَةً أَفْسَدُوهَا وَجَعَلُوٓا أَعِزَّةَ أَهْلِهَآ أَذِلَّةً  وَكَذَٰلِكَ يَفْعَلُونَ",
    "وَإِنِّى مُرْسِلَةٌ إِلَيْهِم بِهَدِيَّةٍ فَنَاظِرَةٌ بِمَ يَرْجِعُ الْمُرْسَلُونَ",
    "فَلَمَّا جَآءَ سُلَيْمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٍ فَمَآ ءَاتَىٰنِۦَ اللَّهُ خَيْرٌ مِّمَّآ ءَاتَىٰكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ",
    "ارْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُم بِجُنُودٍ لَّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَآ أَذِلَّةً وَهُمْ صَٰغِرُونَ",
    "قَالَ يَٰٓأَيُّهَا الْمَلَؤُا أَيُّكُمْ يَأْتِينِى بِعَرْشِهَا قَبْلَ أَن يَأْتُونِى مُسْلِمِينَ",
    "قَالَ عِفْرِيتٌ مِّنَ الْجِنِّ أَنَا ءَاتِيكَ بِهِۦ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ  وَإِنِّى عَلَيْهِ لَقَوِىٌّ أَمِينٌ",
    "قَالَ الَّذِى عِندَهُۥ عِلْمٌ مِّنَ الْكِتَٰبِ أَنَا ءَاتِيكَ بِهِۦ قَبْلَ أَن يَرْتَدَّ إِلَيْكَ طَرْفُكَ  فَلَمَّا رَءَاهُ مُسْتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضْلِ رَبِّى لِيَبْلُوَنِىٓ ءَأَشْكُرُ أَمْ أَكْفُرُ  وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ  وَمَن كَفَرَ فَإِنَّ رَبِّى غَنِىٌّ كَرِيمٌ",
    "قَالَ نَكِّرُوا لَهَا عَرْشَهَا نَنظُرْ أَتَهْتَدِىٓ أَمْ تَكُونُ مِنَ الَّذِينَ لَا يَهْتَدُونَ",
    "فَلَمَّا جَآءَتْ قِيلَ أَهَٰكَذَا عَرْشُكِ  قَالَتْ كَأَنَّهُۥ هُوَ  وَأُوتِينَا الْعِلْمَ مِن قَبْلِهَا وَكُنَّا مُسْلِمِينَ",
    "وَصَدَّهَا مَا كَانَت تَّعْبُدُ مِن دُونِ اللَّهِ  إِنَّهَا كَانَتْ مِن قَوْمٍ كَٰفِرِينَ",
    "قِيلَ لَهَا ادْخُلِى الصَّرْحَ  فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَن سَاقَيْهَا  قَالَ إِنَّهُۥ صَرْحٌ مُّمَرَّدٌ مِّن قَوَارِيرَ  قَالَتْ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى وَأَسْلَمْتُ مَعَ سُلَيْمَٰنَ لِلَّهِ رَبِّ الْعَٰلَمِينَ",
    "وَلَقَدْ أَرْسَلْنَآ إِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا أَنِ اعْبُدُوا اللَّهَ فَإِذَا هُمْ فَرِيقَانِ يَخْتَصِمُونَ",
    "قَالَ يَٰقَوْمِ لِمَ تَسْتَعْجِلُونَ بِالسَّيِّئَةِ قَبْلَ الْحَسَنَةِ  لَوْلَا تَسْتَغْفِرُونَ اللَّهَ لَعَلَّكُمْ تُرْحَمُونَ",
    "قَالُوا اطَّيَّرْنَا بِكَ وَبِمَن مَّعَكَ  قَالَ طَٰٓئِرُكُمْ عِندَ اللَّهِ  بَلْ أَنتُمْ قَوْمٌ تُفْتَنُونَ",
    "وَكَانَ فِى الْمَدِينَةِ تِسْعَةُ رَهْطٍ يُفْسِدُونَ فِى الْأَرْضِ وَلَا يُصْلِحُونَ",
    "قَالُوا تَقَاسَمُوا بِاللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهْلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدْنَا مَهْلِكَ أَهْلِهِۦ وَإِنَّا لَصَٰدِقُونَ",
    "وَمَكَرُوا مَكْرًا وَمَكَرْنَا مَكْرًا وَهُمْ لَا يَشْعُرُونَ",
    "فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ مَكْرِهِمْ أَنَّا دَمَّرْنَٰهُمْ وَقَوْمَهُمْ أَجْمَعِينَ",
    "فَتِلْكَ بُيُوتُهُمْ خَاوِيَةً بِمَا ظَلَمُوٓا  إِنَّ فِى ذَٰلِكَ لََٔايَةً لِّقَوْمٍ يَعْلَمُونَ",
    "وَأَنجَيْنَا الَّذِينَ ءَامَنُوا وَكَانُوا يَتَّقُونَ",
    "وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ الْفَٰحِشَةَ وَأَنتُمْ تُبْصِرُونَ",
    "أَئِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَآءِ  بَلْ أَنتُمْ قَوْمٌ تَجْهَلُونَ",
    "۞ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا أَخْرِجُوٓا ءَالَ لُوطٍ مِّن قَرْيَتِكُمْ  إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ",
    "فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا امْرَأَتَهُۥ قَدَّرْنَٰهَا مِنَ الْغَٰبِرِينَ",
    "وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا  فَسَآءَ مَطَرُ الْمُنذَرِينَ",
    "قُلِ الْحَمْدُ لِلَّهِ وَسَلَٰمٌ عَلَىٰ عِبَادِهِ الَّذِينَ اصْطَفَىٰٓ  ءَآللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ",
    "أَمَّنْ خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ وَأَنزَلَ لَكُم مِّنَ السَّمَآءِ مَآءً فَأَنبَتْنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهْجَةٍ مَّا كَانَ لَكُمْ أَن تُنبِتُوا شَجَرَهَآ  أَءِلَٰهٌ مَّعَ اللَّهِ  بَلْ هُمْ قَوْمٌ يَعْدِلُونَ",
    "أَمَّن جَعَلَ الْأَرْضَ قَرَارًا وَجَعَلَ خِلَٰلَهَآ أَنْهَٰرًا وَجَعَلَ لَهَا رَوَٰسِىَ وَجَعَلَ بَيْنَ الْبَحْرَيْنِ حَاجِزًا  أَءِلَٰهٌ مَّعَ اللَّهِ  بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ",
    "أَمَّن يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ الْأَرْضِ  أَءِلَٰهٌ مَّعَ اللَّهِ  قَلِيلًا مَّا تَذَكَّرُونَ",
    "أَمَّن يَهْدِيكُمْ فِى ظُلُمَٰتِ الْبَرِّ وَالْبَحْرِ وَمَن يُرْسِلُ الرِّيَٰحَ بُشْرًا بَيْنَ يَدَىْ رَحْمَتِهِۦٓ  أَءِلَٰهٌ مَّعَ اللَّهِ  تَعَٰلَى اللَّهُ عَمَّا يُشْرِكُونَ",
    "أَمَّن يَبْدَؤُا الْخَلْقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرْزُقُكُم مِّنَ السَّمَآءِ وَالْأَرْضِ  أَءِلَٰهٌ مَّعَ اللَّهِ  قُلْ هَاتُوا بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ",
    "قُل لَّا يَعْلَمُ مَن فِى السَّمَٰوَٰتِ وَالْأَرْضِ الْغَيْبَ إِلَّا اللَّهُ  وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ",
    "بَلِ ادَّٰرَكَ عِلْمُهُمْ فِى الَْٔاخِرَةِ  بَلْ هُمْ فِى شَكٍّ مِّنْهَا  بَلْ هُم مِّنْهَا عَمُونَ",
    "وَقَالَ الَّذِينَ كَفَرُوٓا أَءِذَا كُنَّا تُرَٰبًا وَءَابَآؤُنَآ أَئِنَّا لَمُخْرَجُونَ",
    "لَقَدْ وُعِدْنَا هَٰذَا نَحْنُ وَءَابَآؤُنَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ الْأَوَّلِينَ",
    "قُلْ سِيرُوا فِى الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَٰقِبَةُ الْمُجْرِمِينَ",
    "وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُن فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ",
    "وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ",
    "قُلْ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعْضُ الَّذِى تَسْتَعْجِلُونَ",
    "وَإِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ",
    "وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ",
    "وَمَا مِنْ غَآئِبَةٍ فِى السَّمَآءِ وَالْأَرْضِ إِلَّا فِى كِتَٰبٍ مُّبِينٍ",
    "إِنَّ هَٰذَا الْقُرْءَانَ يَقُصُّ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَكْثَرَ الَّذِى هُمْ فِيهِ يَخْتَلِفُونَ",
    "وَإِنَّهُۥ لَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ",
    "إِنَّ رَبَّكَ يَقْضِى بَيْنَهُم بِحُكْمِهِۦ  وَهُوَ الْعَزِيزُ الْعَلِيمُ",
    "فَتَوَكَّلْ عَلَى اللَّهِ  إِنَّكَ عَلَى الْحَقِّ الْمُبِينِ",
    "إِنَّكَ لَا تُسْمِعُ الْمَوْتَىٰ وَلَا تُسْمِعُ الصُّمَّ الدُّعَآءَ إِذَا وَلَّوْا مُدْبِرِينَ",
    "وَمَآ أَنتَ بِهَٰدِى الْعُمْىِ عَن ضَلَٰلَتِهِمْ  إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بَِٔايَٰتِنَا فَهُم مُّسْلِمُونَ",
    "۞ وَإِذَا وَقَعَ الْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَآبَّةً مِّنَ الْأَرْضِ تُكَلِّمُهُمْ أَنَّ النَّاسَ كَانُوا بَِٔايَٰتِنَا لَا يُوقِنُونَ",
    "وَيَوْمَ نَحْشُرُ مِن كُلِّ أُمَّةٍ فَوْجًا مِّمَّن يُكَذِّبُ بَِٔايَٰتِنَا فَهُمْ يُوزَعُونَ",
    "حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبْتُم بَِٔايَٰتِى وَلَمْ تُحِيطُوا بِهَا عِلْمًا أَمَّاذَا كُنتُمْ تَعْمَلُونَ",
    "وَوَقَعَ الْقَوْلُ عَلَيْهِم بِمَا ظَلَمُوا فَهُمْ لَا يَنطِقُونَ",
    "أَلَمْ يَرَوْا أَنَّا جَعَلْنَا الَّيْلَ لِيَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ",
    "وَيَوْمَ يُنفَخُ فِى الصُّورِ فَفَزِعَ مَن فِى السَّمَٰوَٰتِ وَمَن فِى الْأَرْضِ إِلَّا مَن شَآءَ اللَّهُ  وَكُلٌّ أَتَوْهُ دَٰخِرِينَ",
    "وَتَرَى الْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِىَ تَمُرُّ مَرَّ السَّحَابِ  صُنْعَ اللَّهِ الَّذِىٓ أَتْقَنَ كُلَّ شَىْءٍ  إِنَّهُۥ خَبِيرٌ بِمَا تَفْعَلُونَ",
    "مَن جَآءَ بِالْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا وَهُم مِّن فَزَعٍ يَوْمَئِذٍ ءَامِنُونَ",
    "وَمَن جَآءَ بِالسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِى النَّارِ هَلْ تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ",
    "إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَٰذِهِ الْبَلْدَةِ الَّذِى حَرَّمَهَا وَلَهُۥ كُلُّ شَىْءٍ  وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُسْلِمِينَ",
    "وَأَنْ أَتْلُوَا الْقُرْءَانَ  فَمَنِ اهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ  وَمَن ضَلَّ فَقُلْ إِنَّمَآ أَنَا مِنَ الْمُنذِرِينَ",
    "وَقُلِ الْحَمْدُ لِلَّهِ سَيُرِيكُمْ ءَايَٰتِهِۦ فَتَعْرِفُونَهَا  وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ",
  ],
  28: [
    "طسٓمٓ",
    "تِلْكَ ءَايَٰتُ الْكِتَٰبِ الْمُبِينِ",
    "نَتْلُوا عَلَيْكَ مِن نَّبَإِ مُوسَىٰ وَفِرْعَوْنَ بِالْحَقِّ لِقَوْمٍ يُؤْمِنُونَ",
    "إِنَّ فِرْعَوْنَ عَلَا فِى الْأَرْضِ وَجَعَلَ أَهْلَهَا شِيَعًا يَسْتَضْعِفُ طَآئِفَةً مِّنْهُمْ يُذَبِّحُ أَبْنَآءَهُمْ وَيَسْتَحْىِۦ نِسَآءَهُمْ  إِنَّهُۥ كَانَ مِنَ الْمُفْسِدِينَ",
    "وَنُرِيدُ أَن نَّمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُوا فِى الْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ الْوَٰرِثِينَ",
    "وَنُمَكِّنَ لَهُمْ فِى الْأَرْضِ وَنُرِىَ فِرْعَوْنَ وَهَٰمَٰنَ وَجُنُودَهُمَا مِنْهُم مَّا كَانُوا يَحْذَرُونَ",
    "وَأَوْحَيْنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنْ أَرْضِعِيهِ  فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِى الْيَمِّ وَلَا تَخَافِى وَلَا تَحْزَنِىٓ  إِنَّا رَآدُّوهُ إِلَيْكِ وَجَاعِلُوهُ مِنَ الْمُرْسَلِينَ",
    "فَالْتَقَطَهُۥٓ ءَالُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَنًا  إِنَّ فِرْعَوْنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُوا خَٰطِِٔينَ",
    "وَقَالَتِ امْرَأَتُ فِرْعَوْنَ قُرَّتُ عَيْنٍ لِّى وَلَكَ  لَا تَقْتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًا وَهُمْ لَا يَشْعُرُونَ",
    "وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًا  إِن كَادَتْ لَتُبْدِى بِهِۦ لَوْلَآ أَن رَّبَطْنَا عَلَىٰ قَلْبِهَا لِتَكُونَ مِنَ الْمُؤْمِنِينَ",
    "وَقَالَتْ لِأُخْتِهِۦ قُصِّيهِ  فَبَصُرَتْ بِهِۦ عَن جُنُبٍ وَهُمْ لَا يَشْعُرُونَ",
    "۞ وَحَرَّمْنَا عَلَيْهِ الْمَرَاضِعَ مِن قَبْلُ فَقَالَتْ هَلْ أَدُلُّكُمْ عَلَىٰٓ أَهْلِ بَيْتٍ يَكْفُلُونَهُۥ لَكُمْ وَهُمْ لَهُۥ نَٰصِحُونَ",
    "فَرَدَدْنَٰهُ إِلَىٰٓ أُمِّهِۦ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ وَلِتَعْلَمَ أَنَّ وَعْدَ اللَّهِ حَقٌّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ",
    "وَلَمَّا بَلَغَ أَشُدَّهُۥ وَاسْتَوَىٰٓ ءَاتَيْنَٰهُ حُكْمًا وَعِلْمًا  وَكَذَٰلِكَ نَجْزِى الْمُحْسِنِينَ",
    "وَدَخَلَ الْمَدِينَةَ عَلَىٰ حِينِ غَفْلَةٍ مِّنْ أَهْلِهَا فَوَجَدَ فِيهَا رَجُلَيْنِ يَقْتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنْ عَدُوِّهِۦ  فَاسْتَغَٰثَهُ الَّذِى مِن شِيعَتِهِۦ عَلَى الَّذِى مِنْ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَيْهِ  قَالَ هَٰذَا مِنْ عَمَلِ الشَّيْطَٰنِ  إِنَّهُۥ عَدُوٌّ مُّضِلٌّ مُّبِينٌ",
    "قَالَ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى فَاغْفِرْ لِى فَغَفَرَ لَهُۥٓ  إِنَّهُۥ هُوَ الْغَفُورُ الرَّحِيمُ",
    "قَالَ رَبِّ بِمَآ أَنْعَمْتَ عَلَىَّ فَلَنْ أَكُونَ ظَهِيرًا لِّلْمُجْرِمِينَ",
    "فَأَصْبَحَ فِى الْمَدِينَةِ خَآئِفًا يَتَرَقَّبُ فَإِذَا الَّذِى اسْتَنصَرَهُۥ بِالْأَمْسِ يَسْتَصْرِخُهُۥ  قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِىٌّ مُّبِينٌ",
    "فَلَمَّآ أَنْ أَرَادَ أَن يَبْطِشَ بِالَّذِى هُوَ عَدُوٌّ لَّهُمَا قَالَ يَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقْتُلَنِى كَمَا قَتَلْتَ نَفْسًا بِالْأَمْسِ  إِن تُرِيدُ إِلَّآ أَن تَكُونَ جَبَّارًا فِى الْأَرْضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ الْمُصْلِحِينَ",
    "وَجَآءَ رَجُلٌ مِّنْ أَقْصَا الْمَدِينَةِ يَسْعَىٰ قَالَ يَٰمُوسَىٰٓ إِنَّ الْمَلَأَ يَأْتَمِرُونَ بِكَ لِيَقْتُلُوكَ فَاخْرُجْ إِنِّى لَكَ مِنَ النَّٰصِحِينَ",
    "فَخَرَجَ مِنْهَا خَآئِفًا يَتَرَقَّبُ  قَالَ رَبِّ نَجِّنِى مِنَ الْقَوْمِ الظَّٰلِمِينَ",
    "وَلَمَّا تَوَجَّهَ تِلْقَآءَ مَدْيَنَ قَالَ عَسَىٰ رَبِّىٓ أَن يَهْدِيَنِى سَوَآءَ السَّبِيلِ",
    "وَلَمَّا وَرَدَ مَآءَ مَدْيَنَ وَجَدَ عَلَيْهِ أُمَّةً مِّنَ النَّاسِ يَسْقُونَ وَوَجَدَ مِن دُونِهِمُ امْرَأَتَيْنِ تَذُودَانِ  قَالَ مَا خَطْبُكُمَا  قَالَتَا لَا نَسْقِى حَتَّىٰ يُصْدِرَ الرِّعَآءُ  وَأَبُونَا شَيْخٌ كَبِيرٌ",
    "فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى الظِّلِّ فَقَالَ رَبِّ إِنِّى لِمَآ أَنزَلْتَ إِلَىَّ مِنْ خَيْرٍ فَقِيرٌ",
    "فَجَآءَتْهُ إِحْدَىٰهُمَا تَمْشِى عَلَى اسْتِحْيَآءٍ قَالَتْ إِنَّ أَبِى يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا  فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيْهِ الْقَصَصَ قَالَ لَا تَخَفْ  نَجَوْتَ مِنَ الْقَوْمِ الظَّٰلِمِينَ",
    "قَالَتْ إِحْدَىٰهُمَا يَٰٓأَبَتِ اسْتَْٔجِرْهُ  إِنَّ خَيْرَ مَنِ اسْتَْٔجَرْتَ الْقَوِىُّ الْأَمِينُ",
    "قَالَ إِنِّىٓ أُرِيدُ أَنْ أُنكِحَكَ إِحْدَى ابْنَتَىَّ هَٰتَيْنِ عَلَىٰٓ أَن تَأْجُرَنِى ثَمَٰنِىَ حِجَجٍ  فَإِنْ أَتْمَمْتَ عَشْرًا فَمِنْ عِندِكَ  وَمَآ أُرِيدُ أَنْ أَشُقَّ عَلَيْكَ  سَتَجِدُنِىٓ إِن شَآءَ اللَّهُ مِنَ الصَّٰلِحِينَ",
    "قَالَ ذَٰلِكَ بَيْنِى وَبَيْنَكَ  أَيَّمَا الْأَجَلَيْنِ قَضَيْتُ فَلَا عُدْوَٰنَ عَلَىَّ  وَاللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌ",
    "۞ فَلَمَّا قَضَىٰ مُوسَى الْأَجَلَ وَسَارَ بِأَهْلِهِۦٓ ءَانَسَ مِن جَانِبِ الطُّورِ نَارًا قَالَ لِأَهْلِهِ امْكُثُوٓا إِنِّىٓ ءَانَسْتُ نَارًا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ جَذْوَةٍ مِّنَ النَّارِ لَعَلَّكُمْ تَصْطَلُونَ",
    "فَلَمَّآ أَتَىٰهَا نُودِىَ مِن شَٰطِئِ الْوَادِ الْأَيْمَنِ فِى الْبُقْعَةِ الْمُبَٰرَكَةِ مِنَ الشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّىٓ أَنَا اللَّهُ رَبُّ الْعَٰلَمِينَ",
    "وَأَنْ أَلْقِ عَصَاكَ  فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ  يَٰمُوسَىٰٓ أَقْبِلْ وَلَا تَخَفْ  إِنَّكَ مِنَ الَْٔامِنِينَ",
    "اسْلُكْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ وَاضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ الرَّهْبِ  فَذَٰنِكَ بُرْهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرْعَوْنَ وَمَلَإِيهِۦٓ  إِنَّهُمْ كَانُوا قَوْمًا فَٰسِقِينَ",
    "قَالَ رَبِّ إِنِّى قَتَلْتُ مِنْهُمْ نَفْسًا فَأَخَافُ أَن يَقْتُلُونِ",
    "وَأَخِى هَٰرُونُ هُوَ أَفْصَحُ مِنِّى لِسَانًا فَأَرْسِلْهُ مَعِىَ رِدْءًا يُصَدِّقُنِىٓ  إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ",
    "قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَٰنًا فَلَا يَصِلُونَ إِلَيْكُمَا  بَِٔايَٰتِنَآ أَنتُمَا وَمَنِ اتَّبَعَكُمَا الْغَٰلِبُونَ",
    "فَلَمَّا جَآءَهُم مُّوسَىٰ بَِٔايَٰتِنَا بَيِّنَٰتٍ قَالُوا مَا هَٰذَآ إِلَّا سِحْرٌ مُّفْتَرًى وَمَا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا الْأَوَّلِينَ",
    "وَقَالَ مُوسَىٰ رَبِّىٓ أَعْلَمُ بِمَن جَآءَ بِالْهُدَىٰ مِنْ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَٰقِبَةُ الدَّارِ  إِنَّهُۥ لَا يُفْلِحُ الظَّٰلِمُونَ",
    "وَقَالَ فِرْعَوْنُ يَٰٓأَيُّهَا الْمَلَأُ مَا عَلِمْتُ لَكُم مِّنْ إِلَٰهٍ غَيْرِى فَأَوْقِدْ لِى يَٰهَٰمَٰنُ عَلَى الطِّينِ فَاجْعَل لِّى صَرْحًا لَّعَلِّىٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ مِنَ الْكَٰذِبِينَ",
    "وَاسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِى الْأَرْضِ بِغَيْرِ الْحَقِّ وَظَنُّوٓا أَنَّهُمْ إِلَيْنَا لَا يُرْجَعُونَ",
    "فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى الْيَمِّ  فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ الظَّٰلِمِينَ",
    "وَجَعَلْنَٰهُمْ أَئِمَّةً يَدْعُونَ إِلَى النَّارِ  وَيَوْمَ الْقِيَٰمَةِ لَا يُنصَرُونَ",
    "وَأَتْبَعْنَٰهُمْ فِى هَٰذِهِ الدُّنْيَا لَعْنَةً  وَيَوْمَ الْقِيَٰمَةِ هُم مِّنَ الْمَقْبُوحِينَ",
    "وَلَقَدْ ءَاتَيْنَا مُوسَى الْكِتَٰبَ مِن بَعْدِ مَآ أَهْلَكْنَا الْقُرُونَ الْأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدًى وَرَحْمَةً لَّعَلَّهُمْ يَتَذَكَّرُونَ",
    "وَمَا كُنتَ بِجَانِبِ الْغَرْبِىِّ إِذْ قَضَيْنَآ إِلَىٰ مُوسَى الْأَمْرَ وَمَا كُنتَ مِنَ الشَّٰهِدِينَ",
    "وَلَٰكِنَّآ أَنشَأْنَا قُرُونًا فَتَطَاوَلَ عَلَيْهِمُ الْعُمُرُ  وَمَا كُنتَ ثَاوِيًا فِىٓ أَهْلِ مَدْيَنَ تَتْلُوا عَلَيْهِمْ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرْسِلِينَ",
    "وَمَا كُنتَ بِجَانِبِ الطُّورِ إِذْ نَادَيْنَا وَلَٰكِن رَّحْمَةً مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ",
    "وَلَوْلَآ أَن تُصِيبَهُم مُّصِيبَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَيَقُولُوا رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ مِنَ الْمُؤْمِنِينَ",
    "فَلَمَّا جَآءَهُمُ الْحَقُّ مِنْ عِندِنَا قَالُوا لَوْلَآ أُوتِىَ مِثْلَ مَآ أُوتِىَ مُوسَىٰٓ  أَوَلَمْ يَكْفُرُوا بِمَآ أُوتِىَ مُوسَىٰ مِن قَبْلُ  قَالُوا سِحْرَانِ تَظَٰهَرَا وَقَالُوٓا إِنَّا بِكُلٍّ كَٰفِرُونَ",
    "قُلْ فَأْتُوا بِكِتَٰبٍ مِّنْ عِندِ اللَّهِ هُوَ أَهْدَىٰ مِنْهُمَآ أَتَّبِعْهُ إِن كُنتُمْ صَٰدِقِينَ",
    "فَإِن لَّمْ يَسْتَجِيبُوا لَكَ فَاعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَآءَهُمْ  وَمَنْ أَضَلُّ مِمَّنِ اتَّبَعَ هَوَىٰهُ بِغَيْرِ هُدًى مِّنَ اللَّهِ  إِنَّ اللَّهَ لَا يَهْدِى الْقَوْمَ الظَّٰلِمِينَ",
    "۞ وَلَقَدْ وَصَّلْنَا لَهُمُ الْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَ",
    "الَّذِينَ ءَاتَيْنَٰهُمُ الْكِتَٰبَ مِن قَبْلِهِۦ هُم بِهِۦ يُؤْمِنُونَ",
    "وَإِذَا يُتْلَىٰ عَلَيْهِمْ قَالُوٓا ءَامَنَّا بِهِۦٓ إِنَّهُ الْحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبْلِهِۦ مُسْلِمِينَ",
    "أُولَٰٓئِكَ يُؤْتَوْنَ أَجْرَهُم مَّرَّتَيْنِ بِمَا صَبَرُوا وَيَدْرَءُونَ بِالْحَسَنَةِ السَّيِّئَةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ",
    "وَإِذَا سَمِعُوا اللَّغْوَ أَعْرَضُوا عَنْهُ وَقَالُوا لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ سَلَٰمٌ عَلَيْكُمْ لَا نَبْتَغِى الْجَٰهِلِينَ",
    "إِنَّكَ لَا تَهْدِى مَنْ أَحْبَبْتَ وَلَٰكِنَّ اللَّهَ يَهْدِى مَن يَشَآءُ  وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ",
    "وَقَالُوٓا إِن نَّتَّبِعِ الْهُدَىٰ مَعَكَ نُتَخَطَّفْ مِنْ أَرْضِنَآ  أَوَلَمْ نُمَكِّن لَّهُمْ حَرَمًا ءَامِنًا يُجْبَىٰٓ إِلَيْهِ ثَمَرَٰتُ كُلِّ شَىْءٍ رِّزْقًا مِّن لَّدُنَّا وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ",
    "وَكَمْ أَهْلَكْنَا مِن قَرْيَةٍ بَطِرَتْ مَعِيشَتَهَا  فَتِلْكَ مَسَٰكِنُهُمْ لَمْ تُسْكَن مِّن بَعْدِهِمْ إِلَّا قَلِيلًا  وَكُنَّا نَحْنُ الْوَٰرِثِينَ",
    "وَمَا كَانَ رَبُّكَ مُهْلِكَ الْقُرَىٰ حَتَّىٰ يَبْعَثَ فِىٓ أُمِّهَا رَسُولًا يَتْلُوا عَلَيْهِمْ ءَايَٰتِنَا  وَمَا كُنَّا مُهْلِكِى الْقُرَىٰٓ إِلَّا وَأَهْلُهَا ظَٰلِمُونَ",
    "وَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَٰعُ الْحَيَوٰةِ الدُّنْيَا وَزِينَتُهَا  وَمَا عِندَ اللَّهِ خَيْرٌ وَأَبْقَىٰٓ  أَفَلَا تَعْقِلُونَ",
    "أَفَمَن وَعَدْنَٰهُ وَعْدًا حَسَنًا فَهُوَ لَٰقِيهِ كَمَن مَّتَّعْنَٰهُ مَتَٰعَ الْحَيَوٰةِ الدُّنْيَا ثُمَّ هُوَ يَوْمَ الْقِيَٰمَةِ مِنَ الْمُحْضَرِينَ",
    "وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ الَّذِينَ كُنتُمْ تَزْعُمُونَ",
    "قَالَ الَّذِينَ حَقَّ عَلَيْهِمُ الْقَوْلُ رَبَّنَا هَٰٓؤُلَآءِ الَّذِينَ أَغْوَيْنَآ أَغْوَيْنَٰهُمْ كَمَا غَوَيْنَا  تَبَرَّأْنَآ إِلَيْكَ  مَا كَانُوٓا إِيَّانَا يَعْبُدُونَ",
    "وَقِيلَ ادْعُوا شُرَكَآءَكُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا لَهُمْ وَرَأَوُا الْعَذَابَ  لَوْ أَنَّهُمْ كَانُوا يَهْتَدُونَ",
    "وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ مَاذَآ أَجَبْتُمُ الْمُرْسَلِينَ",
    "فَعَمِيَتْ عَلَيْهِمُ الْأَنبَآءُ يَوْمَئِذٍ فَهُمْ لَا يَتَسَآءَلُونَ",
    "فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًا فَعَسَىٰٓ أَن يَكُونَ مِنَ الْمُفْلِحِينَ",
    "وَرَبُّكَ يَخْلُقُ مَا يَشَآءُ وَيَخْتَارُ  مَا كَانَ لَهُمُ الْخِيَرَةُ  سُبْحَٰنَ اللَّهِ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ",
    "وَرَبُّكَ يَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ",
    "وَهُوَ اللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ  لَهُ الْحَمْدُ فِى الْأُولَىٰ وَالَْٔاخِرَةِ  وَلَهُ الْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ",
    "قُلْ أَرَءَيْتُمْ إِن جَعَلَ اللَّهُ عَلَيْكُمُ الَّيْلَ سَرْمَدًا إِلَىٰ يَوْمِ الْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ اللَّهِ يَأْتِيكُم بِضِيَآءٍ  أَفَلَا تَسْمَعُونَ",
    "قُلْ أَرَءَيْتُمْ إِن جَعَلَ اللَّهُ عَلَيْكُمُ النَّهَارَ سَرْمَدًا إِلَىٰ يَوْمِ الْقِيَٰمَةِ مَنْ إِلَٰهٌ غَيْرُ اللَّهِ يَأْتِيكُم بِلَيْلٍ تَسْكُنُونَ فِيهِ  أَفَلَا تُبْصِرُونَ",
    "وَمِن رَّحْمَتِهِۦ جَعَلَ لَكُمُ الَّيْلَ وَالنَّهَارَ لِتَسْكُنُوا فِيهِ وَلِتَبْتَغُوا مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ",
    "وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَآءِىَ الَّذِينَ كُنتُمْ تَزْعُمُونَ",
    "وَنَزَعْنَا مِن كُلِّ أُمَّةٍ شَهِيدًا فَقُلْنَا هَاتُوا بُرْهَٰنَكُمْ فَعَلِمُوٓا أَنَّ الْحَقَّ لِلَّهِ وَضَلَّ عَنْهُم مَّا كَانُوا يَفْتَرُونَ",
    "۞ إِنَّ قَٰرُونَ كَانَ مِن قَوْمِ مُوسَىٰ فَبَغَىٰ عَلَيْهِمْ  وَءَاتَيْنَٰهُ مِنَ الْكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِالْعُصْبَةِ أُولِى الْقُوَّةِ إِذْ قَالَ لَهُۥ قَوْمُهُۥ لَا تَفْرَحْ  إِنَّ اللَّهَ لَا يُحِبُّ الْفَرِحِينَ",
    "وَابْتَغِ فِيمَآ ءَاتَىٰكَ اللَّهُ الدَّارَ الَْٔاخِرَةَ  وَلَا تَنسَ نَصِيبَكَ مِنَ الدُّنْيَا  وَأَحْسِن كَمَآ أَحْسَنَ اللَّهُ إِلَيْكَ  وَلَا تَبْغِ الْفَسَادَ فِى الْأَرْضِ  إِنَّ اللَّهَ لَا يُحِبُّ الْمُفْسِدِينَ",
    "قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍ عِندِىٓ  أَوَلَمْ يَعْلَمْ أَنَّ اللَّهَ قَدْ أَهْلَكَ مِن قَبْلِهِۦ مِنَ الْقُرُونِ مَنْ هُوَ أَشَدُّ مِنْهُ قُوَّةً وَأَكْثَرُ جَمْعًا  وَلَا يُسَْٔلُ عَن ذُنُوبِهِمُ الْمُجْرِمُونَ",
    "فَخَرَجَ عَلَىٰ قَوْمِهِۦ فِى زِينَتِهِۦ  قَالَ الَّذِينَ يُرِيدُونَ الْحَيَوٰةَ الدُّنْيَا يَٰلَيْتَ لَنَا مِثْلَ مَآ أُوتِىَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٍ",
    "وَقَالَ الَّذِينَ أُوتُوا الْعِلْمَ وَيْلَكُمْ ثَوَابُ اللَّهِ خَيْرٌ لِّمَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا وَلَا يُلَقَّىٰهَآ إِلَّا الصَّٰبِرُونَ",
    "فَخَسَفْنَا بِهِۦ وَبِدَارِهِ الْأَرْضَ فَمَا كَانَ لَهُۥ مِن فِئَةٍ يَنصُرُونَهُۥ مِن دُونِ اللَّهِ وَمَا كَانَ مِنَ الْمُنتَصِرِينَ",
    "وَأَصْبَحَ الَّذِينَ تَمَنَّوْا مَكَانَهُۥ بِالْأَمْسِ يَقُولُونَ وَيْكَأَنَّ اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ  لَوْلَآ أَن مَّنَّ اللَّهُ عَلَيْنَا لَخَسَفَ بِنَا  وَيْكَأَنَّهُۥ لَا يُفْلِحُ الْكَٰفِرُونَ",
    "تِلْكَ الدَّارُ الَْٔاخِرَةُ نَجْعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوًّا فِى الْأَرْضِ وَلَا فَسَادًا  وَالْعَٰقِبَةُ لِلْمُتَّقِينَ",
    "مَن جَآءَ بِالْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا  وَمَن جَآءَ بِالسَّيِّئَةِ فَلَا يُجْزَى الَّذِينَ عَمِلُوا السَّئَِّاتِ إِلَّا مَا كَانُوا يَعْمَلُونَ",
    "إِنَّ الَّذِى فَرَضَ عَلَيْكَ الْقُرْءَانَ لَرَآدُّكَ إِلَىٰ مَعَادٍ  قُل رَّبِّىٓ أَعْلَمُ مَن جَآءَ بِالْهُدَىٰ وَمَنْ هُوَ فِى ضَلَٰلٍ مُّبِينٍ",
    "وَمَا كُنتَ تَرْجُوٓا أَن يُلْقَىٰٓ إِلَيْكَ الْكِتَٰبُ إِلَّا رَحْمَةً مِّن رَّبِّكَ  فَلَا تَكُونَنَّ ظَهِيرًا لِّلْكَٰفِرِينَ",
    "وَلَا يَصُدُّنَّكَ عَنْ ءَايَٰتِ اللَّهِ بَعْدَ إِذْ أُنزِلَتْ إِلَيْكَ  وَادْعُ إِلَىٰ رَبِّكَ  وَلَا تَكُونَنَّ مِنَ الْمُشْرِكِينَ",
    "وَلَا تَدْعُ مَعَ اللَّهِ إِلَٰهًا ءَاخَرَ  لَآ إِلَٰهَ إِلَّا هُوَ  كُلُّ شَىْءٍ هَالِكٌ إِلَّا وَجْهَهُۥ  لَهُ الْحُكْمُ وَإِلَيْهِ تُرْجَعُونَ",
  ],
  29: [
    "الٓمٓ",
    "أَحَسِبَ النَّاسُ أَن يُتْرَكُوٓا أَن يَقُولُوٓا ءَامَنَّا وَهُمْ لَا يُفْتَنُونَ",
    "وَلَقَدْ فَتَنَّا الَّذِينَ مِن قَبْلِهِمْ  فَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ صَدَقُوا وَلَيَعْلَمَنَّ الْكَٰذِبِينَ",
    "أَمْ حَسِبَ الَّذِينَ يَعْمَلُونَ السَّئَِّاتِ أَن يَسْبِقُونَا  سَآءَ مَا يَحْكُمُونَ",
    "مَن كَانَ يَرْجُوا لِقَآءَ اللَّهِ فَإِنَّ أَجَلَ اللَّهِ لََٔاتٍ  وَهُوَ السَّمِيعُ الْعَلِيمُ",
    "وَمَن جَٰهَدَ فَإِنَّمَا يُجَٰهِدُ لِنَفْسِهِۦٓ  إِنَّ اللَّهَ لَغَنِىٌّ عَنِ الْعَٰلَمِينَ",
    "وَالَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ لَنُكَفِّرَنَّ عَنْهُمْ سَئَِّاتِهِمْ وَلَنَجْزِيَنَّهُمْ أَحْسَنَ الَّذِى كَانُوا يَعْمَلُونَ",
    "وَوَصَّيْنَا الْإِنسَٰنَ بِوَٰلِدَيْهِ حُسْنًا  وَإِن جَٰهَدَاكَ لِتُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَآ  إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ",
    "وَالَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ لَنُدْخِلَنَّهُمْ فِى الصَّٰلِحِينَ",
    "وَمِنَ النَّاسِ مَن يَقُولُ ءَامَنَّا بِاللَّهِ فَإِذَآ أُوذِىَ فِى اللَّهِ جَعَلَ فِتْنَةَ النَّاسِ كَعَذَابِ اللَّهِ وَلَئِن جَآءَ نَصْرٌ مِّن رَّبِّكَ لَيَقُولُنَّ إِنَّا كُنَّا مَعَكُمْ  أَوَلَيْسَ اللَّهُ بِأَعْلَمَ بِمَا فِى صُدُورِ الْعَٰلَمِينَ",
    "وَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ ءَامَنُوا وَلَيَعْلَمَنَّ الْمُنَٰفِقِينَ",
    "وَقَالَ الَّذِينَ كَفَرُوا لِلَّذِينَ ءَامَنُوا اتَّبِعُوا سَبِيلَنَا وَلْنَحْمِلْ خَطَٰيَٰكُمْ وَمَا هُم بِحَٰمِلِينَ مِنْ خَطَٰيَٰهُم مِّن شَىْءٍ  إِنَّهُمْ لَكَٰذِبُونَ",
    "وَلَيَحْمِلُنَّ أَثْقَالَهُمْ وَأَثْقَالًا مَّعَ أَثْقَالِهِمْ  وَلَيُسَْٔلُنَّ يَوْمَ الْقِيَٰمَةِ عَمَّا كَانُوا يَفْتَرُونَ",
    "وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا فَأَخَذَهُمُ الطُّوفَانُ وَهُمْ ظَٰلِمُونَ",
    "فَأَنجَيْنَٰهُ وَأَصْحَٰبَ السَّفِينَةِ وَجَعَلْنَٰهَآ ءَايَةً لِّلْعَٰلَمِينَ",
    "وَإِبْرَٰهِيمَ إِذْ قَالَ لِقَوْمِهِ اعْبُدُوا اللَّهَ وَاتَّقُوهُ  ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ",
    "إِنَّمَا تَعْبُدُونَ مِن دُونِ اللَّهِ أَوْثَٰنًا وَتَخْلُقُونَ إِفْكًا  إِنَّ الَّذِينَ تَعْبُدُونَ مِن دُونِ اللَّهِ لَا يَمْلِكُونَ لَكُمْ رِزْقًا فَابْتَغُوا عِندَ اللَّهِ الرِّزْقَ وَاعْبُدُوهُ وَاشْكُرُوا لَهُۥٓ  إِلَيْهِ تُرْجَعُونَ",
    "وَإِن تُكَذِّبُوا فَقَدْ كَذَّبَ أُمَمٌ مِّن قَبْلِكُمْ  وَمَا عَلَى الرَّسُولِ إِلَّا الْبَلَٰغُ الْمُبِينُ",
    "أَوَلَمْ يَرَوْا كَيْفَ يُبْدِئُ اللَّهُ الْخَلْقَ ثُمَّ يُعِيدُهُۥٓ  إِنَّ ذَٰلِكَ عَلَى اللَّهِ يَسِيرٌ",
    "قُلْ سِيرُوا فِى الْأَرْضِ فَانظُرُوا كَيْفَ بَدَأَ الْخَلْقَ  ثُمَّ اللَّهُ يُنشِئُ النَّشْأَةَ الَْٔاخِرَةَ  إِنَّ اللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ",
    "يُعَذِّبُ مَن يَشَآءُ وَيَرْحَمُ مَن يَشَآءُ  وَإِلَيْهِ تُقْلَبُونَ",
    "وَمَآ أَنتُم بِمُعْجِزِينَ فِى الْأَرْضِ وَلَا فِى السَّمَآءِ  وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ",
    "وَالَّذِينَ كَفَرُوا بَِٔايَٰتِ اللَّهِ وَلِقَآئِهِۦٓ أُولَٰٓئِكَ يَئِسُوا مِن رَّحْمَتِى وَأُولَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ",
    "فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا اقْتُلُوهُ أَوْ حَرِّقُوهُ فَأَنجَىٰهُ اللَّهُ مِنَ النَّارِ  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ",
    "وَقَالَ إِنَّمَا اتَّخَذْتُم مِّن دُونِ اللَّهِ أَوْثَٰنًا مَّوَدَّةَ بَيْنِكُمْ فِى الْحَيَوٰةِ الدُّنْيَا  ثُمَّ يَوْمَ الْقِيَٰمَةِ يَكْفُرُ بَعْضُكُم بِبَعْضٍ وَيَلْعَنُ بَعْضُكُم بَعْضًا وَمَأْوَىٰكُمُ النَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ",
    "۞ فََٔامَنَ لَهُۥ لُوطٌ  وَقَالَ إِنِّى مُهَاجِرٌ إِلَىٰ رَبِّىٓ  إِنَّهُۥ هُوَ الْعَزِيزُ الْحَكِيمُ",
    "وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ وَجَعَلْنَا فِى ذُرِّيَّتِهِ النُّبُوَّةَ وَالْكِتَٰبَ وَءَاتَيْنَٰهُ أَجْرَهُۥ فِى الدُّنْيَا  وَإِنَّهُۥ فِى الَْٔاخِرَةِ لَمِنَ الصَّٰلِحِينَ",
    "وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ إِنَّكُمْ لَتَأْتُونَ الْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَٰلَمِينَ",
    "أَئِنَّكُمْ لَتَأْتُونَ الرِّجَالَ وَتَقْطَعُونَ السَّبِيلَ وَتَأْتُونَ فِى نَادِيكُمُ الْمُنكَرَ  فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوا ائْتِنَا بِعَذَابِ اللَّهِ إِن كُنتَ مِنَ الصَّٰدِقِينَ",
    "قَالَ رَبِّ انصُرْنِى عَلَى الْقَوْمِ الْمُفْسِدِينَ",
    "وَلَمَّا جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِالْبُشْرَىٰ قَالُوٓا إِنَّا مُهْلِكُوٓا أَهْلِ هَٰذِهِ الْقَرْيَةِ  إِنَّ أَهْلَهَا كَانُوا ظَٰلِمِينَ",
    "قَالَ إِنَّ فِيهَا لُوطًا  قَالُوا نَحْنُ أَعْلَمُ بِمَن فِيهَا  لَنُنَجِّيَنَّهُۥ وَأَهْلَهُۥٓ إِلَّا امْرَأَتَهُۥ كَانَتْ مِنَ الْغَٰبِرِينَ",
    "وَلَمَّآ أَن جَآءَتْ رُسُلُنَا لُوطًا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالُوا لَا تَخَفْ وَلَا تَحْزَنْ  إِنَّا مُنَجُّوكَ وَأَهْلَكَ إِلَّا امْرَأَتَكَ كَانَتْ مِنَ الْغَٰبِرِينَ",
    "إِنَّا مُنزِلُونَ عَلَىٰٓ أَهْلِ هَٰذِهِ الْقَرْيَةِ رِجْزًا مِّنَ السَّمَآءِ بِمَا كَانُوا يَفْسُقُونَ",
    "وَلَقَد تَّرَكْنَا مِنْهَآ ءَايَةً بَيِّنَةً لِّقَوْمٍ يَعْقِلُونَ",
    "وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا فَقَالَ يَٰقَوْمِ اعْبُدُوا اللَّهَ وَارْجُوا الْيَوْمَ الَْٔاخِرَ وَلَا تَعْثَوْا فِى الْأَرْضِ مُفْسِدِينَ",
    "فَكَذَّبُوهُ فَأَخَذَتْهُمُ الرَّجْفَةُ فَأَصْبَحُوا فِى دَارِهِمْ جَٰثِمِينَ",
    "وَعَادًا وَثَمُودَا وَقَد تَّبَيَّنَ لَكُم مِّن مَّسَٰكِنِهِمْ  وَزَيَّنَ لَهُمُ الشَّيْطَٰنُ أَعْمَٰلَهُمْ فَصَدَّهُمْ عَنِ السَّبِيلِ وَكَانُوا مُسْتَبْصِرِينَ",
    "وَقَٰرُونَ وَفِرْعَوْنَ وَهَٰمَٰنَ  وَلَقَدْ جَآءَهُم مُّوسَىٰ بِالْبَيِّنَٰتِ فَاسْتَكْبَرُوا فِى الْأَرْضِ وَمَا كَانُوا سَٰبِقِينَ",
    "فَكُلًّا أَخَذْنَا بِذَنبِهِۦ  فَمِنْهُم مَّنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًا وَمِنْهُم مَّنْ أَخَذَتْهُ الصَّيْحَةُ وَمِنْهُم مَّنْ خَسَفْنَا بِهِ الْأَرْضَ وَمِنْهُم مَّنْ أَغْرَقْنَا  وَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا أَنفُسَهُمْ يَظْلِمُونَ",
    "مَثَلُ الَّذِينَ اتَّخَذُوا مِن دُونِ اللَّهِ أَوْلِيَآءَ كَمَثَلِ الْعَنكَبُوتِ اتَّخَذَتْ بَيْتًا  وَإِنَّ أَوْهَنَ الْبُيُوتِ لَبَيْتُ الْعَنكَبُوتِ  لَوْ كَانُوا يَعْلَمُونَ",
    "إِنَّ اللَّهَ يَعْلَمُ مَا يَدْعُونَ مِن دُونِهِۦ مِن شَىْءٍ  وَهُوَ الْعَزِيزُ الْحَكِيمُ",
    "وَتِلْكَ الْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ  وَمَا يَعْقِلُهَآ إِلَّا الْعَٰلِمُونَ",
    "خَلَقَ اللَّهُ السَّمَٰوَٰتِ وَالْأَرْضَ بِالْحَقِّ  إِنَّ فِى ذَٰلِكَ لََٔايَةً لِّلْمُؤْمِنِينَ",
    "اتْلُ مَآ أُوحِىَ إِلَيْكَ مِنَ الْكِتَٰبِ وَأَقِمِ الصَّلَوٰةَ  إِنَّ الصَّلَوٰةَ تَنْهَىٰ عَنِ الْفَحْشَآءِ وَالْمُنكَرِ  وَلَذِكْرُ اللَّهِ أَكْبَرُ  وَاللَّهُ يَعْلَمُ مَا تَصْنَعُونَ",
    "۞ وَلَا تُجَٰدِلُوٓا أَهْلَ الْكِتَٰبِ إِلَّا بِالَّتِى هِىَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ  وَقُولُوٓا ءَامَنَّا بِالَّذِىٓ أُنزِلَ إِلَيْنَا وَأُنزِلَ إِلَيْكُمْ وَإِلَٰهُنَا وَإِلَٰهُكُمْ وَٰحِدٌ وَنَحْنُ لَهُۥ مُسْلِمُونَ",
    "وَكَذَٰلِكَ أَنزَلْنَآ إِلَيْكَ الْكِتَٰبَ  فَالَّذِينَ ءَاتَيْنَٰهُمُ الْكِتَٰبَ يُؤْمِنُونَ بِهِۦ  وَمِنْ هَٰٓؤُلَآءِ مَن يُؤْمِنُ بِهِۦ  وَمَا يَجْحَدُ بَِٔايَٰتِنَآ إِلَّا الْكَٰفِرُونَ",
    "وَمَا كُنتَ تَتْلُوا مِن قَبْلِهِۦ مِن كِتَٰبٍ وَلَا تَخُطُّهُۥ بِيَمِينِكَ  إِذًا لَّارْتَابَ الْمُبْطِلُونَ",
    "بَلْ هُوَ ءَايَٰتٌ بَيِّنَٰتٌ فِى صُدُورِ الَّذِينَ أُوتُوا الْعِلْمَ  وَمَا يَجْحَدُ بَِٔايَٰتِنَآ إِلَّا الظَّٰلِمُونَ",
    "وَقَالُوا لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَٰتٌ مِّن رَّبِّهِۦ  قُلْ إِنَّمَا الَْٔايَٰتُ عِندَ اللَّهِ وَإِنَّمَآ أَنَا نَذِيرٌ مُّبِينٌ",
    "أَوَلَمْ يَكْفِهِمْ أَنَّآ أَنزَلْنَا عَلَيْكَ الْكِتَٰبَ يُتْلَىٰ عَلَيْهِمْ  إِنَّ فِى ذَٰلِكَ لَرَحْمَةً وَذِكْرَىٰ لِقَوْمٍ يُؤْمِنُونَ",
    "قُلْ كَفَىٰ بِاللَّهِ بَيْنِى وَبَيْنَكُمْ شَهِيدًا  يَعْلَمُ مَا فِى السَّمَٰوَٰتِ وَالْأَرْضِ  وَالَّذِينَ ءَامَنُوا بِالْبَٰطِلِ وَكَفَرُوا بِاللَّهِ أُولَٰٓئِكَ هُمُ الْخَٰسِرُونَ",
    "وَيَسْتَعْجِلُونَكَ بِالْعَذَابِ  وَلَوْلَآ أَجَلٌ مُّسَمًّى لَّجَآءَهُمُ الْعَذَابُ وَلَيَأْتِيَنَّهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ",
    "يَسْتَعْجِلُونَكَ بِالْعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌ بِالْكَٰفِرِينَ",
    "يَوْمَ يَغْشَىٰهُمُ الْعَذَابُ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِمْ وَيَقُولُ ذُوقُوا مَا كُنتُمْ تَعْمَلُونَ",
    "يَٰعِبَادِىَ الَّذِينَ ءَامَنُوٓا إِنَّ أَرْضِى وَٰسِعَةٌ فَإِيَّٰىَ فَاعْبُدُونِ",
    "كُلُّ نَفْسٍ ذَآئِقَةُ الْمَوْتِ  ثُمَّ إِلَيْنَا تُرْجَعُونَ",
    "وَالَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ الْجَنَّةِ غُرَفًا تَجْرِى مِن تَحْتِهَا الْأَنْهَٰرُ خَٰلِدِينَ فِيهَا  نِعْمَ أَجْرُ الْعَٰمِلِينَ",
    "الَّذِينَ صَبَرُوا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ",
    "وَكَأَيِّن مِّن دَآبَّةٍ لَّا تَحْمِلُ رِزْقَهَا اللَّهُ يَرْزُقُهَا وَإِيَّاكُمْ  وَهُوَ السَّمِيعُ الْعَلِيمُ",
    "وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ لَيَقُولُنَّ اللَّهُ  فَأَنَّىٰ يُؤْفَكُونَ",
    "اللَّهُ يَبْسُطُ الرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥٓ  إِنَّ اللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ",
    "وَلَئِن سَأَلْتَهُم مَّن نَّزَّلَ مِنَ السَّمَآءِ مَآءً فَأَحْيَا بِهِ الْأَرْضَ مِن بَعْدِ مَوْتِهَا لَيَقُولُنَّ اللَّهُ  قُلِ الْحَمْدُ لِلَّهِ  بَلْ أَكْثَرُهُمْ لَا يَعْقِلُونَ",
    "وَمَا هَٰذِهِ الْحَيَوٰةُ الدُّنْيَآ إِلَّا لَهْوٌ وَلَعِبٌ  وَإِنَّ الدَّارَ الَْٔاخِرَةَ لَهِىَ الْحَيَوَانُ  لَوْ كَانُوا يَعْلَمُونَ",
    "فَإِذَا رَكِبُوا فِى الْفُلْكِ دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى الْبَرِّ إِذَا هُمْ يُشْرِكُونَ",
    "لِيَكْفُرُوا بِمَآ ءَاتَيْنَٰهُمْ وَلِيَتَمَتَّعُوا  فَسَوْفَ يَعْلَمُونَ",
    "أَوَلَمْ يَرَوْا أَنَّا جَعَلْنَا حَرَمًا ءَامِنًا وَيُتَخَطَّفُ النَّاسُ مِنْ حَوْلِهِمْ  أَفَبِالْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَةِ اللَّهِ يَكْفُرُونَ",
    "وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا أَوْ كَذَّبَ بِالْحَقِّ لَمَّا جَآءَهُۥٓ  أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَٰفِرِينَ",
    "وَالَّذِينَ جَٰهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا  وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ",
  ],
  30: [
    "الٓمٓ",
    "غُلِبَتِ الرُّومُ",
    "فِىٓ أَدْنَى الْأَرْضِ وَهُم مِّن بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ",
    "فِى بِضْعِ سِنِينَ  لِلَّهِ الْأَمْرُ مِن قَبْلُ وَمِن بَعْدُ  وَيَوْمَئِذٍ يَفْرَحُ الْمُؤْمِنُونَ",
    "بِنَصْرِ اللَّهِ  يَنصُرُ مَن يَشَآءُ  وَهُوَ الْعَزِيزُ الرَّحِيمُ",
    "وَعْدَ اللَّهِ  لَا يُخْلِفُ اللَّهُ وَعْدَهُۥ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ",
    "يَعْلَمُونَ ظَٰهِرًا مِّنَ الْحَيَوٰةِ الدُّنْيَا وَهُمْ عَنِ الَْٔاخِرَةِ هُمْ غَٰفِلُونَ",
    "أَوَلَمْ يَتَفَكَّرُوا فِىٓ أَنفُسِهِم  مَّا خَلَقَ اللَّهُ السَّمَٰوَٰتِ وَالْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى  وَإِنَّ كَثِيرًا مِّنَ النَّاسِ بِلِقَآئِ رَبِّهِمْ لَكَٰفِرُونَ",
    "أَوَلَمْ يَسِيرُوا فِى الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَٰقِبَةُ الَّذِينَ مِن قَبْلِهِمْ  كَانُوٓا أَشَدَّ مِنْهُمْ قُوَّةً وَأَثَارُوا الْأَرْضَ وَعَمَرُوهَآ أَكْثَرَ مِمَّا عَمَرُوهَا وَجَآءَتْهُمْ رُسُلُهُم بِالْبَيِّنَٰتِ  فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا أَنفُسَهُمْ يَظْلِمُونَ",
    "ثُمَّ كَانَ عَٰقِبَةَ الَّذِينَ أَسَُٰٓٔوا السُّوٓأَىٰٓ أَن كَذَّبُوا بَِٔايَٰتِ اللَّهِ وَكَانُوا بِهَا يَسْتَهْزِءُونَ",
    "اللَّهُ يَبْدَؤُا الْخَلْقَ ثُمَّ يُعِيدُهُۥ ثُمَّ إِلَيْهِ تُرْجَعُونَ",
    "وَيَوْمَ تَقُومُ السَّاعَةُ يُبْلِسُ الْمُجْرِمُونَ",
    "وَلَمْ يَكُن لَّهُم مِّن شُرَكَآئِهِمْ شُفَعَٰٓؤُا وَكَانُوا بِشُرَكَآئِهِمْ كَٰفِرِينَ",
    "وَيَوْمَ تَقُومُ السَّاعَةُ يَوْمَئِذٍ يَتَفَرَّقُونَ",
    "فَأَمَّا الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ فَهُمْ فِى رَوْضَةٍ يُحْبَرُونَ",
    "وَأَمَّا الَّذِينَ كَفَرُوا وَكَذَّبُوا بَِٔايَٰتِنَا وَلِقَآئِ الَْٔاخِرَةِ فَأُولَٰٓئِكَ فِى الْعَذَابِ مُحْضَرُونَ",
    "فَسُبْحَٰنَ اللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ",
    "وَلَهُ الْحَمْدُ فِى السَّمَٰوَٰتِ وَالْأَرْضِ وَعَشِيًّا وَحِينَ تُظْهِرُونَ",
    "يُخْرِجُ الْحَىَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَىِّ وَيُحْىِ الْأَرْضَ بَعْدَ مَوْتِهَا  وَكَذَٰلِكَ تُخْرَجُونَ",
    "وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَكُم مِّن تُرَابٍ ثُمَّ إِذَآ أَنتُم بَشَرٌ تَنتَشِرُونَ",
    "وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا لِّتَسْكُنُوٓا إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةً وَرَحْمَةً  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ",
    "وَمِنْ ءَايَٰتِهِۦ خَلْقُ السَّمَٰوَٰتِ وَالْأَرْضِ وَاخْتِلَٰفُ أَلْسِنَتِكُمْ وَأَلْوَٰنِكُمْ  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ لِّلْعَٰلِمِينَ",
    "وَمِنْ ءَايَٰتِهِۦ مَنَامُكُم بِالَّيْلِ وَالنَّهَارِ وَابْتِغَآؤُكُم مِّن فَضْلِهِۦٓ  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ لِّقَوْمٍ يَسْمَعُونَ",
    "وَمِنْ ءَايَٰتِهِۦ يُرِيكُمُ الْبَرْقَ خَوْفًا وَطَمَعًا وَيُنَزِّلُ مِنَ السَّمَآءِ مَآءً فَيُحْىِۦ بِهِ الْأَرْضَ بَعْدَ مَوْتِهَآ  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ",
    "وَمِنْ ءَايَٰتِهِۦٓ أَن تَقُومَ السَّمَآءُ وَالْأَرْضُ بِأَمْرِهِۦ  ثُمَّ إِذَا دَعَاكُمْ دَعْوَةً مِّنَ الْأَرْضِ إِذَآ أَنتُمْ تَخْرُجُونَ",
    "وَلَهُۥ مَن فِى السَّمَٰوَٰتِ وَالْأَرْضِ  كُلٌّ لَّهُۥ قَٰنِتُونَ",
    "وَهُوَ الَّذِى يَبْدَؤُا الْخَلْقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهْوَنُ عَلَيْهِ  وَلَهُ الْمَثَلُ الْأَعْلَىٰ فِى السَّمَٰوَٰتِ وَالْأَرْضِ  وَهُوَ الْعَزِيزُ الْحَكِيمُ",
    "ضَرَبَ لَكُم مَّثَلًا مِّنْ أَنفُسِكُمْ  هَل لَّكُم مِّن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن شُرَكَآءَ فِى مَا رَزَقْنَٰكُمْ فَأَنتُمْ فِيهِ سَوَآءٌ تَخَافُونَهُمْ كَخِيفَتِكُمْ أَنفُسَكُمْ  كَذَٰلِكَ نُفَصِّلُ الَْٔايَٰتِ لِقَوْمٍ يَعْقِلُونَ",
    "بَلِ اتَّبَعَ الَّذِينَ ظَلَمُوٓا أَهْوَآءَهُم بِغَيْرِ عِلْمٍ  فَمَن يَهْدِى مَنْ أَضَلَّ اللَّهُ  وَمَا لَهُم مِّن نَّٰصِرِينَ",
    "فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا  فِطْرَتَ اللَّهِ الَّتِى فَطَرَ النَّاسَ عَلَيْهَا  لَا تَبْدِيلَ لِخَلْقِ اللَّهِ  ذَٰلِكَ الدِّينُ الْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ",
    "۞ مُنِيبِينَ إِلَيْهِ وَاتَّقُوهُ وَأَقِيمُوا الصَّلَوٰةَ وَلَا تَكُونُوا مِنَ الْمُشْرِكِينَ",
    "مِنَ الَّذِينَ فَرَّقُوا دِينَهُمْ وَكَانُوا شِيَعًا  كُلُّ حِزْبٍ بِمَا لَدَيْهِمْ فَرِحُونَ",
    "وَإِذَا مَسَّ النَّاسَ ضُرٌّ دَعَوْا رَبَّهُم مُّنِيبِينَ إِلَيْهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنْهُ رَحْمَةً إِذَا فَرِيقٌ مِّنْهُم بِرَبِّهِمْ يُشْرِكُونَ",
    "لِيَكْفُرُوا بِمَآ ءَاتَيْنَٰهُمْ  فَتَمَتَّعُوا فَسَوْفَ تَعْلَمُونَ",
    "أَمْ أَنزَلْنَا عَلَيْهِمْ سُلْطَٰنًا فَهُوَ يَتَكَلَّمُ بِمَا كَانُوا بِهِۦ يُشْرِكُونَ",
    "وَإِذَآ أَذَقْنَا النَّاسَ رَحْمَةً فَرِحُوا بِهَا  وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ إِذَا هُمْ يَقْنَطُونَ",
    "أَوَلَمْ يَرَوْا أَنَّ اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ",
    "فََٔاتِ ذَا الْقُرْبَىٰ حَقَّهُۥ وَالْمِسْكِينَ وَابْنَ السَّبِيلِ  ذَٰلِكَ خَيْرٌ لِّلَّذِينَ يُرِيدُونَ وَجْهَ اللَّهِ  وَأُولَٰٓئِكَ هُمُ الْمُفْلِحُونَ",
    "وَمَآ ءَاتَيْتُم مِّن رِّبًا لِّيَرْبُوَا فِىٓ أَمْوَٰلِ النَّاسِ فَلَا يَرْبُوا عِندَ اللَّهِ  وَمَآ ءَاتَيْتُم مِّن زَكَوٰةٍ تُرِيدُونَ وَجْهَ اللَّهِ فَأُولَٰٓئِكَ هُمُ الْمُضْعِفُونَ",
    "اللَّهُ الَّذِى خَلَقَكُمْ ثُمَّ رَزَقَكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ  هَلْ مِن شُرَكَآئِكُم مَّن يَفْعَلُ مِن ذَٰلِكُم مِّن شَىْءٍ  سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ",
    "ظَهَرَ الْفَسَادُ فِى الْبَرِّ وَالْبَحْرِ بِمَا كَسَبَتْ أَيْدِى النَّاسِ لِيُذِيقَهُم بَعْضَ الَّذِى عَمِلُوا لَعَلَّهُمْ يَرْجِعُونَ",
    "قُلْ سِيرُوا فِى الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَٰقِبَةُ الَّذِينَ مِن قَبْلُ  كَانَ أَكْثَرُهُم مُّشْرِكِينَ",
    "فَأَقِمْ وَجْهَكَ لِلدِّينِ الْقَيِّمِ مِن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ اللَّهِ  يَوْمَئِذٍ يَصَّدَّعُونَ",
    "مَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ  وَمَنْ عَمِلَ صَٰلِحًا فَلِأَنفُسِهِمْ يَمْهَدُونَ",
    "لِيَجْزِىَ الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ مِن فَضْلِهِۦٓ  إِنَّهُۥ لَا يُحِبُّ الْكَٰفِرِينَ",
    "وَمِنْ ءَايَٰتِهِۦٓ أَن يُرْسِلَ الرِّيَاحَ مُبَشِّرَٰتٍ وَلِيُذِيقَكُم مِّن رَّحْمَتِهِۦ وَلِتَجْرِىَ الْفُلْكُ بِأَمْرِهِۦ وَلِتَبْتَغُوا مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ",
    "وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِالْبَيِّنَٰتِ فَانتَقَمْنَا مِنَ الَّذِينَ أَجْرَمُوا  وَكَانَ حَقًّا عَلَيْنَا نَصْرُ الْمُؤْمِنِينَ",
    "اللَّهُ الَّذِى يُرْسِلُ الرِّيَٰحَ فَتُثِيرُ سَحَابًا فَيَبْسُطُهُۥ فِى السَّمَآءِ كَيْفَ يَشَآءُ وَيَجْعَلُهُۥ كِسَفًا فَتَرَى الْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ  فَإِذَآ أَصَابَ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ",
    "وَإِن كَانُوا مِن قَبْلِ أَن يُنَزَّلَ عَلَيْهِم مِّن قَبْلِهِۦ لَمُبْلِسِينَ",
    "فَانظُرْ إِلَىٰٓ ءَاثَٰرِ رَحْمَتِ اللَّهِ كَيْفَ يُحْىِ الْأَرْضَ بَعْدَ مَوْتِهَآ  إِنَّ ذَٰلِكَ لَمُحْىِ الْمَوْتَىٰ  وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ",
    "وَلَئِنْ أَرْسَلْنَا رِيحًا فَرَأَوْهُ مُصْفَرًّا لَّظَلُّوا مِن بَعْدِهِۦ يَكْفُرُونَ",
    "فَإِنَّكَ لَا تُسْمِعُ الْمَوْتَىٰ وَلَا تُسْمِعُ الصُّمَّ الدُّعَآءَ إِذَا وَلَّوْا مُدْبِرِينَ",
    "وَمَآ أَنتَ بِهَٰدِ الْعُمْىِ عَن ضَلَٰلَتِهِمْ  إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بَِٔايَٰتِنَا فَهُم مُّسْلِمُونَ",
    "۞ اللَّهُ الَّذِى خَلَقَكُم مِّن ضَعْفٍ ثُمَّ جَعَلَ مِن بَعْدِ ضَعْفٍ قُوَّةً ثُمَّ جَعَلَ مِن بَعْدِ قُوَّةٍ ضَعْفًا وَشَيْبَةً  يَخْلُقُ مَا يَشَآءُ  وَهُوَ الْعَلِيمُ الْقَدِيرُ",
    "وَيَوْمَ تَقُومُ السَّاعَةُ يُقْسِمُ الْمُجْرِمُونَ مَا لَبِثُوا غَيْرَ سَاعَةٍ  كَذَٰلِكَ كَانُوا يُؤْفَكُونَ",
    "وَقَالَ الَّذِينَ أُوتُوا الْعِلْمَ وَالْإِيمَٰنَ لَقَدْ لَبِثْتُمْ فِى كِتَٰبِ اللَّهِ إِلَىٰ يَوْمِ الْبَعْثِ  فَهَٰذَا يَوْمُ الْبَعْثِ وَلَٰكِنَّكُمْ كُنتُمْ لَا تَعْلَمُونَ",
    "فَيَوْمَئِذٍ لَّا يَنفَعُ الَّذِينَ ظَلَمُوا مَعْذِرَتُهُمْ وَلَا هُمْ يُسْتَعْتَبُونَ",
    "وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا الْقُرْءَانِ مِن كُلِّ مَثَلٍ  وَلَئِن جِئْتَهُم بَِٔايَةٍ لَّيَقُولَنَّ الَّذِينَ كَفَرُوٓا إِنْ أَنتُمْ إِلَّا مُبْطِلُونَ",
    "كَذَٰلِكَ يَطْبَعُ اللَّهُ عَلَىٰ قُلُوبِ الَّذِينَ لَا يَعْلَمُونَ",
    "فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ  وَلَا يَسْتَخِفَّنَّكَ الَّذِينَ لَا يُوقِنُونَ",
  ],
  31: [
    "الٓمٓ",
    "تِلْكَ ءَايَٰتُ الْكِتَٰبِ الْحَكِيمِ",
    "هُدًى وَرَحْمَةً لِّلْمُحْسِنِينَ",
    "الَّذِينَ يُقِيمُونَ الصَّلَوٰةَ وَيُؤْتُونَ الزَّكَوٰةَ وَهُم بِالَْٔاخِرَةِ هُمْ يُوقِنُونَ",
    "أُولَٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ  وَأُولَٰٓئِكَ هُمُ الْمُفْلِحُونَ",
    "وَمِنَ النَّاسِ مَن يَشْتَرِى لَهْوَ الْحَدِيثِ لِيُضِلَّ عَن سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا  أُولَٰٓئِكَ لَهُمْ عَذَابٌ مُّهِينٌ",
    "وَإِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا وَلَّىٰ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا كَأَنَّ فِىٓ أُذُنَيْهِ وَقْرًا  فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ",
    "إِنَّ الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ لَهُمْ جَنَّٰتُ النَّعِيمِ",
    "خَٰلِدِينَ فِيهَا  وَعْدَ اللَّهِ حَقًّا  وَهُوَ الْعَزِيزُ الْحَكِيمُ",
    "خَلَقَ السَّمَٰوَٰتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا  وَأَلْقَىٰ فِى الْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ  وَأَنزَلْنَا مِنَ السَّمَآءِ مَآءً فَأَنبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ",
    "هَٰذَا خَلْقُ اللَّهِ فَأَرُونِى مَاذَا خَلَقَ الَّذِينَ مِن دُونِهِۦ  بَلِ الظَّٰلِمُونَ فِى ضَلَٰلٍ مُّبِينٍ",
    "وَلَقَدْ ءَاتَيْنَا لُقْمَٰنَ الْحِكْمَةَ أَنِ اشْكُرْ لِلَّهِ  وَمَن يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ  وَمَن كَفَرَ فَإِنَّ اللَّهَ غَنِىٌّ حَمِيدٌ",
    "وَإِذْ قَالَ لُقْمَٰنُ لِابْنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَىَّ لَا تُشْرِكْ بِاللَّهِ  إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ",
    "وَوَصَّيْنَا الْإِنسَٰنَ بِوَٰلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍ وَفِصَٰلُهُۥ فِى عَامَيْنِ أَنِ اشْكُرْ لِى وَلِوَٰلِدَيْكَ إِلَىَّ الْمَصِيرُ",
    "وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَا  وَصَاحِبْهُمَا فِى الدُّنْيَا مَعْرُوفًا  وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَىَّ  ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ",
    "يَٰبُنَىَّ إِنَّهَآ إِن تَكُ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ فَتَكُن فِى صَخْرَةٍ أَوْ فِى السَّمَٰوَٰتِ أَوْ فِى الْأَرْضِ يَأْتِ بِهَا اللَّهُ  إِنَّ اللَّهَ لَطِيفٌ خَبِيرٌ",
    "يَٰبُنَىَّ أَقِمِ الصَّلَوٰةَ وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنكَرِ وَاصْبِرْ عَلَىٰ مَآ أَصَابَكَ  إِنَّ ذَٰلِكَ مِنْ عَزْمِ الْأُمُورِ",
    "وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِى الْأَرْضِ مَرَحًا  إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ",
    "وَاقْصِدْ فِى مَشْيِكَ وَاغْضُضْ مِن صَوْتِكَ  إِنَّ أَنكَرَ الْأَصْوَٰتِ لَصَوْتُ الْحَمِيرِ",
    "أَلَمْ تَرَوْا أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِى السَّمَٰوَٰتِ وَمَا فِى الْأَرْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُۥ ظَٰهِرَةً وَبَاطِنَةً  وَمِنَ النَّاسِ مَن يُجَٰدِلُ فِى اللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَٰبٍ مُّنِيرٍ",
    "وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَآ أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ  أَوَلَوْ كَانَ الشَّيْطَٰنُ يَدْعُوهُمْ إِلَىٰ عَذَابِ السَّعِيرِ",
    "۞ وَمَن يُسْلِمْ وَجْهَهُۥٓ إِلَى اللَّهِ وَهُوَ مُحْسِنٌ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ  وَإِلَى اللَّهِ عَٰقِبَةُ الْأُمُورِ",
    "وَمَن كَفَرَ فَلَا يَحْزُنكَ كُفْرُهُۥٓ  إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُم بِمَا عَمِلُوٓا  إِنَّ اللَّهَ عَلِيمٌ بِذَاتِ الصُّدُورِ",
    "نُمَتِّعُهُمْ قَلِيلًا ثُمَّ نَضْطَرُّهُمْ إِلَىٰ عَذَابٍ غَلِيظٍ",
    "وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ  قُلِ الْحَمْدُ لِلَّهِ  بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ",
    "لِلَّهِ مَا فِى السَّمَٰوَٰتِ وَالْأَرْضِ  إِنَّ اللَّهَ هُوَ الْغَنِىُّ الْحَمِيدُ",
    "وَلَوْ أَنَّمَا فِى الْأَرْضِ مِن شَجَرَةٍ أَقْلَٰمٌ وَالْبَحْرُ يَمُدُّهُۥ مِن بَعْدِهِۦ سَبْعَةُ أَبْحُرٍ مَّا نَفِدَتْ كَلِمَٰتُ اللَّهِ  إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ",
    "مَّا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَٰحِدَةٍ  إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ",
    "أَلَمْ تَرَ أَنَّ اللَّهَ يُولِجُ الَّيْلَ فِى النَّهَارِ وَيُولِجُ النَّهَارَ فِى الَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِىٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى وَأَنَّ اللَّهَ بِمَا تَعْمَلُونَ خَبِيرٌ",
    "ذَٰلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ الْبَٰطِلُ وَأَنَّ اللَّهَ هُوَ الْعَلِىُّ الْكَبِيرُ",
    "أَلَمْ تَرَ أَنَّ الْفُلْكَ تَجْرِى فِى الْبَحْرِ بِنِعْمَتِ اللَّهِ لِيُرِيَكُم مِّنْ ءَايَٰتِهِۦٓ  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ",
    "وَإِذَا غَشِيَهُم مَّوْجٌ كَالظُّلَلِ دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى الْبَرِّ فَمِنْهُم مُّقْتَصِدٌ  وَمَا يَجْحَدُ بَِٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارٍ كَفُورٍ",
    "يَٰٓأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا لَّا يَجْزِى وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوْلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَئًْا  إِنَّ وَعْدَ اللَّهِ حَقٌّ  فَلَا تَغُرَّنَّكُمُ الْحَيَوٰةُ الدُّنْيَا وَلَا يَغُرَّنَّكُم بِاللَّهِ الْغَرُورُ",
    "إِنَّ اللَّهَ عِندَهُۥ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِى الْأَرْحَامِ  وَمَا تَدْرِى نَفْسٌ مَّاذَا تَكْسِبُ غَدًا  وَمَا تَدْرِى نَفْسٌ بِأَىِّ أَرْضٍ تَمُوتُ  إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ",
  ],
  32: [
    "الٓمٓ",
    "تَنزِيلُ الْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَٰلَمِينَ",
    "أَمْ يَقُولُونَ افْتَرَىٰهُ  بَلْ هُوَ الْحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّآ أَتَىٰهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ",
    "اللَّهُ الَّذِى خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ  مَا لَكُم مِّن دُونِهِۦ مِن وَلِىٍّ وَلَا شَفِيعٍ  أَفَلَا تَتَذَكَّرُونَ",
    "يُدَبِّرُ الْأَمْرَ مِنَ السَّمَآءِ إِلَى الْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥٓ أَلْفَ سَنَةٍ مِّمَّا تَعُدُّونَ",
    "ذَٰلِكَ عَٰلِمُ الْغَيْبِ وَالشَّهَٰدَةِ الْعَزِيزُ الرَّحِيمُ",
    "الَّذِىٓ أَحْسَنَ كُلَّ شَىْءٍ خَلَقَهُۥ  وَبَدَأَ خَلْقَ الْإِنسَٰنِ مِن طِينٍ",
    "ثُمَّ جَعَلَ نَسْلَهُۥ مِن سُلَٰلَةٍ مِّن مَّآءٍ مَّهِينٍ",
    "ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦ  وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَٰرَ وَالْأَفِْٔدَةَ  قَلِيلًا مَّا تَشْكُرُونَ",
    "وَقَالُوٓا أَءِذَا ضَلَلْنَا فِى الْأَرْضِ أَءِنَّا لَفِى خَلْقٍ جَدِيدٍ  بَلْ هُم بِلِقَآءِ رَبِّهِمْ كَٰفِرُونَ",
    "۞ قُلْ يَتَوَفَّىٰكُم مَّلَكُ الْمَوْتِ الَّذِى وُكِّلَ بِكُمْ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ",
    "وَلَوْ تَرَىٰٓ إِذِ الْمُجْرِمُونَ نَاكِسُوا رُءُوسِهِمْ عِندَ رَبِّهِمْ رَبَّنَآ أَبْصَرْنَا وَسَمِعْنَا فَارْجِعْنَا نَعْمَلْ صَٰلِحًا إِنَّا مُوقِنُونَ",
    "وَلَوْ شِئْنَا لََٔاتَيْنَا كُلَّ نَفْسٍ هُدَىٰهَا وَلَٰكِنْ حَقَّ الْقَوْلُ مِنِّى لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ",
    "فَذُوقُوا بِمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَآ إِنَّا نَسِينَٰكُمْ  وَذُوقُوا عَذَابَ الْخُلْدِ بِمَا كُنتُمْ تَعْمَلُونَ",
    "إِنَّمَا يُؤْمِنُ بَِٔايَٰتِنَا الَّذِينَ إِذَا ذُكِّرُوا بِهَا خَرُّوا سُجَّدًا وَسَبَّحُوا بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ",
    "تَتَجَافَىٰ جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ",
    "فَلَا تَعْلَمُ نَفْسٌ مَّآ أُخْفِىَ لَهُم مِّن قُرَّةِ أَعْيُنٍ جَزَآءً بِمَا كَانُوا يَعْمَلُونَ",
    "أَفَمَن كَانَ مُؤْمِنًا كَمَن كَانَ فَاسِقًا  لَّا يَسْتَوُۥنَ",
    "أَمَّا الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ فَلَهُمْ جَنَّٰتُ الْمَأْوَىٰ نُزُلًا بِمَا كَانُوا يَعْمَلُونَ",
    "وَأَمَّا الَّذِينَ فَسَقُوا فَمَأْوَىٰهُمُ النَّارُ  كُلَّمَآ أَرَادُوٓا أَن يَخْرُجُوا مِنْهَآ أُعِيدُوا فِيهَا وَقِيلَ لَهُمْ ذُوقُوا عَذَابَ النَّارِ الَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ",
    "وَلَنُذِيقَنَّهُم مِّنَ الْعَذَابِ الْأَدْنَىٰ دُونَ الْعَذَابِ الْأَكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ",
    "وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بَِٔايَٰتِ رَبِّهِۦ ثُمَّ أَعْرَضَ عَنْهَآ  إِنَّا مِنَ الْمُجْرِمِينَ مُنتَقِمُونَ",
    "وَلَقَدْ ءَاتَيْنَا مُوسَى الْكِتَٰبَ فَلَا تَكُن فِى مِرْيَةٍ مِّن لِّقَآئِهِۦ  وَجَعَلْنَٰهُ هُدًى لِّبَنِىٓ إِسْرَٰٓءِيلَ",
    "وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا  وَكَانُوا بَِٔايَٰتِنَا يُوقِنُونَ",
    "إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ الْقِيَٰمَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ",
    "أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّنَ الْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ  أَفَلَا يَسْمَعُونَ",
    "أَوَلَمْ يَرَوْا أَنَّا نَسُوقُ الْمَآءَ إِلَى الْأَرْضِ الْجُرُزِ فَنُخْرِجُ بِهِۦ زَرْعًا تَأْكُلُ مِنْهُ أَنْعَٰمُهُمْ وَأَنفُسُهُمْ  أَفَلَا يُبْصِرُونَ",
    "وَيَقُولُونَ مَتَىٰ هَٰذَا الْفَتْحُ إِن كُنتُمْ صَٰدِقِينَ",
    "قُلْ يَوْمَ الْفَتْحِ لَا يَنفَعُ الَّذِينَ كَفَرُوٓا إِيمَٰنُهُمْ وَلَا هُمْ يُنظَرُونَ",
    "فَأَعْرِضْ عَنْهُمْ وَانتَظِرْ إِنَّهُم مُّنتَظِرُونَ",
  ],
  33: [
    "يَٰٓأَيُّهَا النَّبِىُّ اتَّقِ اللَّهَ وَلَا تُطِعِ الْكَٰفِرِينَ وَالْمُنَٰفِقِينَ  إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا",
    "وَاتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ مِن رَّبِّكَ  إِنَّ اللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا",
    "وَتَوَكَّلْ عَلَى اللَّهِ  وَكَفَىٰ بِاللَّهِ وَكِيلًا",
    "مَّا جَعَلَ اللَّهُ لِرَجُلٍ مِّن قَلْبَيْنِ فِى جَوْفِهِۦ  وَمَا جَعَلَ أَزْوَٰجَكُمُ الَِّٰٓٔى تُظَٰهِرُونَ مِنْهُنَّ أُمَّهَٰتِكُمْ  وَمَا جَعَلَ أَدْعِيَآءَكُمْ أَبْنَآءَكُمْ  ذَٰلِكُمْ قَوْلُكُم بِأَفْوَٰهِكُمْ  وَاللَّهُ يَقُولُ الْحَقَّ وَهُوَ يَهْدِى السَّبِيلَ",
    "ادْعُوهُمْ لَِٔابَآئِهِمْ هُوَ أَقْسَطُ عِندَ اللَّهِ  فَإِن لَّمْ تَعْلَمُوٓا ءَابَآءَهُمْ فَإِخْوَٰنُكُمْ فِى الدِّينِ وَمَوَٰلِيكُمْ  وَلَيْسَ عَلَيْكُمْ جُنَاحٌ فِيمَآ أَخْطَأْتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتْ قُلُوبُكُمْ  وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا",
    "النَّبِىُّ أَوْلَىٰ بِالْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ  وَأَزْوَٰجُهُۥٓ أُمَّهَٰتُهُمْ  وَأُولُوا الْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَٰبِ اللَّهِ مِنَ الْمُؤْمِنِينَ وَالْمُهَٰجِرِينَ إِلَّآ أَن تَفْعَلُوٓا إِلَىٰٓ أَوْلِيَآئِكُم مَّعْرُوفًا  كَانَ ذَٰلِكَ فِى الْكِتَٰبِ مَسْطُورًا",
    "وَإِذْ أَخَذْنَا مِنَ النَّبِيِّنَ مِيثَٰقَهُمْ وَمِنكَ وَمِن نُّوحٍ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ابْنِ مَرْيَمَ  وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًا",
    "لِّيَسَْٔلَ الصَّٰدِقِينَ عَن صِدْقِهِمْ  وَأَعَدَّ لِلْكَٰفِرِينَ عَذَابًا أَلِيمًا",
    "يَٰٓأَيُّهَا الَّذِينَ ءَامَنُوا اذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا  وَكَانَ اللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا",
    "إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ الْأَبْصَٰرُ وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ وَتَظُنُّونَ بِاللَّهِ الظُّنُونَا",
    "هُنَالِكَ ابْتُلِىَ الْمُؤْمِنُونَ وَزُلْزِلُوا زِلْزَالًا شَدِيدًا",
    "وَإِذْ يَقُولُ الْمُنَٰفِقُونَ وَالَّذِينَ فِى قُلُوبِهِم مَّرَضٌ مَّا وَعَدَنَا اللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورًا",
    "وَإِذْ قَالَت طَّآئِفَةٌ مِّنْهُمْ يَٰٓأَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَارْجِعُوا  وَيَسْتَْٔذِنُ فَرِيقٌ مِّنْهُمُ النَّبِىَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوْرَةٌ وَمَا هِىَ بِعَوْرَةٍ  إِن يُرِيدُونَ إِلَّا فِرَارًا",
    "وَلَوْ دُخِلَتْ عَلَيْهِم مِّنْ أَقْطَارِهَا ثُمَّ سُئِلُوا الْفِتْنَةَ لََٔاتَوْهَا وَمَا تَلَبَّثُوا بِهَآ إِلَّا يَسِيرًا",
    "وَلَقَدْ كَانُوا عَٰهَدُوا اللَّهَ مِن قَبْلُ لَا يُوَلُّونَ الْأَدْبَٰرَ  وَكَانَ عَهْدُ اللَّهِ مَسُْٔولًا",
    "قُل لَّن يَنفَعَكُمُ الْفِرَارُ إِن فَرَرْتُم مِّنَ الْمَوْتِ أَوِ الْقَتْلِ وَإِذًا لَّا تُمَتَّعُونَ إِلَّا قَلِيلًا",
    "قُلْ مَن ذَا الَّذِى يَعْصِمُكُم مِّنَ اللَّهِ إِنْ أَرَادَ بِكُمْ سُوٓءًا أَوْ أَرَادَ بِكُمْ رَحْمَةً  وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا",
    "۞ قَدْ يَعْلَمُ اللَّهُ الْمُعَوِّقِينَ مِنكُمْ وَالْقَآئِلِينَ لِإِخْوَٰنِهِمْ هَلُمَّ إِلَيْنَا  وَلَا يَأْتُونَ الْبَأْسَ إِلَّا قَلِيلًا",
    "أَشِحَّةً عَلَيْكُمْ  فَإِذَا جَآءَ الْخَوْفُ رَأَيْتَهُمْ يَنظُرُونَ إِلَيْكَ تَدُورُ أَعْيُنُهُمْ كَالَّذِى يُغْشَىٰ عَلَيْهِ مِنَ الْمَوْتِ  فَإِذَا ذَهَبَ الْخَوْفُ سَلَقُوكُم بِأَلْسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى الْخَيْرِ  أُولَٰٓئِكَ لَمْ يُؤْمِنُوا فَأَحْبَطَ اللَّهُ أَعْمَٰلَهُمْ  وَكَانَ ذَٰلِكَ عَلَى اللَّهِ يَسِيرًا",
    "يَحْسَبُونَ الْأَحْزَابَ لَمْ يَذْهَبُوا  وَإِن يَأْتِ الْأَحْزَابُ يَوَدُّوا لَوْ أَنَّهُم بَادُونَ فِى الْأَعْرَابِ يَسَْٔلُونَ عَنْ أَنبَآئِكُمْ  وَلَوْ كَانُوا فِيكُم مَّا قَٰتَلُوٓا إِلَّا قَلِيلًا",
    "لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا اللَّهَ وَالْيَوْمَ الَْٔاخِرَ وَذَكَرَ اللَّهَ كَثِيرًا",
    "وَلَمَّا رَءَا الْمُؤْمِنُونَ الْأَحْزَابَ قَالُوا هَٰذَا مَا وَعَدَنَا اللَّهُ وَرَسُولُهُۥ وَصَدَقَ اللَّهُ وَرَسُولُهُۥ  وَمَا زَادَهُمْ إِلَّآ إِيمَٰنًا وَتَسْلِيمًا",
    "مِّنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَٰهَدُوا اللَّهَ عَلَيْهِ  فَمِنْهُم مَّن قَضَىٰ نَحْبَهُۥ وَمِنْهُم مَّن يَنتَظِرُ  وَمَا بَدَّلُوا تَبْدِيلًا",
    "لِّيَجْزِىَ اللَّهُ الصَّٰدِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ الْمُنَٰفِقِينَ إِن شَآءَ أَوْ يَتُوبَ عَلَيْهِمْ  إِنَّ اللَّهَ كَانَ غَفُورًا رَّحِيمًا",
    "وَرَدَّ اللَّهُ الَّذِينَ كَفَرُوا بِغَيْظِهِمْ لَمْ يَنَالُوا خَيْرًا  وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ  وَكَانَ اللَّهُ قَوِيًّا عَزِيزًا",
    "وَأَنزَلَ الَّذِينَ ظَٰهَرُوهُم مِّنْ أَهْلِ الْكِتَٰبِ مِن صَيَاصِيهِمْ وَقَذَفَ فِى قُلُوبِهِمُ الرُّعْبَ فَرِيقًا تَقْتُلُونَ وَتَأْسِرُونَ فَرِيقًا",
    "وَأَوْرَثَكُمْ أَرْضَهُمْ وَدِيَٰرَهُمْ وَأَمْوَٰلَهُمْ وَأَرْضًا لَّمْ تَطَُٔوهَا  وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا",
    "يَٰٓأَيُّهَا النَّبِىُّ قُل لِّأَزْوَٰجِكَ إِن كُنتُنَّ تُرِدْنَ الْحَيَوٰةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا",
    "وَإِن كُنتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُۥ وَالدَّارَ الَْٔاخِرَةَ فَإِنَّ اللَّهَ أَعَدَّ لِلْمُحْسِنَٰتِ مِنكُنَّ أَجْرًا عَظِيمًا",
    "يَٰنِسَآءَ النَّبِىِّ مَن يَأْتِ مِنكُنَّ بِفَٰحِشَةٍ مُّبَيِّنَةٍ يُضَٰعَفْ لَهَا الْعَذَابُ ضِعْفَيْنِ  وَكَانَ ذَٰلِكَ عَلَى اللَّهِ يَسِيرًا",
    "۞ وَمَن يَقْنُتْ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعْمَلْ صَٰلِحًا نُّؤْتِهَآ أَجْرَهَا مَرَّتَيْنِ وَأَعْتَدْنَا لَهَا رِزْقًا كَرِيمًا",
    "يَٰنِسَآءَ النَّبِىِّ لَسْتُنَّ كَأَحَدٍ مِّنَ النِّسَآءِ  إِنِ اتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِى فِى قَلْبِهِۦ مَرَضٌ وَقُلْنَ قَوْلًا مَّعْرُوفًا",
    "وَقَرْنَ فِى بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَٰهِلِيَّةِ الْأُولَىٰ  وَأَقِمْنَ الصَّلَوٰةَ وَءَاتِينَ الزَّكَوٰةَ وَأَطِعْنَ اللَّهَ وَرَسُولَهُۥٓ  إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا",
    "وَاذْكُرْنَ مَا يُتْلَىٰ فِى بُيُوتِكُنَّ مِنْ ءَايَٰتِ اللَّهِ وَالْحِكْمَةِ  إِنَّ اللَّهَ كَانَ لَطِيفًا خَبِيرًا",
    "إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَٰتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَٰتِ وَالْقَٰنِتِينَ وَالْقَٰنِتَٰتِ وَالصَّٰدِقِينَ وَالصَّٰدِقَٰتِ وَالصَّٰبِرِينَ وَالصَّٰبِرَٰتِ وَالْخَٰشِعِينَ وَالْخَٰشِعَٰتِ وَالْمُتَصَدِّقِينَ وَالْمُتَصَدِّقَٰتِ وَالصَّٰٓئِمِينَ وَالصَّٰٓئِمَٰتِ وَالْحَٰفِظِينَ فُرُوجَهُمْ وَالْحَٰفِظَٰتِ وَالذَّٰكِرِينَ اللَّهَ كَثِيرًا وَالذَّٰكِرَٰتِ أَعَدَّ اللَّهُ لَهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًا",
    "وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى اللَّهُ وَرَسُولُهُۥٓ أَمْرًا أَن يَكُونَ لَهُمُ الْخِيَرَةُ مِنْ أَمْرِهِمْ  وَمَن يَعْصِ اللَّهَ وَرَسُولَهُۥ فَقَدْ ضَلَّ ضَلَٰلًا مُّبِينًا",
    "وَإِذْ تَقُولُ لِلَّذِىٓ أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ وَتُخْفِى فِى نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَن تَخْشَىٰهُ  فَلَمَّا قَضَىٰ زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَٰكَهَا لِكَىْ لَا يَكُونَ عَلَى الْمُؤْمِنِينَ حَرَجٌ فِىٓ أَزْوَٰجِ أَدْعِيَآئِهِمْ إِذَا قَضَوْا مِنْهُنَّ وَطَرًا  وَكَانَ أَمْرُ اللَّهِ مَفْعُولًا",
    "مَّا كَانَ عَلَى النَّبِىِّ مِنْ حَرَجٍ فِيمَا فَرَضَ اللَّهُ لَهُۥ  سُنَّةَ اللَّهِ فِى الَّذِينَ خَلَوْا مِن قَبْلُ  وَكَانَ أَمْرُ اللَّهِ قَدَرًا مَّقْدُورًا",
    "الَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ اللَّهِ وَيَخْشَوْنَهُۥ وَلَا يَخْشَوْنَ أَحَدًا إِلَّا اللَّهَ  وَكَفَىٰ بِاللَّهِ حَسِيبًا",
    "مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّنَ  وَكَانَ اللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا",
    "يَٰٓأَيُّهَا الَّذِينَ ءَامَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا",
    "وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا",
    "هُوَ الَّذِى يُصَلِّى عَلَيْكُمْ وَمَلَٰٓئِكَتُهُۥ لِيُخْرِجَكُم مِّنَ الظُّلُمَٰتِ إِلَى النُّورِ  وَكَانَ بِالْمُؤْمِنِينَ رَحِيمًا",
    "تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُۥ سَلَٰمٌ  وَأَعَدَّ لَهُمْ أَجْرًا كَرِيمًا",
    "يَٰٓأَيُّهَا النَّبِىُّ إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًا وَمُبَشِّرًا وَنَذِيرًا",
    "وَدَاعِيًا إِلَى اللَّهِ بِإِذْنِهِۦ وَسِرَاجًا مُّنِيرًا",
    "وَبَشِّرِ الْمُؤْمِنِينَ بِأَنَّ لَهُم مِّنَ اللَّهِ فَضْلًا كَبِيرًا",
    "وَلَا تُطِعِ الْكَٰفِرِينَ وَالْمُنَٰفِقِينَ وَدَعْ أَذَىٰهُمْ وَتَوَكَّلْ عَلَى اللَّهِ  وَكَفَىٰ بِاللَّهِ وَكِيلًا",
    "يَٰٓأَيُّهَا الَّذِينَ ءَامَنُوٓا إِذَا نَكَحْتُمُ الْمُؤْمِنَٰتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا  فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا",
    "يَٰٓأَيُّهَا النَّبِىُّ إِنَّآ أَحْلَلْنَا لَكَ أَزْوَٰجَكَ الَّٰتِىٓ ءَاتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّآ أَفَآءَ اللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ الَّٰتِى هَاجَرْنَ مَعَكَ وَامْرَأَةً مُّؤْمِنَةً إِن وَهَبَتْ نَفْسَهَا لِلنَّبِىِّ إِنْ أَرَادَ النَّبِىُّ أَن يَسْتَنكِحَهَا خَالِصَةً لَّكَ مِن دُونِ الْمُؤْمِنِينَ  قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِىٓ أَزْوَٰجِهِمْ وَمَا مَلَكَتْ أَيْمَٰنُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌ  وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا",
    "۞ تُرْجِى مَن تَشَآءُ مِنْهُنَّ وَتُْٔوِىٓ إِلَيْكَ مَن تَشَآءُ  وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ  ذَٰلِكَ أَدْنَىٰٓ أَن تَقَرَّ أَعْيُنُهُنَّ وَلَا يَحْزَنَّ وَيَرْضَيْنَ بِمَآ ءَاتَيْتَهُنَّ كُلُّهُنَّ  وَاللَّهُ يَعْلَمُ مَا فِى قُلُوبِكُمْ  وَكَانَ اللَّهُ عَلِيمًا حَلِيمًا",
    "لَّا يَحِلُّ لَكَ النِّسَآءُ مِن بَعْدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنْ أَزْوَٰجٍ وَلَوْ أَعْجَبَكَ حُسْنُهُنَّ إِلَّا مَا مَلَكَتْ يَمِينُكَ  وَكَانَ اللَّهُ عَلَىٰ كُلِّ شَىْءٍ رَّقِيبًا",
    "يَٰٓأَيُّهَا الَّذِينَ ءَامَنُوا لَا تَدْخُلُوا بُيُوتَ النَّبِىِّ إِلَّآ أَن يُؤْذَنَ لَكُمْ إِلَىٰ طَعَامٍ غَيْرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنْ إِذَا دُعِيتُمْ فَادْخُلُوا فَإِذَا طَعِمْتُمْ فَانتَشِرُوا وَلَا مُسْتَْٔنِسِينَ لِحَدِيثٍ  إِنَّ ذَٰلِكُمْ كَانَ يُؤْذِى النَّبِىَّ فَيَسْتَحْىِۦ مِنكُمْ  وَاللَّهُ لَا يَسْتَحْىِۦ مِنَ الْحَقِّ  وَإِذَا سَأَلْتُمُوهُنَّ مَتَٰعًا فَسَْٔلُوهُنَّ مِن وَرَآءِ حِجَابٍ  ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ  وَمَا كَانَ لَكُمْ أَن تُؤْذُوا رَسُولَ اللَّهِ وَلَآ أَن تَنكِحُوٓا أَزْوَٰجَهُۥ مِن بَعْدِهِۦٓ أَبَدًا  إِنَّ ذَٰلِكُمْ كَانَ عِندَ اللَّهِ عَظِيمًا",
    "إِن تُبْدُوا شَئًْا أَوْ تُخْفُوهُ فَإِنَّ اللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا",
    "لَّا جُنَاحَ عَلَيْهِنَّ فِىٓ ءَابَآئِهِنَّ وَلَآ أَبْنَآئِهِنَّ وَلَآ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتْ أَيْمَٰنُهُنَّ  وَاتَّقِينَ اللَّهَ  إِنَّ اللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا",
    "إِنَّ اللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى النَّبِىِّ  يَٰٓأَيُّهَا الَّذِينَ ءَامَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا",
    "إِنَّ الَّذِينَ يُؤْذُونَ اللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ اللَّهُ فِى الدُّنْيَا وَالَْٔاخِرَةِ وَأَعَدَّ لَهُمْ عَذَابًا مُّهِينًا",
    "وَالَّذِينَ يُؤْذُونَ الْمُؤْمِنِينَ وَالْمُؤْمِنَٰتِ بِغَيْرِ مَا اكْتَسَبُوا فَقَدِ احْتَمَلُوا بُهْتَٰنًا وَإِثْمًا مُّبِينًا",
    "يَٰٓأَيُّهَا النَّبِىُّ قُل لِّأَزْوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَٰبِيبِهِنَّ  ذَٰلِكَ أَدْنَىٰٓ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ  وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا",
    "۞ لَّئِن لَّمْ يَنتَهِ الْمُنَٰفِقُونَ وَالَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَالْمُرْجِفُونَ فِى الْمَدِينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلًا",
    "مَّلْعُونِينَ  أَيْنَمَا ثُقِفُوٓا أُخِذُوا وَقُتِّلُوا تَقْتِيلًا",
    "سُنَّةَ اللَّهِ فِى الَّذِينَ خَلَوْا مِن قَبْلُ  وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا",
    "يَسَْٔلُكَ النَّاسُ عَنِ السَّاعَةِ  قُلْ إِنَّمَا عِلْمُهَا عِندَ اللَّهِ  وَمَا يُدْرِيكَ لَعَلَّ السَّاعَةَ تَكُونُ قَرِيبًا",
    "إِنَّ اللَّهَ لَعَنَ الْكَٰفِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا",
    "خَٰلِدِينَ فِيهَآ أَبَدًا  لَّا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا",
    "يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى النَّارِ يَقُولُونَ يَٰلَيْتَنَآ أَطَعْنَا اللَّهَ وَأَطَعْنَا الرَّسُولَا",
    "وَقَالُوا رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا السَّبِيلَا",
    "رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ الْعَذَابِ وَالْعَنْهُمْ لَعْنًا كَبِيرًا",
    "يَٰٓأَيُّهَا الَّذِينَ ءَامَنُوا لَا تَكُونُوا كَالَّذِينَ ءَاذَوْا مُوسَىٰ فَبَرَّأَهُ اللَّهُ مِمَّا قَالُوا  وَكَانَ عِندَ اللَّهِ وَجِيهًا",
    "يَٰٓأَيُّهَا الَّذِينَ ءَامَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا",
    "يُصْلِحْ لَكُمْ أَعْمَٰلَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ  وَمَن يُطِعِ اللَّهَ وَرَسُولَهُۥ فَقَدْ فَازَ فَوْزًا عَظِيمًا",
    "إِنَّا عَرَضْنَا الْأَمَانَةَ عَلَى السَّمَٰوَٰتِ وَالْأَرْضِ وَالْجِبَالِ فَأَبَيْنَ أَن يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا الْإِنسَٰنُ  إِنَّهُۥ كَانَ ظَلُومًا جَهُولًا",
    "لِّيُعَذِّبَ اللَّهُ الْمُنَٰفِقِينَ وَالْمُنَٰفِقَٰتِ وَالْمُشْرِكِينَ وَالْمُشْرِكَٰتِ وَيَتُوبَ اللَّهُ عَلَى الْمُؤْمِنِينَ وَالْمُؤْمِنَٰتِ  وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا",
  ],
  34: [
    "الْحَمْدُ لِلَّهِ الَّذِى لَهُۥ مَا فِى السَّمَٰوَٰتِ وَمَا فِى الْأَرْضِ وَلَهُ الْحَمْدُ فِى الَْٔاخِرَةِ  وَهُوَ الْحَكِيمُ الْخَبِيرُ",
    "يَعْلَمُ مَا يَلِجُ فِى الْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ السَّمَآءِ وَمَا يَعْرُجُ فِيهَا  وَهُوَ الرَّحِيمُ الْغَفُورُ",
    "وَقَالَ الَّذِينَ كَفَرُوا لَا تَأْتِينَا السَّاعَةُ  قُلْ بَلَىٰ وَرَبِّى لَتَأْتِيَنَّكُمْ عَٰلِمِ الْغَيْبِ  لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ فِى السَّمَٰوَٰتِ وَلَا فِى الْأَرْضِ وَلَآ أَصْغَرُ مِن ذَٰلِكَ وَلَآ أَكْبَرُ إِلَّا فِى كِتَٰبٍ مُّبِينٍ",
    "لِّيَجْزِىَ الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ  أُولَٰٓئِكَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ",
    "وَالَّذِينَ سَعَوْ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُولَٰٓئِكَ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ",
    "وَيَرَى الَّذِينَ أُوتُوا الْعِلْمَ الَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ الْحَقَّ وَيَهْدِىٓ إِلَىٰ صِرَٰطِ الْعَزِيزِ الْحَمِيدِ",
    "وَقَالَ الَّذِينَ كَفَرُوا هَلْ نَدُلُّكُمْ عَلَىٰ رَجُلٍ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ إِنَّكُمْ لَفِى خَلْقٍ جَدِيدٍ",
    "أَفْتَرَىٰ عَلَى اللَّهِ كَذِبًا أَم بِهِۦ جِنَّةٌ  بَلِ الَّذِينَ لَا يُؤْمِنُونَ بِالَْٔاخِرَةِ فِى الْعَذَابِ وَالضَّلَٰلِ الْبَعِيدِ",
    "أَفَلَمْ يَرَوْا إِلَىٰ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُم مِّنَ السَّمَآءِ وَالْأَرْضِ  إِن نَّشَأْ نَخْسِفْ بِهِمُ الْأَرْضَ أَوْ نُسْقِطْ عَلَيْهِمْ كِسَفًا مِّنَ السَّمَآءِ  إِنَّ فِى ذَٰلِكَ لََٔايَةً لِّكُلِّ عَبْدٍ مُّنِيبٍ",
    "۞ وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ مِنَّا فَضْلًا  يَٰجِبَالُ أَوِّبِى مَعَهُۥ وَالطَّيْرَ  وَأَلَنَّا لَهُ الْحَدِيدَ",
    "أَنِ اعْمَلْ سَٰبِغَٰتٍ وَقَدِّرْ فِى السَّرْدِ  وَاعْمَلُوا صَٰلِحًا  إِنِّى بِمَا تَعْمَلُونَ بَصِيرٌ",
    "وَلِسُلَيْمَٰنَ الرِّيحَ غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ  وَأَسَلْنَا لَهُۥ عَيْنَ الْقِطْرِ  وَمِنَ الْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِۦ  وَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ السَّعِيرِ",
    "يَعْمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانٍ كَالْجَوَابِ وَقُدُورٍ رَّاسِيَٰتٍ  اعْمَلُوٓا ءَالَ دَاوُۥدَ شُكْرًا  وَقَلِيلٌ مِّنْ عِبَادِىَ الشَّكُورُ",
    "فَلَمَّا قَضَيْنَا عَلَيْهِ الْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِۦٓ إِلَّا دَآبَّةُ الْأَرْضِ تَأْكُلُ مِنسَأَتَهُۥ  فَلَمَّا خَرَّ تَبَيَّنَتِ الْجِنُّ أَن لَّوْ كَانُوا يَعْلَمُونَ الْغَيْبَ مَا لَبِثُوا فِى الْعَذَابِ الْمُهِينِ",
    "لَقَدْ كَانَ لِسَبَإٍ فِى مَسْكَنِهِمْ ءَايَةٌ  جَنَّتَانِ عَن يَمِينٍ وَشِمَالٍ  كُلُوا مِن رِّزْقِ رَبِّكُمْ وَاشْكُرُوا لَهُۥ  بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ",
    "فَأَعْرَضُوا فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ الْعَرِمِ وَبَدَّلْنَٰهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَىْ أُكُلٍ خَمْطٍ وَأَثْلٍ وَشَىْءٍ مِّن سِدْرٍ قَلِيلٍ",
    "ذَٰلِكَ جَزَيْنَٰهُم بِمَا كَفَرُوا  وَهَلْ نُجَٰزِىٓ إِلَّا الْكَفُورَ",
    "وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ الْقُرَى الَّتِى بَٰرَكْنَا فِيهَا قُرًى ظَٰهِرَةً وَقَدَّرْنَا فِيهَا السَّيْرَ  سِيرُوا فِيهَا لَيَالِىَ وَأَيَّامًا ءَامِنِينَ",
    "فَقَالُوا رَبَّنَا بَٰعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُوٓا أَنفُسَهُمْ فَجَعَلْنَٰهُمْ أَحَادِيثَ وَمَزَّقْنَٰهُمْ كُلَّ مُمَزَّقٍ  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ",
    "وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُۥ فَاتَّبَعُوهُ إِلَّا فَرِيقًا مِّنَ الْمُؤْمِنِينَ",
    "وَمَا كَانَ لَهُۥ عَلَيْهِم مِّن سُلْطَٰنٍ إِلَّا لِنَعْلَمَ مَن يُؤْمِنُ بِالَْٔاخِرَةِ مِمَّنْ هُوَ مِنْهَا فِى شَكٍّ  وَرَبُّكَ عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ",
    "قُلِ ادْعُوا الَّذِينَ زَعَمْتُم مِّن دُونِ اللَّهِ  لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِى السَّمَٰوَٰتِ وَلَا فِى الْأَرْضِ وَمَا لَهُمْ فِيهِمَا مِن شِرْكٍ وَمَا لَهُۥ مِنْهُم مِّن ظَهِيرٍ",
    "وَلَا تَنفَعُ الشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنْ أَذِنَ لَهُۥ  حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُوا مَاذَا قَالَ رَبُّكُمْ  قَالُوا الْحَقَّ  وَهُوَ الْعَلِىُّ الْكَبِيرُ",
    "۞ قُلْ مَن يَرْزُقُكُم مِّنَ السَّمَٰوَٰتِ وَالْأَرْضِ  قُلِ اللَّهُ  وَإِنَّآ أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِى ضَلَٰلٍ مُّبِينٍ",
    "قُل لَّا تُسَْٔلُونَ عَمَّآ أَجْرَمْنَا وَلَا نُسَْٔلُ عَمَّا تَعْمَلُونَ",
    "قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِالْحَقِّ وَهُوَ الْفَتَّاحُ الْعَلِيمُ",
    "قُلْ أَرُونِىَ الَّذِينَ أَلْحَقْتُم بِهِۦ شُرَكَآءَ  كَلَّا  بَلْ هُوَ اللَّهُ الْعَزِيزُ الْحَكِيمُ",
    "وَمَآ أَرْسَلْنَٰكَ إِلَّا كَآفَّةً لِّلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ",
    "وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ",
    "قُل لَّكُم مِّيعَادُ يَوْمٍ لَّا تَسْتَْٔخِرُونَ عَنْهُ سَاعَةً وَلَا تَسْتَقْدِمُونَ",
    "وَقَالَ الَّذِينَ كَفَرُوا لَن نُّؤْمِنَ بِهَٰذَا الْقُرْءَانِ وَلَا بِالَّذِى بَيْنَ يَدَيْهِ  وَلَوْ تَرَىٰٓ إِذِ الظَّٰلِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَىٰ بَعْضٍ الْقَوْلَ يَقُولُ الَّذِينَ اسْتُضْعِفُوا لِلَّذِينَ اسْتَكْبَرُوا لَوْلَآ أَنتُمْ لَكُنَّا مُؤْمِنِينَ",
    "قَالَ الَّذِينَ اسْتَكْبَرُوا لِلَّذِينَ اسْتُضْعِفُوٓا أَنَحْنُ صَدَدْنَٰكُمْ عَنِ الْهُدَىٰ بَعْدَ إِذْ جَآءَكُم  بَلْ كُنتُم مُّجْرِمِينَ",
    "وَقَالَ الَّذِينَ اسْتُضْعِفُوا لِلَّذِينَ اسْتَكْبَرُوا بَلْ مَكْرُ الَّيْلِ وَالنَّهَارِ إِذْ تَأْمُرُونَنَآ أَن نَّكْفُرَ بِاللَّهِ وَنَجْعَلَ لَهُۥٓ أَندَادًا  وَأَسَرُّوا النَّدَامَةَ لَمَّا رَأَوُا الْعَذَابَ وَجَعَلْنَا الْأَغْلَٰلَ فِىٓ أَعْنَاقِ الَّذِينَ كَفَرُوا  هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا يَعْمَلُونَ",
    "وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ",
    "وَقَالُوا نَحْنُ أَكْثَرُ أَمْوَٰلًا وَأَوْلَٰدًا وَمَا نَحْنُ بِمُعَذَّبِينَ",
    "قُلْ إِنَّ رَبِّى يَبْسُطُ الرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ",
    "وَمَآ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُم بِالَّتِى تُقَرِّبُكُمْ عِندَنَا زُلْفَىٰٓ إِلَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا فَأُولَٰٓئِكَ لَهُمْ جَزَآءُ الضِّعْفِ بِمَا عَمِلُوا وَهُمْ فِى الْغُرُفَٰتِ ءَامِنُونَ",
    "وَالَّذِينَ يَسْعَوْنَ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُولَٰٓئِكَ فِى الْعَذَابِ مُحْضَرُونَ",
    "قُلْ إِنَّ رَبِّى يَبْسُطُ الرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥ  وَمَآ أَنفَقْتُم مِّن شَىْءٍ فَهُوَ يُخْلِفُهُۥ  وَهُوَ خَيْرُ الرَّٰزِقِينَ",
    "وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمْ كَانُوا يَعْبُدُونَ",
    "قَالُوا سُبْحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِم  بَلْ كَانُوا يَعْبُدُونَ الْجِنَّ  أَكْثَرُهُم بِهِم مُّؤْمِنُونَ",
    "فَالْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضٍ نَّفْعًا وَلَا ضَرًّا وَنَقُولُ لِلَّذِينَ ظَلَمُوا ذُوقُوا عَذَابَ النَّارِ الَّتِى كُنتُم بِهَا تُكَذِّبُونَ",
    "وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالُوا مَا هَٰذَآ إِلَّا رَجُلٌ يُرِيدُ أَن يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ ءَابَآؤُكُمْ وَقَالُوا مَا هَٰذَآ إِلَّآ إِفْكٌ مُّفْتَرًى  وَقَالَ الَّذِينَ كَفَرُوا لِلْحَقِّ لَمَّا جَآءَهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ",
    "وَمَآ ءَاتَيْنَٰهُم مِّن كُتُبٍ يَدْرُسُونَهَا  وَمَآ أَرْسَلْنَآ إِلَيْهِمْ قَبْلَكَ مِن نَّذِيرٍ",
    "وَكَذَّبَ الَّذِينَ مِن قَبْلِهِمْ وَمَا بَلَغُوا مِعْشَارَ مَآ ءَاتَيْنَٰهُمْ فَكَذَّبُوا رُسُلِى  فَكَيْفَ كَانَ نَكِيرِ",
    "۞ قُلْ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍ  أَن تَقُومُوا لِلَّهِ مَثْنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُوا  مَا بِصَاحِبِكُم مِّن جِنَّةٍ  إِنْ هُوَ إِلَّا نَذِيرٌ لَّكُم بَيْنَ يَدَىْ عَذَابٍ شَدِيدٍ",
    "قُلْ مَا سَأَلْتُكُم مِّنْ أَجْرٍ فَهُوَ لَكُمْ  إِنْ أَجْرِىَ إِلَّا عَلَى اللَّهِ  وَهُوَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ",
    "قُلْ إِنَّ رَبِّى يَقْذِفُ بِالْحَقِّ عَلَّٰمُ الْغُيُوبِ",
    "قُلْ جَآءَ الْحَقُّ وَمَا يُبْدِئُ الْبَٰطِلُ وَمَا يُعِيدُ",
    "قُلْ إِن ضَلَلْتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفْسِى  وَإِنِ اهْتَدَيْتُ فَبِمَا يُوحِىٓ إِلَىَّ رَبِّىٓ  إِنَّهُۥ سَمِيعٌ قَرِيبٌ",
    "وَلَوْ تَرَىٰٓ إِذْ فَزِعُوا فَلَا فَوْتَ وَأُخِذُوا مِن مَّكَانٍ قَرِيبٍ",
    "وَقَالُوٓا ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ التَّنَاوُشُ مِن مَّكَانٍ بَعِيدٍ",
    "وَقَدْ كَفَرُوا بِهِۦ مِن قَبْلُ  وَيَقْذِفُونَ بِالْغَيْبِ مِن مَّكَانٍ بَعِيدٍ",
    "وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِم مِّن قَبْلُ  إِنَّهُمْ كَانُوا فِى شَكٍّ مُّرِيبٍ",
  ],
  35: [
    "الْحَمْدُ لِلَّهِ فَاطِرِ السَّمَٰوَٰتِ وَالْأَرْضِ جَاعِلِ الْمَلَٰٓئِكَةِ رُسُلًا أُولِىٓ أَجْنِحَةٍ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ  يَزِيدُ فِى الْخَلْقِ مَا يَشَآءُ  إِنَّ اللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ",
    "مَّا يَفْتَحِ اللَّهُ لِلنَّاسِ مِن رَّحْمَةٍ فَلَا مُمْسِكَ لَهَا  وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُۥ مِن بَعْدِهِۦ  وَهُوَ الْعَزِيزُ الْحَكِيمُ",
    "يَٰٓأَيُّهَا النَّاسُ اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ  هَلْ مِنْ خَٰلِقٍ غَيْرُ اللَّهِ يَرْزُقُكُم مِّنَ السَّمَآءِ وَالْأَرْضِ  لَآ إِلَٰهَ إِلَّا هُوَ  فَأَنَّىٰ تُؤْفَكُونَ",
    "وَإِن يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ  وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ",
    "يَٰٓأَيُّهَا النَّاسُ إِنَّ وَعْدَ اللَّهِ حَقٌّ  فَلَا تَغُرَّنَّكُمُ الْحَيَوٰةُ الدُّنْيَا  وَلَا يَغُرَّنَّكُم بِاللَّهِ الْغَرُورُ",
    "إِنَّ الشَّيْطَٰنَ لَكُمْ عَدُوٌّ فَاتَّخِذُوهُ عَدُوًّا  إِنَّمَا يَدْعُوا حِزْبَهُۥ لِيَكُونُوا مِنْ أَصْحَٰبِ السَّعِيرِ",
    "الَّذِينَ كَفَرُوا لَهُمْ عَذَابٌ شَدِيدٌ  وَالَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ",
    "أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنًا  فَإِنَّ اللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ  فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَٰتٍ  إِنَّ اللَّهَ عَلِيمٌ بِمَا يَصْنَعُونَ",
    "وَاللَّهُ الَّذِىٓ أَرْسَلَ الرِّيَٰحَ فَتُثِيرُ سَحَابًا فَسُقْنَٰهُ إِلَىٰ بَلَدٍ مَّيِّتٍ فَأَحْيَيْنَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا  كَذَٰلِكَ النُّشُورُ",
    "مَن كَانَ يُرِيدُ الْعِزَّةَ فَلِلَّهِ الْعِزَّةُ جَمِيعًا  إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ وَالْعَمَلُ الصَّٰلِحُ يَرْفَعُهُۥ  وَالَّذِينَ يَمْكُرُونَ السَّئَِّاتِ لَهُمْ عَذَابٌ شَدِيدٌ  وَمَكْرُ أُولَٰٓئِكَ هُوَ يَبُورُ",
    "وَاللَّهُ خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ جَعَلَكُمْ أَزْوَٰجًا  وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ  وَمَا يُعَمَّرُ مِن مُّعَمَّرٍ وَلَا يُنقَصُ مِنْ عُمُرِهِۦٓ إِلَّا فِى كِتَٰبٍ  إِنَّ ذَٰلِكَ عَلَى اللَّهِ يَسِيرٌ",
    "وَمَا يَسْتَوِى الْبَحْرَانِ هَٰذَا عَذْبٌ فُرَاتٌ سَآئِغٌ شَرَابُهُۥ وَهَٰذَا مِلْحٌ أُجَاجٌ  وَمِن كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُونَ حِلْيَةً تَلْبَسُونَهَا  وَتَرَى الْفُلْكَ فِيهِ مَوَاخِرَ لِتَبْتَغُوا مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ",
    "يُولِجُ الَّيْلَ فِى النَّهَارِ وَيُولِجُ النَّهَارَ فِى الَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى  ذَٰلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ  وَالَّذِينَ تَدْعُونَ مِن دُونِهِۦ مَا يَمْلِكُونَ مِن قِطْمِيرٍ",
    "إِن تَدْعُوهُمْ لَا يَسْمَعُوا دُعَآءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ  وَيَوْمَ الْقِيَٰمَةِ يَكْفُرُونَ بِشِرْكِكُمْ  وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرٍ",
    "۞ يَٰٓأَيُّهَا النَّاسُ أَنتُمُ الْفُقَرَآءُ إِلَى اللَّهِ  وَاللَّهُ هُوَ الْغَنِىُّ الْحَمِيدُ",
    "إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ",
    "وَمَا ذَٰلِكَ عَلَى اللَّهِ بِعَزِيزٍ",
    "وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ  وَإِن تَدْعُ مُثْقَلَةٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَىْءٌ وَلَوْ كَانَ ذَا قُرْبَىٰٓ  إِنَّمَا تُنذِرُ الَّذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ وَأَقَامُوا الصَّلَوٰةَ  وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِۦ  وَإِلَى اللَّهِ الْمَصِيرُ",
    "وَمَا يَسْتَوِى الْأَعْمَىٰ وَالْبَصِيرُ",
    "وَلَا الظُّلُمَٰتُ وَلَا النُّورُ",
    "وَلَا الظِّلُّ وَلَا الْحَرُورُ",
    "وَمَا يَسْتَوِى الْأَحْيَآءُ وَلَا الْأَمْوَٰتُ  إِنَّ اللَّهَ يُسْمِعُ مَن يَشَآءُ  وَمَآ أَنتَ بِمُسْمِعٍ مَّن فِى الْقُبُورِ",
    "إِنْ أَنتَ إِلَّا نَذِيرٌ",
    "إِنَّآ أَرْسَلْنَٰكَ بِالْحَقِّ بَشِيرًا وَنَذِيرًا  وَإِن مِّنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ",
    "وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ جَآءَتْهُمْ رُسُلُهُم بِالْبَيِّنَٰتِ وَبِالزُّبُرِ وَبِالْكِتَٰبِ الْمُنِيرِ",
    "ثُمَّ أَخَذْتُ الَّذِينَ كَفَرُوا  فَكَيْفَ كَانَ نَكِيرِ",
    "أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا  وَمِنَ الْجِبَالِ جُدَدٌ بِيضٌ وَحُمْرٌ مُّخْتَلِفٌ أَلْوَٰنُهَا وَغَرَابِيبُ سُودٌ",
    "وَمِنَ النَّاسِ وَالدَّوَآبِّ وَالْأَنْعَٰمِ مُخْتَلِفٌ أَلْوَٰنُهُۥ كَذَٰلِكَ  إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَٰٓؤُا  إِنَّ اللَّهَ عَزِيزٌ غَفُورٌ",
    "إِنَّ الَّذِينَ يَتْلُونَ كِتَٰبَ اللَّهِ وَأَقَامُوا الصَّلَوٰةَ وَأَنفَقُوا مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً يَرْجُونَ تِجَٰرَةً لَّن تَبُورَ",
    "لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُم مِّن فَضْلِهِۦٓ  إِنَّهُۥ غَفُورٌ شَكُورٌ",
    "وَالَّذِىٓ أَوْحَيْنَآ إِلَيْكَ مِنَ الْكِتَٰبِ هُوَ الْحَقُّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ  إِنَّ اللَّهَ بِعِبَادِهِۦ لَخَبِيرٌ بَصِيرٌ",
    "ثُمَّ أَوْرَثْنَا الْكِتَٰبَ الَّذِينَ اصْطَفَيْنَا مِنْ عِبَادِنَا  فَمِنْهُمْ ظَالِمٌ لِّنَفْسِهِۦ وَمِنْهُم مُّقْتَصِدٌ وَمِنْهُمْ سَابِقٌ بِالْخَيْرَٰتِ بِإِذْنِ اللَّهِ  ذَٰلِكَ هُوَ الْفَضْلُ الْكَبِيرُ",
    "جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا  وَلِبَاسُهُمْ فِيهَا حَرِيرٌ",
    "وَقَالُوا الْحَمْدُ لِلَّهِ الَّذِىٓ أَذْهَبَ عَنَّا الْحَزَنَ  إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ",
    "الَّذِىٓ أَحَلَّنَا دَارَ الْمُقَامَةِ مِن فَضْلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٌ وَلَا يَمَسُّنَا فِيهَا لُغُوبٌ",
    "وَالَّذِينَ كَفَرُوا لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضَىٰ عَلَيْهِمْ فَيَمُوتُوا وَلَا يُخَفَّفُ عَنْهُم مِّنْ عَذَابِهَا  كَذَٰلِكَ نَجْزِى كُلَّ كَفُورٍ",
    "وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَآ أَخْرِجْنَا نَعْمَلْ صَٰلِحًا غَيْرَ الَّذِى كُنَّا نَعْمَلُ  أَوَلَمْ نُعَمِّرْكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ النَّذِيرُ  فَذُوقُوا فَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ",
    "إِنَّ اللَّهَ عَٰلِمُ غَيْبِ السَّمَٰوَٰتِ وَالْأَرْضِ  إِنَّهُۥ عَلِيمٌ بِذَاتِ الصُّدُورِ",
    "هُوَ الَّذِى جَعَلَكُمْ خَلَٰٓئِفَ فِى الْأَرْضِ  فَمَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ  وَلَا يَزِيدُ الْكَٰفِرِينَ كُفْرُهُمْ عِندَ رَبِّهِمْ إِلَّا مَقْتًا  وَلَا يَزِيدُ الْكَٰفِرِينَ كُفْرُهُمْ إِلَّا خَسَارًا",
    "قُلْ أَرَءَيْتُمْ شُرَكَآءَكُمُ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ أَرُونِى مَاذَا خَلَقُوا مِنَ الْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى السَّمَٰوَٰتِ أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًا فَهُمْ عَلَىٰ بَيِّنَتٍ مِّنْهُ  بَلْ إِن يَعِدُ الظَّٰلِمُونَ بَعْضُهُم بَعْضًا إِلَّا غُرُورًا",
    "۞ إِنَّ اللَّهَ يُمْسِكُ السَّمَٰوَٰتِ وَالْأَرْضَ أَن تَزُولَا  وَلَئِن زَالَتَآ إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِّن بَعْدِهِۦٓ  إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا",
    "وَأَقْسَمُوا بِاللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَهُمْ نَذِيرٌ لَّيَكُونُنَّ أَهْدَىٰ مِنْ إِحْدَى الْأُمَمِ  فَلَمَّا جَآءَهُمْ نَذِيرٌ مَّا زَادَهُمْ إِلَّا نُفُورًا",
    "اسْتِكْبَارًا فِى الْأَرْضِ وَمَكْرَ السَّيِّئِ  وَلَا يَحِيقُ الْمَكْرُ السَّيِّئُ إِلَّا بِأَهْلِهِۦ  فَهَلْ يَنظُرُونَ إِلَّا سُنَّتَ الْأَوَّلِينَ  فَلَن تَجِدَ لِسُنَّتِ اللَّهِ تَبْدِيلًا  وَلَن تَجِدَ لِسُنَّتِ اللَّهِ تَحْوِيلًا",
    "أَوَلَمْ يَسِيرُوا فِى الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَٰقِبَةُ الَّذِينَ مِن قَبْلِهِمْ وَكَانُوٓا أَشَدَّ مِنْهُمْ قُوَّةً  وَمَا كَانَ اللَّهُ لِيُعْجِزَهُۥ مِن شَىْءٍ فِى السَّمَٰوَٰتِ وَلَا فِى الْأَرْضِ  إِنَّهُۥ كَانَ عَلِيمًا قَدِيرًا",
    "وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِمَا كَسَبُوا مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَآبَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى  فَإِذَا جَآءَ أَجَلُهُمْ فَإِنَّ اللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرًا",
  ],
  36: [
    "يسٓ",
    "وَالْقُرْءَانِ الْحَكِيمِ",
    "إِنَّكَ لَمِنَ الْمُرْسَلِينَ",
    "عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ",
    "تَنزِيلَ الْعَزِيزِ الرَّحِيمِ",
    "لِتُنذِرَ قَوْمًا مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَٰفِلُونَ",
    "لَقَدْ حَقَّ الْقَوْلُ عَلَىٰٓ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ",
    "إِنَّا جَعَلْنَا فِىٓ أَعْنَٰقِهِمْ أَغْلَٰلًا فَهِىَ إِلَى الْأَذْقَانِ فَهُم مُّقْمَحُونَ",
    "وَجَعَلْنَا مِن بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَٰهُمْ فَهُمْ لَا يُبْصِرُونَ",
    "وَسَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ",
    "إِنَّمَا تُنذِرُ مَنِ اتَّبَعَ الذِّكْرَ وَخَشِىَ الرَّحْمَٰنَ بِالْغَيْبِ  فَبَشِّرْهُ بِمَغْفِرَةٍ وَأَجْرٍ كَرِيمٍ",
    "إِنَّا نَحْنُ نُحْىِ الْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا وَءَاثَٰرَهُمْ  وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ فِىٓ إِمَامٍ مُّبِينٍ",
    "وَاضْرِبْ لَهُم مَّثَلًا أَصْحَٰبَ الْقَرْيَةِ إِذْ جَآءَهَا الْمُرْسَلُونَ",
    "إِذْ أَرْسَلْنَآ إِلَيْهِمُ اثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوٓا إِنَّآ إِلَيْكُم مُّرْسَلُونَ",
    "قَالُوا مَآ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا وَمَآ أَنزَلَ الرَّحْمَٰنُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا تَكْذِبُونَ",
    "قَالُوا رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ",
    "وَمَا عَلَيْنَآ إِلَّا الْبَلَٰغُ الْمُبِينُ",
    "قَالُوٓا إِنَّا تَطَيَّرْنَا بِكُمْ  لَئِن لَّمْ تَنتَهُوا لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٌ",
    "قَالُوا طَٰٓئِرُكُم مَّعَكُمْ  أَئِن ذُكِّرْتُم  بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ",
    "وَجَآءَ مِنْ أَقْصَا الْمَدِينَةِ رَجُلٌ يَسْعَىٰ قَالَ يَٰقَوْمِ اتَّبِعُوا الْمُرْسَلِينَ",
    "اتَّبِعُوا مَن لَّا يَسَْٔلُكُمْ أَجْرًا وَهُم مُّهْتَدُونَ",
    "وَمَا لِىَ لَآ أَعْبُدُ الَّذِى فَطَرَنِى وَإِلَيْهِ تُرْجَعُونَ",
    "ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدْنِ الرَّحْمَٰنُ بِضُرٍّ لَّا تُغْنِ عَنِّى شَفَٰعَتُهُمْ شَئًْا وَلَا يُنقِذُونِ",
    "إِنِّىٓ إِذًا لَّفِى ضَلَٰلٍ مُّبِينٍ",
    "إِنِّىٓ ءَامَنتُ بِرَبِّكُمْ فَاسْمَعُونِ",
    "قِيلَ ادْخُلِ الْجَنَّةَ  قَالَ يَٰلَيْتَ قَوْمِى يَعْلَمُونَ",
    "بِمَا غَفَرَ لِى رَبِّى وَجَعَلَنِى مِنَ الْمُكْرَمِينَ",
    "۞ وَمَآ أَنزَلْنَا عَلَىٰ قَوْمِهِۦ مِن بَعْدِهِۦ مِن جُندٍ مِّنَ السَّمَآءِ وَمَا كُنَّا مُنزِلِينَ",
    "إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ خَٰمِدُونَ",
    "يَٰحَسْرَةً عَلَى الْعِبَادِ  مَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِۦ يَسْتَهْزِءُونَ",
    "أَلَمْ يَرَوْا كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ الْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ",
    "وَإِن كُلٌّ لَّمَّا جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ",
    "وَءَايَةٌ لَّهُمُ الْأَرْضُ الْمَيْتَةُ أَحْيَيْنَٰهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ",
    "وَجَعَلْنَا فِيهَا جَنَّٰتٍ مِّن نَّخِيلٍ وَأَعْنَٰبٍ وَفَجَّرْنَا فِيهَا مِنَ الْعُيُونِ",
    "لِيَأْكُلُوا مِن ثَمَرِهِۦ وَمَا عَمِلَتْهُ أَيْدِيهِمْ  أَفَلَا يَشْكُرُونَ",
    "سُبْحَٰنَ الَّذِى خَلَقَ الْأَزْوَٰجَ كُلَّهَا مِمَّا تُنبِتُ الْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ",
    "وَءَايَةٌ لَّهُمُ الَّيْلُ نَسْلَخُ مِنْهُ النَّهَارَ فَإِذَا هُم مُّظْلِمُونَ",
    "وَالشَّمْسُ تَجْرِى لِمُسْتَقَرٍّ لَّهَا  ذَٰلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ",
    "وَالْقَمَرَ قَدَّرْنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَالْعُرْجُونِ الْقَدِيمِ",
    "لَا الشَّمْسُ يَنبَغِى لَهَآ أَن تُدْرِكَ الْقَمَرَ وَلَا الَّيْلُ سَابِقُ النَّهَارِ  وَكُلٌّ فِى فَلَكٍ يَسْبَحُونَ",
    "وَءَايَةٌ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى الْفُلْكِ الْمَشْحُونِ",
    "وَخَلَقْنَا لَهُم مِّن مِّثْلِهِۦ مَا يَرْكَبُونَ",
    "وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ",
    "إِلَّا رَحْمَةً مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٍ",
    "وَإِذَا قِيلَ لَهُمُ اتَّقُوا مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ",
    "وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ",
    "وَإِذَا قِيلَ لَهُمْ أَنفِقُوا مِمَّا رَزَقَكُمُ اللَّهُ قَالَ الَّذِينَ كَفَرُوا لِلَّذِينَ ءَامَنُوٓا أَنُطْعِمُ مَن لَّوْ يَشَآءُ اللَّهُ أَطْعَمَهُۥٓ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍ مُّبِينٍ",
    "وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ",
    "مَا يَنظُرُونَ إِلَّا صَيْحَةً وَٰحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ",
    "فَلَا يَسْتَطِيعُونَ تَوْصِيَةً وَلَآ إِلَىٰٓ أَهْلِهِمْ يَرْجِعُونَ",
    "وَنُفِخَ فِى الصُّورِ فَإِذَا هُم مِّنَ الْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ",
    "قَالُوا يَٰوَيْلَنَا مَن بَعَثَنَا مِن مَّرْقَدِنَا   هَٰذَا مَا وَعَدَ الرَّحْمَٰنُ وَصَدَقَ الْمُرْسَلُونَ",
    "إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ",
    "فَالْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَئًْا وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ",
    "إِنَّ أَصْحَٰبَ الْجَنَّةِ الْيَوْمَ فِى شُغُلٍ فَٰكِهُونَ",
    "هُمْ وَأَزْوَٰجُهُمْ فِى ظِلَٰلٍ عَلَى الْأَرَآئِكِ مُتَّكُِٔونَ",
    "لَهُمْ فِيهَا فَٰكِهَةٌ وَلَهُم مَّا يَدَّعُونَ",
    "سَلَٰمٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ",
    "وَامْتَٰزُوا الْيَوْمَ أَيُّهَا الْمُجْرِمُونَ",
    "۞ أَلَمْ أَعْهَدْ إِلَيْكُمْ يَٰبَنِىٓ ءَادَمَ أَن لَّا تَعْبُدُوا الشَّيْطَٰنَ  إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ",
    "وَأَنِ اعْبُدُونِى  هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ",
    "وَلَقَدْ أَضَلَّ مِنكُمْ جِبِلًّا كَثِيرًا  أَفَلَمْ تَكُونُوا تَعْقِلُونَ",
    "هَٰذِهِۦ جَهَنَّمُ الَّتِى كُنتُمْ تُوعَدُونَ",
    "اصْلَوْهَا الْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ",
    "الْيَوْمَ نَخْتِمُ عَلَىٰٓ أَفْوَٰهِهِمْ وَتُكَلِّمُنَآ أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا يَكْسِبُونَ",
    "وَلَوْ نَشَآءُ لَطَمَسْنَا عَلَىٰٓ أَعْيُنِهِمْ فَاسْتَبَقُوا الصِّرَٰطَ فَأَنَّىٰ يُبْصِرُونَ",
    "وَلَوْ نَشَآءُ لَمَسَخْنَٰهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا اسْتَطَٰعُوا مُضِيًّا وَلَا يَرْجِعُونَ",
    "وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِى الْخَلْقِ  أَفَلَا يَعْقِلُونَ",
    "وَمَا عَلَّمْنَٰهُ الشِّعْرَ وَمَا يَنبَغِى لَهُۥٓ  إِنْ هُوَ إِلَّا ذِكْرٌ وَقُرْءَانٌ مُّبِينٌ",
    "لِّيُنذِرَ مَن كَانَ حَيًّا وَيَحِقَّ الْقَوْلُ عَلَى الْكَٰفِرِينَ",
    "أَوَلَمْ يَرَوْا أَنَّا خَلَقْنَا لَهُم مِّمَّا عَمِلَتْ أَيْدِينَآ أَنْعَٰمًا فَهُمْ لَهَا مَٰلِكُونَ",
    "وَذَلَّلْنَٰهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ",
    "وَلَهُمْ فِيهَا مَنَٰفِعُ وَمَشَارِبُ  أَفَلَا يَشْكُرُونَ",
    "وَاتَّخَذُوا مِن دُونِ اللَّهِ ءَالِهَةً لَّعَلَّهُمْ يُنصَرُونَ",
    "لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌ مُّحْضَرُونَ",
    "فَلَا يَحْزُنكَ قَوْلُهُمْ  إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ",
    "أَوَلَمْ يَرَ الْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ",
    "وَضَرَبَ لَنَا مَثَلًا وَنَسِىَ خَلْقَهُۥ  قَالَ مَن يُحْىِ الْعِظَٰمَ وَهِىَ رَمِيمٌ",
    "قُلْ يُحْيِيهَا الَّذِىٓ أَنشَأَهَآ أَوَّلَ مَرَّةٍ  وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ",
    "الَّذِى جَعَلَ لَكُم مِّنَ الشَّجَرِ الْأَخْضَرِ نَارًا فَإِذَآ أَنتُم مِّنْهُ تُوقِدُونَ",
    "أَوَلَيْسَ الَّذِى خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُم  بَلَىٰ وَهُوَ الْخَلَّٰقُ الْعَلِيمُ",
    "إِنَّمَآ أَمْرُهُۥٓ إِذَآ أَرَادَ شَئًْا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ",
    "فَسُبْحَٰنَ الَّذِى بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَإِلَيْهِ تُرْجَعُونَ",
  ],
  37: [
    "وَالصَّٰٓفَّٰتِ صَفًّا",
    "فَالزَّٰجِرَٰتِ زَجْرًا",
    "فَالتَّٰلِيَٰتِ ذِكْرًا",
    "إِنَّ إِلَٰهَكُمْ لَوَٰحِدٌ",
    "رَّبُّ السَّمَٰوَٰتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ الْمَشَٰرِقِ",
    "إِنَّا زَيَّنَّا السَّمَآءَ الدُّنْيَا بِزِينَةٍ الْكَوَاكِبِ",
    "وَحِفْظًا مِّن كُلِّ شَيْطَٰنٍ مَّارِدٍ",
    "لَّا يَسَّمَّعُونَ إِلَى الْمَلَإِ الْأَعْلَىٰ وَيُقْذَفُونَ مِن كُلِّ جَانِبٍ",
    "دُحُورًا  وَلَهُمْ عَذَابٌ وَاصِبٌ",
    "إِلَّا مَنْ خَطِفَ الْخَطْفَةَ فَأَتْبَعَهُۥ شِهَابٌ ثَاقِبٌ",
    "فَاسْتَفْتِهِمْ أَهُمْ أَشَدُّ خَلْقًا أَم مَّنْ خَلَقْنَآ  إِنَّا خَلَقْنَٰهُم مِّن طِينٍ لَّازِبٍ",
    "بَلْ عَجِبْتَ وَيَسْخَرُونَ",
    "وَإِذَا ذُكِّرُوا لَا يَذْكُرُونَ",
    "وَإِذَا رَأَوْا ءَايَةً يَسْتَسْخِرُونَ",
    "وَقَالُوٓا إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ",
    "أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ",
    "أَوَءَابَآؤُنَا الْأَوَّلُونَ",
    "قُلْ نَعَمْ وَأَنتُمْ دَٰخِرُونَ",
    "فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ فَإِذَا هُمْ يَنظُرُونَ",
    "وَقَالُوا يَٰوَيْلَنَا هَٰذَا يَوْمُ الدِّينِ",
    "هَٰذَا يَوْمُ الْفَصْلِ الَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ",
    "۞ احْشُرُوا الَّذِينَ ظَلَمُوا وَأَزْوَٰجَهُمْ وَمَا كَانُوا يَعْبُدُونَ",
    "مِن دُونِ اللَّهِ فَاهْدُوهُمْ إِلَىٰ صِرَٰطِ الْجَحِيمِ",
    "وَقِفُوهُمْ  إِنَّهُم مَّسُْٔولُونَ",
    "مَا لَكُمْ لَا تَنَاصَرُونَ",
    "بَلْ هُمُ الْيَوْمَ مُسْتَسْلِمُونَ",
    "وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ",
    "قَالُوٓا إِنَّكُمْ كُنتُمْ تَأْتُونَنَا عَنِ الْيَمِينِ",
    "قَالُوا بَل لَّمْ تَكُونُوا مُؤْمِنِينَ",
    "وَمَا كَانَ لَنَا عَلَيْكُم مِّن سُلْطَٰنٍ  بَلْ كُنتُمْ قَوْمًا طَٰغِينَ",
    "فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَآ  إِنَّا لَذَآئِقُونَ",
    "فَأَغْوَيْنَٰكُمْ إِنَّا كُنَّا غَٰوِينَ",
    "فَإِنَّهُمْ يَوْمَئِذٍ فِى الْعَذَابِ مُشْتَرِكُونَ",
    "إِنَّا كَذَٰلِكَ نَفْعَلُ بِالْمُجْرِمِينَ",
    "إِنَّهُمْ كَانُوٓا إِذَا قِيلَ لَهُمْ لَآ إِلَٰهَ إِلَّا اللَّهُ يَسْتَكْبِرُونَ",
    "وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓا ءَالِهَتِنَا لِشَاعِرٍ مَّجْنُونٍ",
    "بَلْ جَآءَ بِالْحَقِّ وَصَدَّقَ الْمُرْسَلِينَ",
    "إِنَّكُمْ لَذَآئِقُوا الْعَذَابِ الْأَلِيمِ",
    "وَمَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ",
    "إِلَّا عِبَادَ اللَّهِ الْمُخْلَصِينَ",
    "أُولَٰٓئِكَ لَهُمْ رِزْقٌ مَّعْلُومٌ",
    "فَوَٰكِهُ  وَهُم مُّكْرَمُونَ",
    "فِى جَنَّٰتِ النَّعِيمِ",
    "عَلَىٰ سُرُرٍ مُّتَقَٰبِلِينَ",
    "يُطَافُ عَلَيْهِم بِكَأْسٍ مِّن مَّعِينٍ",
    "بَيْضَآءَ لَذَّةٍ لِّلشَّٰرِبِينَ",
    "لَا فِيهَا غَوْلٌ وَلَا هُمْ عَنْهَا يُنزَفُونَ",
    "وَعِندَهُمْ قَٰصِرَٰتُ الطَّرْفِ عِينٌ",
    "كَأَنَّهُنَّ بَيْضٌ مَّكْنُونٌ",
    "فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ",
    "قَالَ قَآئِلٌ مِّنْهُمْ إِنِّى كَانَ لِى قَرِينٌ",
    "يَقُولُ أَءِنَّكَ لَمِنَ الْمُصَدِّقِينَ",
    "أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَدِينُونَ",
    "قَالَ هَلْ أَنتُم مُّطَّلِعُونَ",
    "فَاطَّلَعَ فَرَءَاهُ فِى سَوَآءِ الْجَحِيمِ",
    "قَالَ تَاللَّهِ إِن كِدتَّ لَتُرْدِينِ",
    "وَلَوْلَا نِعْمَةُ رَبِّى لَكُنتُ مِنَ الْمُحْضَرِينَ",
    "أَفَمَا نَحْنُ بِمَيِّتِينَ",
    "إِلَّا مَوْتَتَنَا الْأُولَىٰ وَمَا نَحْنُ بِمُعَذَّبِينَ",
    "إِنَّ هَٰذَا لَهُوَ الْفَوْزُ الْعَظِيمُ",
    "لِمِثْلِ هَٰذَا فَلْيَعْمَلِ الْعَٰمِلُونَ",
    "أَذَٰلِكَ خَيْرٌ نُّزُلًا أَمْ شَجَرَةُ الزَّقُّومِ",
    "إِنَّا جَعَلْنَٰهَا فِتْنَةً لِّلظَّٰلِمِينَ",
    "إِنَّهَا شَجَرَةٌ تَخْرُجُ فِىٓ أَصْلِ الْجَحِيمِ",
    "طَلْعُهَا كَأَنَّهُۥ رُءُوسُ الشَّيَٰطِينِ",
    "فَإِنَّهُمْ لََٔاكِلُونَ مِنْهَا فَمَالُِٔونَ مِنْهَا الْبُطُونَ",
    "ثُمَّ إِنَّ لَهُمْ عَلَيْهَا لَشَوْبًا مِّنْ حَمِيمٍ",
    "ثُمَّ إِنَّ مَرْجِعَهُمْ لَإِلَى الْجَحِيمِ",
    "إِنَّهُمْ أَلْفَوْا ءَابَآءَهُمْ ضَآلِّينَ",
    "فَهُمْ عَلَىٰٓ ءَاثَٰرِهِمْ يُهْرَعُونَ",
    "وَلَقَدْ ضَلَّ قَبْلَهُمْ أَكْثَرُ الْأَوَّلِينَ",
    "وَلَقَدْ أَرْسَلْنَا فِيهِم مُّنذِرِينَ",
    "فَانظُرْ كَيْفَ كَانَ عَٰقِبَةُ الْمُنذَرِينَ",
    "إِلَّا عِبَادَ اللَّهِ الْمُخْلَصِينَ",
    "وَلَقَدْ نَادَىٰنَا نُوحٌ فَلَنِعْمَ الْمُجِيبُونَ",
    "وَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ الْكَرْبِ الْعَظِيمِ",
    "وَجَعَلْنَا ذُرِّيَّتَهُۥ هُمُ الْبَاقِينَ",
    "وَتَرَكْنَا عَلَيْهِ فِى الَْٔاخِرِينَ",
    "سَلَٰمٌ عَلَىٰ نُوحٍ فِى الْعَٰلَمِينَ",
    "إِنَّا كَذَٰلِكَ نَجْزِى الْمُحْسِنِينَ",
    "إِنَّهُۥ مِنْ عِبَادِنَا الْمُؤْمِنِينَ",
    "ثُمَّ أَغْرَقْنَا الَْٔاخَرِينَ",
    "۞ وَإِنَّ مِن شِيعَتِهِۦ لَإِبْرَٰهِيمَ",
    "إِذْ جَآءَ رَبَّهُۥ بِقَلْبٍ سَلِيمٍ",
    "إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَاذَا تَعْبُدُونَ",
    "أَئِفْكًا ءَالِهَةً دُونَ اللَّهِ تُرِيدُونَ",
    "فَمَا ظَنُّكُم بِرَبِّ الْعَٰلَمِينَ",
    "فَنَظَرَ نَظْرَةً فِى النُّجُومِ",
    "فَقَالَ إِنِّى سَقِيمٌ",
    "فَتَوَلَّوْا عَنْهُ مُدْبِرِينَ",
    "فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمْ فَقَالَ أَلَا تَأْكُلُونَ",
    "مَا لَكُمْ لَا تَنطِقُونَ",
    "فَرَاغَ عَلَيْهِمْ ضَرْبًا بِالْيَمِينِ",
    "فَأَقْبَلُوٓا إِلَيْهِ يَزِفُّونَ",
    "قَالَ أَتَعْبُدُونَ مَا تَنْحِتُونَ",
    "وَاللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ",
    "قَالُوا ابْنُوا لَهُۥ بُنْيَٰنًا فَأَلْقُوهُ فِى الْجَحِيمِ",
    "فَأَرَادُوا بِهِۦ كَيْدًا فَجَعَلْنَٰهُمُ الْأَسْفَلِينَ",
    "وَقَالَ إِنِّى ذَاهِبٌ إِلَىٰ رَبِّى سَيَهْدِينِ",
    "رَبِّ هَبْ لِى مِنَ الصَّٰلِحِينَ",
    "فَبَشَّرْنَٰهُ بِغُلَٰمٍ حَلِيمٍ",
    "فَلَمَّا بَلَغَ مَعَهُ السَّعْىَ قَالَ يَٰبُنَىَّ إِنِّىٓ أَرَىٰ فِى الْمَنَامِ أَنِّىٓ أَذْبَحُكَ فَانظُرْ مَاذَا تَرَىٰ  قَالَ يَٰٓأَبَتِ افْعَلْ مَا تُؤْمَرُ  سَتَجِدُنِىٓ إِن شَآءَ اللَّهُ مِنَ الصَّٰبِرِينَ",
    "فَلَمَّآ أَسْلَمَا وَتَلَّهُۥ لِلْجَبِينِ",
    "وَنَٰدَيْنَٰهُ أَن يَٰٓإِبْرَٰهِيمُ",
    "قَدْ صَدَّقْتَ الرُّءْيَآ  إِنَّا كَذَٰلِكَ نَجْزِى الْمُحْسِنِينَ",
    "إِنَّ هَٰذَا لَهُوَ الْبَلَٰٓؤُا الْمُبِينُ",
    "وَفَدَيْنَٰهُ بِذِبْحٍ عَظِيمٍ",
    "وَتَرَكْنَا عَلَيْهِ فِى الَْٔاخِرِينَ",
    "سَلَٰمٌ عَلَىٰٓ إِبْرَٰهِيمَ",
    "كَذَٰلِكَ نَجْزِى الْمُحْسِنِينَ",
    "إِنَّهُۥ مِنْ عِبَادِنَا الْمُؤْمِنِينَ",
    "وَبَشَّرْنَٰهُ بِإِسْحَٰقَ نَبِيًّا مِّنَ الصَّٰلِحِينَ",
    "وَبَٰرَكْنَا عَلَيْهِ وَعَلَىٰٓ إِسْحَٰقَ  وَمِن ذُرِّيَّتِهِمَا مُحْسِنٌ وَظَالِمٌ لِّنَفْسِهِۦ مُبِينٌ",
    "وَلَقَدْ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَٰرُونَ",
    "وَنَجَّيْنَٰهُمَا وَقَوْمَهُمَا مِنَ الْكَرْبِ الْعَظِيمِ",
    "وَنَصَرْنَٰهُمْ فَكَانُوا هُمُ الْغَٰلِبِينَ",
    "وَءَاتَيْنَٰهُمَا الْكِتَٰبَ الْمُسْتَبِينَ",
    "وَهَدَيْنَٰهُمَا الصِّرَٰطَ الْمُسْتَقِيمَ",
    "وَتَرَكْنَا عَلَيْهِمَا فِى الَْٔاخِرِينَ",
    "سَلَٰمٌ عَلَىٰ مُوسَىٰ وَهَٰرُونَ",
    "إِنَّا كَذَٰلِكَ نَجْزِى الْمُحْسِنِينَ",
    "إِنَّهُمَا مِنْ عِبَادِنَا الْمُؤْمِنِينَ",
    "وَإِنَّ إِلْيَاسَ لَمِنَ الْمُرْسَلِينَ",
    "إِذْ قَالَ لِقَوْمِهِۦٓ أَلَا تَتَّقُونَ",
    "أَتَدْعُونَ بَعْلًا وَتَذَرُونَ أَحْسَنَ الْخَٰلِقِينَ",
    "اللَّهَ رَبَّكُمْ وَرَبَّ ءَابَآئِكُمُ الْأَوَّلِينَ",
    "فَكَذَّبُوهُ فَإِنَّهُمْ لَمُحْضَرُونَ",
    "إِلَّا عِبَادَ اللَّهِ الْمُخْلَصِينَ",
    "وَتَرَكْنَا عَلَيْهِ فِى الَْٔاخِرِينَ",
    "سَلَٰمٌ عَلَىٰٓ إِلْ يَاسِينَ",
    "إِنَّا كَذَٰلِكَ نَجْزِى الْمُحْسِنِينَ",
    "إِنَّهُۥ مِنْ عِبَادِنَا الْمُؤْمِنِينَ",
    "وَإِنَّ لُوطًا لَّمِنَ الْمُرْسَلِينَ",
    "إِذْ نَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ",
    "إِلَّا عَجُوزًا فِى الْغَٰبِرِينَ",
    "ثُمَّ دَمَّرْنَا الَْٔاخَرِينَ",
    "وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِم مُّصْبِحِينَ",
    "وَبِالَّيْلِ  أَفَلَا تَعْقِلُونَ",
    "وَإِنَّ يُونُسَ لَمِنَ الْمُرْسَلِينَ",
    "إِذْ أَبَقَ إِلَى الْفُلْكِ الْمَشْحُونِ",
    "فَسَاهَمَ فَكَانَ مِنَ الْمُدْحَضِينَ",
    "فَالْتَقَمَهُ الْحُوتُ وَهُوَ مُلِيمٌ",
    "فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ الْمُسَبِّحِينَ",
    "لَلَبِثَ فِى بَطْنِهِۦٓ إِلَىٰ يَوْمِ يُبْعَثُونَ",
    "۞ فَنَبَذْنَٰهُ بِالْعَرَآءِ وَهُوَ سَقِيمٌ",
    "وَأَنبَتْنَا عَلَيْهِ شَجَرَةً مِّن يَقْطِينٍ",
    "وَأَرْسَلْنَٰهُ إِلَىٰ مِائَةِ أَلْفٍ أَوْ يَزِيدُونَ",
    "فََٔامَنُوا فَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍ",
    "فَاسْتَفْتِهِمْ أَلِرَبِّكَ الْبَنَاتُ وَلَهُمُ الْبَنُونَ",
    "أَمْ خَلَقْنَا الْمَلَٰٓئِكَةَ إِنَٰثًا وَهُمْ شَٰهِدُونَ",
    "أَلَآ إِنَّهُم مِّنْ إِفْكِهِمْ لَيَقُولُونَ",
    "وَلَدَ اللَّهُ وَإِنَّهُمْ لَكَٰذِبُونَ",
    "أَصْطَفَى الْبَنَاتِ عَلَى الْبَنِينَ",
    "مَا لَكُمْ كَيْفَ تَحْكُمُونَ",
    "أَفَلَا تَذَكَّرُونَ",
    "أَمْ لَكُمْ سُلْطَٰنٌ مُّبِينٌ",
    "فَأْتُوا بِكِتَٰبِكُمْ إِن كُنتُمْ صَٰدِقِينَ",
    "وَجَعَلُوا بَيْنَهُۥ وَبَيْنَ الْجِنَّةِ نَسَبًا  وَلَقَدْ عَلِمَتِ الْجِنَّةُ إِنَّهُمْ لَمُحْضَرُونَ",
    "سُبْحَٰنَ اللَّهِ عَمَّا يَصِفُونَ",
    "إِلَّا عِبَادَ اللَّهِ الْمُخْلَصِينَ",
    "فَإِنَّكُمْ وَمَا تَعْبُدُونَ",
    "مَآ أَنتُمْ عَلَيْهِ بِفَٰتِنِينَ",
    "إِلَّا مَنْ هُوَ صَالِ الْجَحِيمِ",
    "وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٌ مَّعْلُومٌ",
    "وَإِنَّا لَنَحْنُ الصَّآفُّونَ",
    "وَإِنَّا لَنَحْنُ الْمُسَبِّحُونَ",
    "وَإِن كَانُوا لَيَقُولُونَ",
    "لَوْ أَنَّ عِندَنَا ذِكْرًا مِّنَ الْأَوَّلِينَ",
    "لَكُنَّا عِبَادَ اللَّهِ الْمُخْلَصِينَ",
    "فَكَفَرُوا بِهِۦ  فَسَوْفَ يَعْلَمُونَ",
    "وَلَقَدْ سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا الْمُرْسَلِينَ",
    "إِنَّهُمْ لَهُمُ الْمَنصُورُونَ",
    "وَإِنَّ جُندَنَا لَهُمُ الْغَٰلِبُونَ",
    "فَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ",
    "وَأَبْصِرْهُمْ فَسَوْفَ يُبْصِرُونَ",
    "أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ",
    "فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَآءَ صَبَاحُ الْمُنذَرِينَ",
    "وَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ",
    "وَأَبْصِرْ فَسَوْفَ يُبْصِرُونَ",
    "سُبْحَٰنَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ",
    "وَسَلَٰمٌ عَلَى الْمُرْسَلِينَ",
    "وَالْحَمْدُ لِلَّهِ رَبِّ الْعَٰلَمِينَ",
  ],
  38: [
    "صٓ  وَالْقُرْءَانِ ذِى الذِّكْرِ",
    "بَلِ الَّذِينَ كَفَرُوا فِى عِزَّةٍ وَشِقَاقٍ",
    "كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ فَنَادَوا وَّلَاتَ حِينَ مَنَاصٍ",
    "وَعَجِبُوٓا أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ  وَقَالَ الْكَٰفِرُونَ هَٰذَا سَٰحِرٌ كَذَّابٌ",
    "أَجَعَلَ الَْٔالِهَةَ إِلَٰهًا وَٰحِدًا  إِنَّ هَٰذَا لَشَىْءٌ عُجَابٌ",
    "وَانطَلَقَ الْمَلَأُ مِنْهُمْ أَنِ امْشُوا وَاصْبِرُوا عَلَىٰٓ ءَالِهَتِكُمْ  إِنَّ هَٰذَا لَشَىْءٌ يُرَادُ",
    "مَا سَمِعْنَا بِهَٰذَا فِى الْمِلَّةِ الَْٔاخِرَةِ إِنْ هَٰذَآ إِلَّا اخْتِلَٰقٌ",
    "أَءُنزِلَ عَلَيْهِ الذِّكْرُ مِن بَيْنِنَا  بَلْ هُمْ فِى شَكٍّ مِّن ذِكْرِى  بَل لَّمَّا يَذُوقُوا عَذَابِ",
    "أَمْ عِندَهُمْ خَزَآئِنُ رَحْمَةِ رَبِّكَ الْعَزِيزِ الْوَهَّابِ",
    "أَمْ لَهُم مُّلْكُ السَّمَٰوَٰتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا  فَلْيَرْتَقُوا فِى الْأَسْبَٰبِ",
    "جُندٌ مَّا هُنَالِكَ مَهْزُومٌ مِّنَ الْأَحْزَابِ",
    "كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَفِرْعَوْنُ ذُو الْأَوْتَادِ",
    "وَثَمُودُ وَقَوْمُ لُوطٍ وَأَصْحَٰبُ لَْٔيْكَةِ  أُولَٰٓئِكَ الْأَحْزَابُ",
    "إِن كُلٌّ إِلَّا كَذَّبَ الرُّسُلَ فَحَقَّ عِقَابِ",
    "وَمَا يَنظُرُ هَٰٓؤُلَآءِ إِلَّا صَيْحَةً وَٰحِدَةً مَّا لَهَا مِن فَوَاقٍ",
    "وَقَالُوا رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبْلَ يَوْمِ الْحِسَابِ",
    "اصْبِرْ عَلَىٰ مَا يَقُولُونَ وَاذْكُرْ عَبْدَنَا دَاوُۥدَ ذَا الْأَيْدِ  إِنَّهُۥٓ أَوَّابٌ",
    "إِنَّا سَخَّرْنَا الْجِبَالَ مَعَهُۥ يُسَبِّحْنَ بِالْعَشِىِّ وَالْإِشْرَاقِ",
    "وَالطَّيْرَ مَحْشُورَةً  كُلٌّ لَّهُۥٓ أَوَّابٌ",
    "وَشَدَدْنَا مُلْكَهُۥ وَءَاتَيْنَٰهُ الْحِكْمَةَ وَفَصْلَ الْخِطَابِ",
    "۞ وَهَلْ أَتَىٰكَ نَبَؤُا الْخَصْمِ إِذْ تَسَوَّرُوا الْمِحْرَابَ",
    "إِذْ دَخَلُوا عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنْهُمْ  قَالُوا لَا تَخَفْ  خَصْمَانِ بَغَىٰ بَعْضُنَا عَلَىٰ بَعْضٍ فَاحْكُم بَيْنَنَا بِالْحَقِّ وَلَا تُشْطِطْ وَاهْدِنَآ إِلَىٰ سَوَآءِ الصِّرَٰطِ",
    "إِنَّ هَٰذَآ أَخِى لَهُۥ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِىَ نَعْجَةٌ وَٰحِدَةٌ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِى فِى الْخِطَابِ",
    "قَالَ لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِهِۦ  وَإِنَّ كَثِيرًا مِّنَ الْخُلَطَآءِ لَيَبْغِى بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ وَقَلِيلٌ مَّا هُمْ  وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَاسْتَغْفَرَ رَبَّهُۥ وَخَرَّ رَاكِعًا وَأَنَابَ",
    "فَغَفَرْنَا لَهُۥ ذَٰلِكَ  وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مََٔابٍ",
    "يَٰدَاوُۥدُ إِنَّا جَعَلْنَٰكَ خَلِيفَةً فِى الْأَرْضِ فَاحْكُم بَيْنَ النَّاسِ بِالْحَقِّ وَلَا تَتَّبِعِ الْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ اللَّهِ  إِنَّ الَّذِينَ يَضِلُّونَ عَن سَبِيلِ اللَّهِ لَهُمْ عَذَابٌ شَدِيدٌ بِمَا نَسُوا يَوْمَ الْحِسَابِ",
    "وَمَا خَلَقْنَا السَّمَآءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا بَٰطِلًا  ذَٰلِكَ ظَنُّ الَّذِينَ كَفَرُوا  فَوَيْلٌ لِّلَّذِينَ كَفَرُوا مِنَ النَّارِ",
    "أَمْ نَجْعَلُ الَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ كَالْمُفْسِدِينَ فِى الْأَرْضِ أَمْ نَجْعَلُ الْمُتَّقِينَ كَالْفُجَّارِ",
    "كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ مُبَٰرَكٌ لِّيَدَّبَّرُوٓا ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُولُوا الْأَلْبَٰبِ",
    "وَوَهَبْنَا لِدَاوُۥدَ سُلَيْمَٰنَ  نِعْمَ الْعَبْدُ  إِنَّهُۥٓ أَوَّابٌ",
    "إِذْ عُرِضَ عَلَيْهِ بِالْعَشِىِّ الصَّٰفِنَٰتُ الْجِيَادُ",
    "فَقَالَ إِنِّىٓ أَحْبَبْتُ حُبَّ الْخَيْرِ عَن ذِكْرِ رَبِّى حَتَّىٰ تَوَارَتْ بِالْحِجَابِ",
    "رُدُّوهَا عَلَىَّ  فَطَفِقَ مَسْحًا بِالسُّوقِ وَالْأَعْنَاقِ",
    "وَلَقَدْ فَتَنَّا سُلَيْمَٰنَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِۦ جَسَدًا ثُمَّ أَنَابَ",
    "قَالَ رَبِّ اغْفِرْ لِى وَهَبْ لِى مُلْكًا لَّا يَنبَغِى لِأَحَدٍ مِّن بَعْدِىٓ  إِنَّكَ أَنتَ الْوَهَّابُ",
    "فَسَخَّرْنَا لَهُ الرِّيحَ تَجْرِى بِأَمْرِهِۦ رُخَآءً حَيْثُ أَصَابَ",
    "وَالشَّيَٰطِينَ كُلَّ بَنَّآءٍ وَغَوَّاصٍ",
    "وَءَاخَرِينَ مُقَرَّنِينَ فِى الْأَصْفَادِ",
    "هَٰذَا عَطَآؤُنَا فَامْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ",
    "وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مََٔابٍ",
    "وَاذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ الشَّيْطَٰنُ بِنُصْبٍ وَعَذَابٍ",
    "ارْكُضْ بِرِجْلِكَ  هَٰذَا مُغْتَسَلٌ بَارِدٌ وَشَرَابٌ",
    "وَوَهَبْنَا لَهُۥٓ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنَّا وَذِكْرَىٰ لِأُولِى الْأَلْبَٰبِ",
    "وَخُذْ بِيَدِكَ ضِغْثًا فَاضْرِب بِّهِۦ وَلَا تَحْنَثْ  إِنَّا وَجَدْنَٰهُ صَابِرًا  نِّعْمَ الْعَبْدُ  إِنَّهُۥٓ أَوَّابٌ",
    "وَاذْكُرْ عِبَٰدَنَآ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ أُولِى الْأَيْدِى وَالْأَبْصَٰرِ",
    "إِنَّآ أَخْلَصْنَٰهُم بِخَالِصَةٍ ذِكْرَى الدَّارِ",
    "وَإِنَّهُمْ عِندَنَا لَمِنَ الْمُصْطَفَيْنَ الْأَخْيَارِ",
    "وَاذْكُرْ إِسْمَٰعِيلَ وَالْيَسَعَ وَذَا الْكِفْلِ  وَكُلٌّ مِّنَ الْأَخْيَارِ",
    "هَٰذَا ذِكْرٌ  وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مََٔابٍ",
    "جَنَّٰتِ عَدْنٍ مُّفَتَّحَةً لَّهُمُ الْأَبْوَٰبُ",
    "مُتَّكِِٔينَ فِيهَا يَدْعُونَ فِيهَا بِفَٰكِهَةٍ كَثِيرَةٍ وَشَرَابٍ",
    "۞ وَعِندَهُمْ قَٰصِرَٰتُ الطَّرْفِ أَتْرَابٌ",
    "هَٰذَا مَا تُوعَدُونَ لِيَوْمِ الْحِسَابِ",
    "إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُۥ مِن نَّفَادٍ",
    "هَٰذَا  وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مََٔابٍ",
    "جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ الْمِهَادُ",
    "هَٰذَا فَلْيَذُوقُوهُ حَمِيمٌ وَغَسَّاقٌ",
    "وَءَاخَرُ مِن شَكْلِهِۦٓ أَزْوَٰجٌ",
    "هَٰذَا فَوْجٌ مُّقْتَحِمٌ مَّعَكُمْ  لَا مَرْحَبًا بِهِمْ  إِنَّهُمْ صَالُوا النَّارِ",
    "قَالُوا بَلْ أَنتُمْ لَا مَرْحَبًا بِكُمْ  أَنتُمْ قَدَّمْتُمُوهُ لَنَا  فَبِئْسَ الْقَرَارُ",
    "قَالُوا رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدْهُ عَذَابًا ضِعْفًا فِى النَّارِ",
    "وَقَالُوا مَا لَنَا لَا نَرَىٰ رِجَالًا كُنَّا نَعُدُّهُم مِّنَ الْأَشْرَارِ",
    "أَتَّخَذْنَٰهُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ الْأَبْصَٰرُ",
    "إِنَّ ذَٰلِكَ لَحَقٌّ تَخَاصُمُ أَهْلِ النَّارِ",
    "قُلْ إِنَّمَآ أَنَا مُنذِرٌ  وَمَا مِنْ إِلَٰهٍ إِلَّا اللَّهُ الْوَٰحِدُ الْقَهَّارُ",
    "رَبُّ السَّمَٰوَٰتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزِيزُ الْغَفَّٰرُ",
    "قُلْ هُوَ نَبَؤٌا عَظِيمٌ",
    "أَنتُمْ عَنْهُ مُعْرِضُونَ",
    "مَا كَانَ لِىَ مِنْ عِلْمٍ بِالْمَلَإِ الْأَعْلَىٰٓ إِذْ يَخْتَصِمُونَ",
    "إِن يُوحَىٰٓ إِلَىَّ إِلَّآ أَنَّمَآ أَنَا نَذِيرٌ مُّبِينٌ",
    "إِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌ بَشَرًا مِّن طِينٍ",
    "فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا لَهُۥ سَٰجِدِينَ",
    "فَسَجَدَ الْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ",
    "إِلَّآ إِبْلِيسَ اسْتَكْبَرَ وَكَانَ مِنَ الْكَٰفِرِينَ",
    "قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَىَّ  أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ الْعَالِينَ",
    "قَالَ أَنَا خَيْرٌ مِّنْهُ  خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ",
    "قَالَ فَاخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ",
    "وَإِنَّ عَلَيْكَ لَعْنَتِىٓ إِلَىٰ يَوْمِ الدِّينِ",
    "قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ",
    "قَالَ فَإِنَّكَ مِنَ الْمُنظَرِينَ",
    "إِلَىٰ يَوْمِ الْوَقْتِ الْمَعْلُومِ",
    "قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ",
    "إِلَّا عِبَادَكَ مِنْهُمُ الْمُخْلَصِينَ",
    "قَالَ فَالْحَقُّ وَالْحَقَّ أَقُولُ",
    "لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمْ أَجْمَعِينَ",
    "قُلْ مَآ أَسَْٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَآ أَنَا مِنَ الْمُتَكَلِّفِينَ",
    "إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ",
    "وَلَتَعْلَمُنَّ نَبَأَهُۥ بَعْدَ حِينٍ",
  ],
  39: [
    "تَنزِيلُ الْكِتَٰبِ مِنَ اللَّهِ الْعَزِيزِ الْحَكِيمِ",
    "إِنَّآ أَنزَلْنَآ إِلَيْكَ الْكِتَٰبَ بِالْحَقِّ فَاعْبُدِ اللَّهَ مُخْلِصًا لَّهُ الدِّينَ",
    "أَلَا لِلَّهِ الدِّينُ الْخَالِصُ  وَالَّذِينَ اتَّخَذُوا مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى اللَّهِ زُلْفَىٰٓ إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ  إِنَّ اللَّهَ لَا يَهْدِى مَنْ هُوَ كَٰذِبٌ كَفَّارٌ",
    "لَّوْ أَرَادَ اللَّهُ أَن يَتَّخِذَ وَلَدًا لَّاصْطَفَىٰ مِمَّا يَخْلُقُ مَا يَشَآءُ  سُبْحَٰنَهُۥ  هُوَ اللَّهُ الْوَٰحِدُ الْقَهَّارُ",
    "خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ بِالْحَقِّ  يُكَوِّرُ الَّيْلَ عَلَى النَّهَارِ وَيُكَوِّرُ النَّهَارَ عَلَى الَّيْلِ  وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ  كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى  أَلَا هُوَ الْعَزِيزُ الْغَفَّٰرُ",
    "خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا وَأَنزَلَ لَكُم مِّنَ الْأَنْعَٰمِ ثَمَٰنِيَةَ أَزْوَٰجٍ  يَخْلُقُكُمْ فِى بُطُونِ أُمَّهَٰتِكُمْ خَلْقًا مِّن بَعْدِ خَلْقٍ فِى ظُلُمَٰتٍ ثَلَٰثٍ  ذَٰلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ  لَآ إِلَٰهَ إِلَّا هُوَ  فَأَنَّىٰ تُصْرَفُونَ",
    "إِن تَكْفُرُوا فَإِنَّ اللَّهَ غَنِىٌّ عَنكُمْ  وَلَا يَرْضَىٰ لِعِبَادِهِ الْكُفْرَ  وَإِن تَشْكُرُوا يَرْضَهُ لَكُمْ  وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ  ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ  إِنَّهُۥ عَلِيمٌ بِذَاتِ الصُّدُورِ",
    "۞ وَإِذَا مَسَّ الْإِنسَٰنَ ضُرٌّ دَعَا رَبَّهُۥ مُنِيبًا إِلَيْهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعْمَةً مِّنْهُ نَسِىَ مَا كَانَ يَدْعُوٓا إِلَيْهِ مِن قَبْلُ وَجَعَلَ لِلَّهِ أَندَادًا لِّيُضِلَّ عَن سَبِيلِهِۦ  قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلًا  إِنَّكَ مِنْ أَصْحَٰبِ النَّارِ",
    "أَمَّنْ هُوَ قَٰنِتٌ ءَانَآءَ الَّيْلِ سَاجِدًا وَقَآئِمًا يَحْذَرُ الَْٔاخِرَةَ وَيَرْجُوا رَحْمَةَ رَبِّهِۦ  قُلْ هَلْ يَسْتَوِى الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ  إِنَّمَا يَتَذَكَّرُ أُولُوا الْأَلْبَٰبِ",
    "قُلْ يَٰعِبَادِ الَّذِينَ ءَامَنُوا اتَّقُوا رَبَّكُمْ  لِلَّذِينَ أَحْسَنُوا فِى هَٰذِهِ الدُّنْيَا حَسَنَةٌ  وَأَرْضُ اللَّهِ وَٰسِعَةٌ  إِنَّمَا يُوَفَّى الصَّٰبِرُونَ أَجْرَهُم بِغَيْرِ حِسَابٍ",
    "قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَعْبُدَ اللَّهَ مُخْلِصًا لَّهُ الدِّينَ",
    "وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ الْمُسْلِمِينَ",
    "قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ",
    "قُلِ اللَّهَ أَعْبُدُ مُخْلِصًا لَّهُۥ دِينِى",
    "فَاعْبُدُوا مَا شِئْتُم مِّن دُونِهِۦ  قُلْ إِنَّ الْخَٰسِرِينَ الَّذِينَ خَسِرُوٓا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَٰمَةِ  أَلَا ذَٰلِكَ هُوَ الْخُسْرَانُ الْمُبِينُ",
    "لَهُم مِّن فَوْقِهِمْ ظُلَلٌ مِّنَ النَّارِ وَمِن تَحْتِهِمْ ظُلَلٌ  ذَٰلِكَ يُخَوِّفُ اللَّهُ بِهِۦ عِبَادَهُۥ  يَٰعِبَادِ فَاتَّقُونِ",
    "وَالَّذِينَ اجْتَنَبُوا الطَّٰغُوتَ أَن يَعْبُدُوهَا وَأَنَابُوٓا إِلَى اللَّهِ لَهُمُ الْبُشْرَىٰ  فَبَشِّرْ عِبَادِ",
    "الَّذِينَ يَسْتَمِعُونَ الْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ  أُولَٰٓئِكَ الَّذِينَ هَدَىٰهُمُ اللَّهُ  وَأُولَٰٓئِكَ هُمْ أُولُوا الْأَلْبَٰبِ",
    "أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ الْعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِى النَّارِ",
    "لَٰكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ غُرَفٌ مِّن فَوْقِهَا غُرَفٌ مَّبْنِيَّةٌ تَجْرِى مِن تَحْتِهَا الْأَنْهَٰرُ  وَعْدَ اللَّهِ  لَا يُخْلِفُ اللَّهُ الْمِيعَادَ",
    "أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَآءِ مَآءً فَسَلَكَهُۥ يَنَٰبِيعَ فِى الْأَرْضِ ثُمَّ يُخْرِجُ بِهِۦ زَرْعًا مُّخْتَلِفًا أَلْوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَجْعَلُهُۥ حُطَٰمًا  إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِأُولِى الْأَلْبَٰبِ",
    "أَفَمَن شَرَحَ اللَّهُ صَدْرَهُۥ لِلْإِسْلَٰمِ فَهُوَ عَلَىٰ نُورٍ مِّن رَّبِّهِۦ  فَوَيْلٌ لِّلْقَٰسِيَةِ قُلُوبُهُم مِّن ذِكْرِ اللَّهِ  أُولَٰٓئِكَ فِى ضَلَٰلٍ مُّبِينٍ",
    "اللَّهُ نَزَّلَ أَحْسَنَ الْحَدِيثِ كِتَٰبًا مُّتَشَٰبِهًا مَّثَانِىَ تَقْشَعِرُّ مِنْهُ جُلُودُ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ اللَّهِ  ذَٰلِكَ هُدَى اللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ  وَمَن يُضْلِلِ اللَّهُ فَمَا لَهُۥ مِنْ هَادٍ",
    "أَفَمَن يَتَّقِى بِوَجْهِهِۦ سُوٓءَ الْعَذَابِ يَوْمَ الْقِيَٰمَةِ  وَقِيلَ لِلظَّٰلِمِينَ ذُوقُوا مَا كُنتُمْ تَكْسِبُونَ",
    "كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ فَأَتَىٰهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ",
    "فَأَذَاقَهُمُ اللَّهُ الْخِزْىَ فِى الْحَيَوٰةِ الدُّنْيَا  وَلَعَذَابُ الَْٔاخِرَةِ أَكْبَرُ  لَوْ كَانُوا يَعْلَمُونَ",
    "وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا الْقُرْءَانِ مِن كُلِّ مَثَلٍ لَّعَلَّهُمْ يَتَذَكَّرُونَ",
    "قُرْءَانًا عَرَبِيًّا غَيْرَ ذِى عِوَجٍ لَّعَلَّهُمْ يَتَّقُونَ",
    "ضَرَبَ اللَّهُ مَثَلًا رَّجُلًا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلًا سَلَمًا لِّرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلًا  الْحَمْدُ لِلَّهِ  بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ",
    "إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ",
    "ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ",
    "۞ فَمَنْ أَظْلَمُ مِمَّن كَذَبَ عَلَى اللَّهِ وَكَذَّبَ بِالصِّدْقِ إِذْ جَآءَهُۥٓ  أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَٰفِرِينَ",
    "وَالَّذِى جَآءَ بِالصِّدْقِ وَصَدَّقَ بِهِۦٓ  أُولَٰٓئِكَ هُمُ الْمُتَّقُونَ",
    "لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ  ذَٰلِكَ جَزَآءُ الْمُحْسِنِينَ",
    "لِيُكَفِّرَ اللَّهُ عَنْهُمْ أَسْوَأَ الَّذِى عَمِلُوا وَيَجْزِيَهُمْ أَجْرَهُم بِأَحْسَنِ الَّذِى كَانُوا يَعْمَلُونَ",
    "أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُۥ  وَيُخَوِّفُونَكَ بِالَّذِينَ مِن دُونِهِۦ  وَمَن يُضْلِلِ اللَّهُ فَمَا لَهُۥ مِنْ هَادٍ",
    "وَمَن يَهْدِ اللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّ  أَلَيْسَ اللَّهُ بِعَزِيزٍ ذِى انتِقَامٍ",
    "وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَٰوَٰتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ  قُلْ أَفَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ اللَّهِ إِنْ أَرَادَنِىَ اللَّهُ بِضُرٍّ هَلْ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوْ أَرَادَنِى بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَٰتُ رَحْمَتِهِۦ  قُلْ حَسْبِىَ اللَّهُ  عَلَيْهِ يَتَوَكَّلُ الْمُتَوَكِّلُونَ",
    "قُلْ يَٰقَوْمِ اعْمَلُوا عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌ  فَسَوْفَ تَعْلَمُونَ",
    "مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ",
    "إِنَّآ أَنزَلْنَا عَلَيْكَ الْكِتَٰبَ لِلنَّاسِ بِالْحَقِّ  فَمَنِ اهْتَدَىٰ فَلِنَفْسِهِۦ  وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا  وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ",
    "اللَّهُ يَتَوَفَّى الْأَنفُسَ حِينَ مَوْتِهَا وَالَّتِى لَمْ تَمُتْ فِى مَنَامِهَا  فَيُمْسِكُ الَّتِى قَضَىٰ عَلَيْهَا الْمَوْتَ وَيُرْسِلُ الْأُخْرَىٰٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ",
    "أَمِ اتَّخَذُوا مِن دُونِ اللَّهِ شُفَعَآءَ  قُلْ أَوَلَوْ كَانُوا لَا يَمْلِكُونَ شَئًْا وَلَا يَعْقِلُونَ",
    "قُل لِّلَّهِ الشَّفَٰعَةُ جَمِيعًا  لَّهُۥ مُلْكُ السَّمَٰوَٰتِ وَالْأَرْضِ  ثُمَّ إِلَيْهِ تُرْجَعُونَ",
    "وَإِذَا ذُكِرَ اللَّهُ وَحْدَهُ اشْمَأَزَّتْ قُلُوبُ الَّذِينَ لَا يُؤْمِنُونَ بِالَْٔاخِرَةِ  وَإِذَا ذُكِرَ الَّذِينَ مِن دُونِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ",
    "قُلِ اللَّهُمَّ فَاطِرَ السَّمَٰوَٰتِ وَالْأَرْضِ عَٰلِمَ الْغَيْبِ وَالشَّهَٰدَةِ أَنتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِى مَا كَانُوا فِيهِ يَخْتَلِفُونَ",
    "وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا مَا فِى الْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَافْتَدَوْا بِهِۦ مِن سُوٓءِ الْعَذَابِ يَوْمَ الْقِيَٰمَةِ  وَبَدَا لَهُم مِّنَ اللَّهِ مَا لَمْ يَكُونُوا يَحْتَسِبُونَ",
    "وَبَدَا لَهُمْ سَئَِّاتُ مَا كَسَبُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِۦ يَسْتَهْزِءُونَ",
    "فَإِذَا مَسَّ الْإِنسَٰنَ ضُرٌّ دَعَانَا ثُمَّ إِذَا خَوَّلْنَٰهُ نِعْمَةً مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍ  بَلْ هِىَ فِتْنَةٌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ",
    "قَدْ قَالَهَا الَّذِينَ مِن قَبْلِهِمْ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا يَكْسِبُونَ",
    "فَأَصَابَهُمْ سَئَِّاتُ مَا كَسَبُوا  وَالَّذِينَ ظَلَمُوا مِنْ هَٰٓؤُلَآءِ سَيُصِيبُهُمْ سَئَِّاتُ مَا كَسَبُوا وَمَا هُم بِمُعْجِزِينَ",
    "أَوَلَمْ يَعْلَمُوٓا أَنَّ اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ  إِنَّ فِى ذَٰلِكَ لََٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ",
    "۞ قُلْ يَٰعِبَادِىَ الَّذِينَ أَسْرَفُوا عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ  إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا  إِنَّهُۥ هُوَ الْغَفُورُ الرَّحِيمُ",
    "وَأَنِيبُوٓا إِلَىٰ رَبِّكُمْ وَأَسْلِمُوا لَهُۥ مِن قَبْلِ أَن يَأْتِيَكُمُ الْعَذَابُ ثُمَّ لَا تُنصَرُونَ",
    "وَاتَّبِعُوٓا أَحْسَنَ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُم مِّن قَبْلِ أَن يَأْتِيَكُمُ الْعَذَابُ بَغْتَةً وَأَنتُمْ لَا تَشْعُرُونَ",
    "أَن تَقُولَ نَفْسٌ يَٰحَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَنبِ اللَّهِ وَإِن كُنتُ لَمِنَ السَّٰخِرِينَ",
    "أَوْ تَقُولَ لَوْ أَنَّ اللَّهَ هَدَىٰنِى لَكُنتُ مِنَ الْمُتَّقِينَ",
    "أَوْ تَقُولَ حِينَ تَرَى الْعَذَابَ لَوْ أَنَّ لِى كَرَّةً فَأَكُونَ مِنَ الْمُحْسِنِينَ",
    "بَلَىٰ قَدْ جَآءَتْكَ ءَايَٰتِى فَكَذَّبْتَ بِهَا وَاسْتَكْبَرْتَ وَكُنتَ مِنَ الْكَٰفِرِينَ",
    "وَيَوْمَ الْقِيَٰمَةِ تَرَى الَّذِينَ كَذَبُوا عَلَى اللَّهِ وُجُوهُهُم مُّسْوَدَّةٌ  أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْمُتَكَبِّرِينَ",
    "وَيُنَجِّى اللَّهُ الَّذِينَ اتَّقَوْا بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ السُّوٓءُ وَلَا هُمْ يَحْزَنُونَ",
    "اللَّهُ خَٰلِقُ كُلِّ شَىْءٍ  وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ",
    "لَّهُۥ مَقَالِيدُ السَّمَٰوَٰتِ وَالْأَرْضِ  وَالَّذِينَ كَفَرُوا بَِٔايَٰتِ اللَّهِ أُولَٰٓئِكَ هُمُ الْخَٰسِرُونَ",
    "قُلْ أَفَغَيْرَ اللَّهِ تَأْمُرُوٓنِّىٓ أَعْبُدُ أَيُّهَا الْجَٰهِلُونَ",
    "وَلَقَدْ أُوحِىَ إِلَيْكَ وَإِلَى الَّذِينَ مِن قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَٰسِرِينَ",
    "بَلِ اللَّهَ فَاعْبُدْ وَكُن مِّنَ الشَّٰكِرِينَ",
    "وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِۦ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُۥ يَوْمَ الْقِيَٰمَةِ وَالسَّمَٰوَٰتُ مَطْوِيَّٰتٌ بِيَمِينِهِۦ  سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ",
    "وَنُفِخَ فِى الصُّورِ فَصَعِقَ مَن فِى السَّمَٰوَٰتِ وَمَن فِى الْأَرْضِ إِلَّا مَن شَآءَ اللَّهُ  ثُمَّ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَامٌ يَنظُرُونَ",
    "وَأَشْرَقَتِ الْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ الْكِتَٰبُ وَجِاىٓءَ بِالنَّبِيِّنَ وَالشُّهَدَآءِ وَقُضِىَ بَيْنَهُم بِالْحَقِّ وَهُمْ لَا يُظْلَمُونَ",
    "وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ",
    "وَسِيقَ الَّذِينَ كَفَرُوٓا إِلَىٰ جَهَنَّمَ زُمَرًا  حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَتْلُونَ عَلَيْكُمْ ءَايَٰتِ رَبِّكُمْ وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا  قَالُوا بَلَىٰ وَلَٰكِنْ حَقَّتْ كَلِمَةُ الْعَذَابِ عَلَى الْكَٰفِرِينَ",
    "قِيلَ ادْخُلُوٓا أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا  فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ",
    "وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا  حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَٰمٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَٰلِدِينَ",
    "وَقَالُوا الْحَمْدُ لِلَّهِ الَّذِى صَدَقَنَا وَعْدَهُۥ وَأَوْرَثَنَا الْأَرْضَ نَتَبَوَّأُ مِنَ الْجَنَّةِ حَيْثُ نَشَآءُ  فَنِعْمَ أَجْرُ الْعَٰمِلِينَ",
    "وَتَرَى الْمَلَٰٓئِكَةَ حَآفِّينَ مِنْ حَوْلِ الْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ  وَقُضِىَ بَيْنَهُم بِالْحَقِّ وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَٰلَمِينَ",
  ],
  40: [
    "حمٓ",
    "تَنزِيلُ الْكِتَٰبِ مِنَ اللَّهِ الْعَزِيزِ الْعَلِيمِ",
    "غَافِرِ الذَّنبِ وَقَابِلِ التَّوْبِ شَدِيدِ الْعِقَابِ ذِى الطَّوْلِ  لَآ إِلَٰهَ إِلَّا هُوَ  إِلَيْهِ الْمَصِيرُ",
    "مَا يُجَٰدِلُ فِىٓ ءَايَٰتِ اللَّهِ إِلَّا الَّذِينَ كَفَرُوا فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِى الْبِلَٰدِ",
    "كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَالْأَحْزَابُ مِن بَعْدِهِمْ  وَهَمَّتْ كُلُّ أُمَّةٍ بِرَسُولِهِمْ لِيَأْخُذُوهُ  وَجَٰدَلُوا بِالْبَٰطِلِ لِيُدْحِضُوا بِهِ الْحَقَّ فَأَخَذْتُهُمْ  فَكَيْفَ كَانَ عِقَابِ",
    "وَكَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى الَّذِينَ كَفَرُوٓا أَنَّهُمْ أَصْحَٰبُ النَّارِ",
    "الَّذِينَ يَحْمِلُونَ الْعَرْشَ وَمَنْ حَوْلَهُۥ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِۦ وَيَسْتَغْفِرُونَ لِلَّذِينَ ءَامَنُوا رَبَّنَا وَسِعْتَ كُلَّ شَىْءٍ رَّحْمَةً وَعِلْمًا فَاغْفِرْ لِلَّذِينَ تَابُوا وَاتَّبَعُوا سَبِيلَكَ وَقِهِمْ عَذَابَ الْجَحِيمِ",
    "رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ الَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ  إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ",
    "وَقِهِمُ السَّئَِّاتِ  وَمَن تَقِ السَّئَِّاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُۥ  وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ",
    "إِنَّ الَّذِينَ كَفَرُوا يُنَادَوْنَ لَمَقْتُ اللَّهِ أَكْبَرُ مِن مَّقْتِكُمْ أَنفُسَكُمْ إِذْ تُدْعَوْنَ إِلَى الْإِيمَٰنِ فَتَكْفُرُونَ",
    "قَالُوا رَبَّنَآ أَمَتَّنَا اثْنَتَيْنِ وَأَحْيَيْتَنَا اثْنَتَيْنِ فَاعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَىٰ خُرُوجٍ مِّن سَبِيلٍ",
    "ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِىَ اللَّهُ وَحْدَهُۥ كَفَرْتُمْ  وَإِن يُشْرَكْ بِهِۦ تُؤْمِنُوا  فَالْحُكْمُ لِلَّهِ الْعَلِىِّ الْكَبِيرِ",
    "هُوَ الَّذِى يُرِيكُمْ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ السَّمَآءِ رِزْقًا  وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ",
    "فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَٰفِرُونَ",
    "رَفِيعُ الدَّرَجَٰتِ ذُو الْعَرْشِ يُلْقِى الرُّوحَ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ لِيُنذِرَ يَوْمَ التَّلَاقِ",
    "يَوْمَ هُم بَٰرِزُونَ  لَا يَخْفَىٰ عَلَى اللَّهِ مِنْهُمْ شَىْءٌ  لِّمَنِ الْمُلْكُ الْيَوْمَ  لِلَّهِ الْوَٰحِدِ الْقَهَّارِ",
    "الْيَوْمَ تُجْزَىٰ كُلُّ نَفْسٍ بِمَا كَسَبَتْ  لَا ظُلْمَ الْيَوْمَ  إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ",
    "وَأَنذِرْهُمْ يَوْمَ الَْٔازِفَةِ إِذِ الْقُلُوبُ لَدَى الْحَنَاجِرِ كَٰظِمِينَ  مَا لِلظَّٰلِمِينَ مِنْ حَمِيمٍ وَلَا شَفِيعٍ يُطَاعُ",
    "يَعْلَمُ خَآئِنَةَ الْأَعْيُنِ وَمَا تُخْفِى الصُّدُورُ",
    "وَاللَّهُ يَقْضِى بِالْحَقِّ  وَالَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَقْضُونَ بِشَىْءٍ  إِنَّ اللَّهَ هُوَ السَّمِيعُ الْبَصِيرُ",
    "۞ أَوَلَمْ يَسِيرُوا فِى الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَٰقِبَةُ الَّذِينَ كَانُوا مِن قَبْلِهِمْ  كَانُوا هُمْ أَشَدَّ مِنْهُمْ قُوَّةً وَءَاثَارًا فِى الْأَرْضِ فَأَخَذَهُمُ اللَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُم مِّنَ اللَّهِ مِن وَاقٍ",
    "ذَٰلِكَ بِأَنَّهُمْ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِالْبَيِّنَٰتِ فَكَفَرُوا فَأَخَذَهُمُ اللَّهُ  إِنَّهُۥ قَوِىٌّ شَدِيدُ الْعِقَابِ",
    "وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بَِٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ",
    "إِلَىٰ فِرْعَوْنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُوا سَٰحِرٌ كَذَّابٌ",
    "فَلَمَّا جَآءَهُم بِالْحَقِّ مِنْ عِندِنَا قَالُوا اقْتُلُوٓا أَبْنَآءَ الَّذِينَ ءَامَنُوا مَعَهُۥ وَاسْتَحْيُوا نِسَآءَهُمْ  وَمَا كَيْدُ الْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ",
    "وَقَالَ فِرْعَوْنُ ذَرُونِىٓ أَقْتُلْ مُوسَىٰ وَلْيَدْعُ رَبَّهُۥٓ  إِنِّىٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمْ أَوْ أَن يُظْهِرَ فِى الْأَرْضِ الْفَسَادَ",
    "وَقَالَ مُوسَىٰٓ إِنِّى عُذْتُ بِرَبِّى وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لَّا يُؤْمِنُ بِيَوْمِ الْحِسَابِ",
    "وَقَالَ رَجُلٌ مُّؤْمِنٌ مِّنْ ءَالِ فِرْعَوْنَ يَكْتُمُ إِيمَٰنَهُۥٓ أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّىَ اللَّهُ وَقَدْ جَآءَكُم بِالْبَيِّنَٰتِ مِن رَّبِّكُمْ  وَإِن يَكُ كَٰذِبًا فَعَلَيْهِ كَذِبُهُۥ  وَإِن يَكُ صَادِقًا يُصِبْكُم بَعْضُ الَّذِى يَعِدُكُمْ  إِنَّ اللَّهَ لَا يَهْدِى مَنْ هُوَ مُسْرِفٌ كَذَّابٌ",
    "يَٰقَوْمِ لَكُمُ الْمُلْكُ الْيَوْمَ ظَٰهِرِينَ فِى الْأَرْضِ فَمَن يَنصُرُنَا مِن بَأْسِ اللَّهِ إِن جَآءَنَا  قَالَ فِرْعَوْنُ مَآ أُرِيكُمْ إِلَّا مَآ أَرَىٰ وَمَآ أَهْدِيكُمْ إِلَّا سَبِيلَ الرَّشَادِ",
    "وَقَالَ الَّذِىٓ ءَامَنَ يَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُم مِّثْلَ يَوْمِ الْأَحْزَابِ",
    "مِثْلَ دَأْبِ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَالَّذِينَ مِن بَعْدِهِمْ  وَمَا اللَّهُ يُرِيدُ ظُلْمًا لِّلْعِبَادِ",
    "وَيَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُمْ يَوْمَ التَّنَادِ",
    "يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُم مِّنَ اللَّهِ مِنْ عَاصِمٍ  وَمَن يُضْلِلِ اللَّهُ فَمَا لَهُۥ مِنْ هَادٍ",
    "وَلَقَدْ جَآءَكُمْ يُوسُفُ مِن قَبْلُ بِالْبَيِّنَٰتِ فَمَا زِلْتُمْ فِى شَكٍّ مِّمَّا جَآءَكُم بِهِۦ  حَتَّىٰٓ إِذَا هَلَكَ قُلْتُمْ لَن يَبْعَثَ اللَّهُ مِن بَعْدِهِۦ رَسُولًا  كَذَٰلِكَ يُضِلُّ اللَّهُ مَنْ هُوَ مُسْرِفٌ مُّرْتَابٌ",
    "الَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ اللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ  كَبُرَ مَقْتًا عِندَ اللَّهِ وَعِندَ الَّذِينَ ءَامَنُوا  كَذَٰلِكَ يَطْبَعُ اللَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ",
    "وَقَالَ فِرْعَوْنُ يَٰهَٰمَٰنُ ابْنِ لِى صَرْحًا لَّعَلِّىٓ أَبْلُغُ الْأَسْبَٰبَ",
    "أَسْبَٰبَ السَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ كَٰذِبًا  وَكَذَٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ السَّبِيلِ  وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِى تَبَابٍ",
    "وَقَالَ الَّذِىٓ ءَامَنَ يَٰقَوْمِ اتَّبِعُونِ أَهْدِكُمْ سَبِيلَ الرَّشَادِ",
    "يَٰقَوْمِ إِنَّمَا هَٰذِهِ الْحَيَوٰةُ الدُّنْيَا مَتَٰعٌ وَإِنَّ الَْٔاخِرَةَ هِىَ دَارُ الْقَرَارِ",
    "مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا  وَمَنْ عَمِلَ صَٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُولَٰٓئِكَ يَدْخُلُونَ الْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ",
    "۞ وَيَٰقَوْمِ مَا لِىٓ أَدْعُوكُمْ إِلَى النَّجَوٰةِ وَتَدْعُونَنِىٓ إِلَى النَّارِ",
    "تَدْعُونَنِى لِأَكْفُرَ بِاللَّهِ وَأُشْرِكَ بِهِۦ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَأَنَا أَدْعُوكُمْ إِلَى الْعَزِيزِ الْغَفَّٰرِ",
    "لَا جَرَمَ أَنَّمَا تَدْعُونَنِىٓ إِلَيْهِ لَيْسَ لَهُۥ دَعْوَةٌ فِى الدُّنْيَا وَلَا فِى الَْٔاخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى اللَّهِ وَأَنَّ الْمُسْرِفِينَ هُمْ أَصْحَٰبُ النَّارِ",
    "فَسَتَذْكُرُونَ مَآ أَقُولُ لَكُمْ  وَأُفَوِّضُ أَمْرِىٓ إِلَى اللَّهِ  إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ",
    "فَوَقَىٰهُ اللَّهُ سَئَِّاتِ مَا مَكَرُوا  وَحَاقَ بَِٔالِ فِرْعَوْنَ سُوٓءُ الْعَذَابِ",
    "النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا  وَيَوْمَ تَقُومُ السَّاعَةُ أَدْخِلُوٓا ءَالَ فِرْعَوْنَ أَشَدَّ الْعَذَابِ",
    "وَإِذْ يَتَحَآجُّونَ فِى النَّارِ فَيَقُولُ الضُّعَفَٰٓؤُا لِلَّذِينَ اسْتَكْبَرُوٓا إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا نَصِيبًا مِّنَ النَّارِ",
    "قَالَ الَّذِينَ اسْتَكْبَرُوٓا إِنَّا كُلٌّ فِيهَآ إِنَّ اللَّهَ قَدْ حَكَمَ بَيْنَ الْعِبَادِ",
    "وَقَالَ الَّذِينَ فِى النَّارِ لِخَزَنَةِ جَهَنَّمَ ادْعُوا رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًا مِّنَ الْعَذَابِ",
    "قَالُوٓا أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِالْبَيِّنَٰتِ  قَالُوا بَلَىٰ  قَالُوا فَادْعُوا  وَمَا دُعَٰٓؤُا الْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ",
    "إِنَّا لَنَنصُرُ رُسُلَنَا وَالَّذِينَ ءَامَنُوا فِى الْحَيَوٰةِ الدُّنْيَا وَيَوْمَ يَقُومُ الْأَشْهَٰدُ",
    "يَوْمَ لَا يَنفَعُ الظَّٰلِمِينَ مَعْذِرَتُهُمْ  وَلَهُمُ اللَّعْنَةُ وَلَهُمْ سُوٓءُ الدَّارِ",
    "وَلَقَدْ ءَاتَيْنَا مُوسَى الْهُدَىٰ وَأَوْرَثْنَا بَنِىٓ إِسْرَٰٓءِيلَ الْكِتَٰبَ",
    "هُدًى وَذِكْرَىٰ لِأُولِى الْأَلْبَٰبِ",
    "فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ وَاسْتَغْفِرْ لِذَنبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِالْعَشِىِّ وَالْإِبْكَٰرِ",
    "إِنَّ الَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ اللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ  إِن فِى صُدُورِهِمْ إِلَّا كِبْرٌ مَّا هُم بِبَٰلِغِيهِ  فَاسْتَعِذْ بِاللَّهِ  إِنَّهُۥ هُوَ السَّمِيعُ الْبَصِيرُ",
    "لَخَلْقُ السَّمَٰوَٰتِ وَالْأَرْضِ أَكْبَرُ مِنْ خَلْقِ النَّاسِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ",
    "وَمَا يَسْتَوِى الْأَعْمَىٰ وَالْبَصِيرُ وَالَّذِينَ ءَامَنُوا وَعَمِلُوا الصَّٰلِحَٰتِ وَلَا الْمُسِىٓءُ  قَلِيلًا مَّا تَتَذَكَّرُونَ",
    "إِنَّ السَّاعَةَ لََٔاتِيَةٌ لَّا رَيْبَ فِيهَا وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ",
    "وَقَالَ رَبُّكُمُ ادْعُونِىٓ أَسْتَجِبْ لَكُمْ  إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ",
    "اللَّهُ الَّذِى جَعَلَ لَكُمُ الَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا  إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ",
    "ذَٰلِكُمُ اللَّهُ رَبُّكُمْ خَٰلِقُ كُلِّ شَىْءٍ لَّآ إِلَٰهَ إِلَّا هُوَ  فَأَنَّىٰ تُؤْفَكُونَ",
    "كَذَٰلِكَ يُؤْفَكُ الَّذِينَ كَانُوا بَِٔايَٰتِ اللَّهِ يَجْحَدُونَ",
    "اللَّهُ الَّذِى جَعَلَ لَكُمُ الْأَرْضَ قَرَارًا وَالسَّمَآءَ بِنَآءً وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُم مِّنَ الطَّيِّبَٰتِ  ذَٰلِكُمُ اللَّهُ رَبُّكُمْ  فَتَبَارَكَ اللَّهُ رَبُّ الْعَٰلَمِينَ",
    "هُوَ الْحَىُّ لَآ إِلَٰهَ إِلَّا هُوَ فَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ  الْحَمْدُ لِلَّهِ رَبِّ الْعَٰلَمِينَ",
    "۞ قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ لَمَّا جَآءَنِىَ الْبَيِّنَٰتُ مِن رَّبِّى وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ الْعَٰلَمِينَ",
    "هُوَ الَّذِى خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا أَشُدَّكُمْ ثُمَّ لِتَكُونُوا شُيُوخًا  وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبْلُ  وَلِتَبْلُغُوٓا أَجَلًا مُّسَمًّى وَلَعَلَّكُمْ تَعْقِلُونَ",
    "هُوَ الَّذِى يُحْىِۦ وَيُمِيتُ  فَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ",
    "أَلَمْ تَرَ إِلَى الَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ اللَّهِ أَنَّىٰ يُصْرَفُونَ",
    "الَّذِينَ كَذَّبُوا بِالْكِتَٰبِ وَبِمَآ أَرْسَلْنَا بِهِۦ رُسُلَنَا  فَسَوْفَ يَعْلَمُونَ",
    "إِذِ الْأَغْلَٰلُ فِىٓ أَعْنَٰقِهِمْ وَالسَّلَٰسِلُ يُسْحَبُونَ",
    "فِى الْحَمِيمِ ثُمَّ فِى النَّارِ يُسْجَرُونَ",
    "ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ",
    "مِن دُونِ اللَّهِ  قَالُوا ضَلُّوا عَنَّا بَل لَّمْ نَكُن نَّدْعُوا مِن قَبْلُ شَئًْا  كَذَٰلِكَ يُضِلُّ اللَّهُ الْكَٰفِرِينَ",
    "ذَٰلِكُم بِمَا كُنتُمْ تَفْرَحُونَ فِى الْأَرْضِ بِغَيْرِ الْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ",
    "ادْخُلُوٓا أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا  فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ",
    "فَاصْبِرْ إِنَّ وَعْدَ اللَّهِ حَقٌّ  فَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ",
    "وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ  وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بَِٔايَةٍ إِلَّا بِإِذْنِ اللَّهِ  فَإِذَا جَآءَ أَمْرُ اللَّهِ قُضِىَ بِالْحَقِّ وَخَسِرَ هُنَالِكَ الْمُبْطِلُونَ",
    "اللَّهُ الَّذِى جَعَلَ لَكُمُ الْأَنْعَٰمَ لِتَرْكَبُوا مِنْهَا وَمِنْهَا تَأْكُلُونَ",
    "وَلَكُمْ فِيهَا مَنَٰفِعُ وَلِتَبْلُغُوا عَلَيْهَا حَاجَةً فِى صُدُورِكُمْ وَعَلَيْهَا وَعَلَى الْفُلْكِ تُحْمَلُونَ",
    "وَيُرِيكُمْ ءَايَٰتِهِۦ فَأَىَّ ءَايَٰتِ اللَّهِ تُنكِرُونَ",
    "أَفَلَمْ يَسِيرُوا فِى الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَٰقِبَةُ الَّذِينَ مِن قَبْلِهِمْ  كَانُوٓا أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً وَءَاثَارًا فِى الْأَرْضِ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا يَكْسِبُونَ",
    "فَلَمَّا جَآءَتْهُمْ رُسُلُهُم بِالْبَيِّنَٰتِ فَرِحُوا بِمَا عِندَهُم مِّنَ الْعِلْمِ وَحَاقَ بِهِم مَّا كَانُوا بِهِۦ يَسْتَهْزِءُونَ",
    "فَلَمَّا رَأَوْا بَأْسَنَا قَالُوٓا ءَامَنَّا بِاللَّهِ وَحْدَهُۥ وَكَفَرْنَا بِمَا كُنَّا بِهِۦ مُشْرِكِينَ",
    "فَلَمْ يَكُ يَنفَعُهُمْ إِيمَٰنُهُمْ لَمَّا رَأَوْا بَأْسَنَا  سُنَّتَ اللَّهِ الَّتِى قَدْ خَلَتْ فِى عِبَادِهِۦ  وَخَسِرَ هُنَالِكَ الْكَٰفِرُونَ",
  ],
};
